{"command":"mkdir -p /tmp/work && cat > /tmp/work/extract.py <<'EOF'
import re, json
def parse(path, long):
    lines = open(path).read().split('\n')
    # find sections
    res = {}
    i = 0
    cur = None
    order = []
    while i < len(lines):
        l = lines[i]
        m = re.match(r'^  (-\w, )?(--[\w-]+)?(.*)$', l) if (l.startswith('  ') and not l.startswith('          ')) else None
        if m and (l.startswith('  -') or l.startswith('      --') or l.startswith('  <') or l.startswith('  [')):
            if long:
                key = l.strip()
                cur = key
                order.append(key)
                res[key] = []
            else:
                # short: split at 2+ spaces after the spec
                mm = re.match(r'^(  .*?)(\s{2,})(\S.*)$', l)
                if mm and not l.startswith('  <') and not l.startswith('  ['):
                    key = mm.group(1).strip()
                    res[key] = [mm.group(3)]
                elif mm:
                    key = mm.group(1).strip(); res[key] = [mm.group(3)]
                else:
                    key = l.strip(); res[key] = []
                cur = key
                order.append(key)
        elif l.startswith('          ') or (long and l == '          '):
            res[cur].append(l[10:])
        elif l == '' :
            cur = None if long else cur
        i += 1
    return res, order
s, so = parse('/tmp/help_short_wide.txt', False)
l, lo = parse('/tmp/help_long_wide.txt', True)
json.dump({'short': s, 'short_order': so, 'long': l, 'long_order': lo}, open('/tmp/work/help.json','w'), indent=1)
for k in lo:
    print(repr(k), '|', repr(s.get(k)), '|', repr('\n'.join(l[k]))[:100])
EOF
python3 /tmp/work/extract.py"}

