{"command":"cd /workspace; cat > cli_defs.go <<'EOF'
package main

// Argument definitions mirroring the observed command line interface.

type ArgAction int

const (
	ActSetTrue ArgAction = iota
	ActCount
	ActSet
	ActAppend
	ActHelpShort
	ActVersion
)

type ArgDef struct {
	ID             string
	Short          rune
	Long           string
	ValueName      string
	Action         ArgAction
	Possible       []string
	Hidden         bool
	Positional     bool
	Index          int
	Required       bool
	RequiredUnless []string
	Overrides      []string
	Conflicts      []string
	Requires       []string
	Validate       func(string) error
	Help           string
	LongHelp       string
	InGroup        bool
	Multiple       bool
}

func (a *ArgDef) TakesValue() bool {
	return a.Action == ActSet || a.Action == ActAppend
}

// Display mirrors clap's Arg Display impl.
func (a *ArgDef) String() string {
	return a.stylized(nil)
}

// stylized renders the arg; required overrides the positional requiredness.
func (a *ArgDef) stylized(required *bool) string {
	s := ""
	if a.Long != "" {
		s = "--" + a.Long
	} else if a.Short != 0 {
		s = "-" + string(a.Short)
	}
	return s + a.suffix(required)
}

func (a *ArgDef) suffix(required *bool) string {
	s := ""
	if a.TakesValue() && !a.Positional {
		s += " "
	}
	if a.TakesValue() || a.Positional {
		req := a.Required
		if required != nil {
			req = *required
		}
		name := a.ValueName
		if a.Positional && !req {
			s += "[" + name + "]"
		} else {
			s += "<" + name + ">"
		}
		if a.Positional && a.Action == ActAppend {
			s += "..."
		}
	} else if a.Action == ActCount {
		s += "..."
	}
	return s
}

func (a *ArgDef) nameNoBrackets() string {
	return a.ValueName
}

var argDefs []*ArgDef
var argByID = map[string]*ArgDef{}
var argByLong = map[string]*ArgDef{}
var argByShort = map[rune]*ArgDef{}
var longOrder []string

func ht(name string) (string, string) {
	t, ok := helpTexts[name]
	if !ok {
		return "", ""
	}
	return t[0], t[1]
}

func init() {
	type d struct {
		id, long  string
		short     rune
		vname     string
		act       ArgAction
		pv        []string
		hidden    bool
		overrides []string
		conflicts []string
		requires  []string
		validate  func(string) error
		help      string
	}
	defs := []d{
		{id: "json", long: "json", short: 'j', act: ActSetTrue, overrides: []string{"form", "multipart"}},
		{id: "form", long: "form", short: 'f', act: ActSetTrue, overrides: []string{"json", "multipart"}},
		{id: "multipart", long: "multipart", act: ActSetTrue, overrides: []string{"json", "form"}, conflicts: []string{"raw", "compress"}},
		{id: "raw", long: "raw", vname: "RAW", act: ActSet},
		{id: "pretty", long: "pretty", vname: "STYLE", act: ActSet, pv: []string{"all", "colors", "format", "none"}},
		{id: "format_options", long: "format-options", vname: "FORMAT_OPTIONS", act: ActAppend, validate: validateFormatOptions},
		{id: "style", long: "style", short: 's', vname: "THEME", act: ActSet, pv: []string{"auto", "solarized", "monokai", "fruity"}},
		{id: "response_charset", long: "response-charset", vname: "ENCODING", act: ActSet, validate: validateCharset},
		{id: "response_mime", long: "response-mime", vname: "MIME_TYPE", act: ActSet},
		{id: "print", long: "print", short: 'p', vname: "FORMAT", act: ActSet},
		{id: "headers", long: "headers", short: 'h', act: ActSetTrue},
		{id: "body", long: "body", short: 'b', act: ActSetTrue},
		{id: "meta", long: "meta", short: 'm', act: ActSetTrue},
		{id: "verbose", long: "verbose", short: 'v', act: ActCount},
		{id: "debug", long: "debug", act: ActSetTrue},
		{id: "all", long: "all", act: ActSetTrue},
		{id: "history_print", long: "history-print", short: 'P', vname: "FORMAT", act: ActSet},
		{id: "quiet", long: "quiet", short: 'q', act: ActCount},
		{id: "stream", long: "stream", short: 'S', act: ActSetTrue},
		{id: "compress", long: "compress", short: 'x', act: ActCount},
		{id: "output", long: "output", short: 'o', vname: "FILE", act: ActSet},
		{id: "download", long: "download", short: 'd', act: ActSetTrue},
		{id: "resume", long: "continue", short: 'c', act: ActSetTrue, requires: []string{"download", "output"}},
		{id: "session", long: "session", vname: "FILE", act: ActSet, conflicts: []string{"session_read_only"}},
		{id: "session_read_only", long: "session-read-only", vname: "FILE", act: ActSet},
		{id: "auth_type", long: "auth-type", short: 'A', vname: "AUTH_TYPE", act: ActSet, pv: []string{"basic", "bearer", "digest"}},
		{id: "auth", long: "auth", short: 'a', vname: "USER[:PASS] | TOKEN", act: ActSet},
		{id: "bearer", long: "bearer", vname: "TOKEN", act: ActSet, hidden: true, help: "Authenticate with a bearer token"},
		{id: "ignore_netrc", long: "ignore-netrc", act: ActSetTrue},
		{id: "offline", long: "offline", act: ActSetTrue},
		{id: "check_status", long: "check-status", act: ActSetTrue},
		{id: "follow", long: "follow", short: 'F', act: ActSetTrue},
		{id: "max_redirects", long: "max-redirects", vname: "NUM", act: ActSet, validate: validateUsize},
		{id: "timeout", long: "timeout", vname: "SEC", act: ActSet, validate: validateTimeout},
		{id: "proxy", long: "proxy", vname: "PROTOCOL:URL", act: ActAppend, validate: validateProxy},
		{id: "verify", long: "verify", vname: "VERIFY", act: ActSet},
		{id: "cert", long: "cert", vname: "FILE", act: ActSet},
		{id: "cert_key", long: "cert-key", vname: "FILE", act: ActSet},
		{id: "ssl", long: "ssl", vname: "VERSION", act: ActSet, pv: []string{"auto", "tls1", "tls1.1", "tls1.2", "tls1.3"}},
		{id: "native_tls", long: "native-tls", act: ActSetTrue, hidden: true, help: "Use the system TLS library instead of rustls (if enabled at compile time)"},
		{id: "default_scheme", long: "default-scheme", vname: "SCHEME", act: ActSet, hidden: true, help: "The default scheme to use if not specified in the URL"},
		{id: "https", long: "https", act: ActSetTrue},
		{id: "http_version", long: "http-version", vname: "VERSION", act: ActSet, pv: []string{"1.0", "1.1", "2", "2-prior-knowledge", "3-prior-knowledge"}},
		{id: "resolve", long: "resolve", vname: "HOST:ADDRESS", act: ActAppend, validate: validateResolve},
		{id: "interface", long: "interface", vname: "NAME", act: ActSet},
		{id: "ipv4", long: "ipv4", short: '4', act: ActSetTrue},
		{id: "ipv6", long: "ipv6", short: '6', act: ActSetTrue},
		{id: "unix_socket", long: "unix-socket", vname: "FILE", act: ActSet},
		{id: "ignore_stdin", long: "ignore-stdin", short: 'I', act: ActSetTrue},
		{id: "curl", long: "curl", act: ActSetTrue},
		{id: "curl_long", long: "curl-long", act: ActSetTrue},
		{id: "generate", long: "generate", vname: "KIND", act: ActSet, pv: []string{"complete-bash", "complete-elvish", "complete-fish", "complete-nushell", "complete-powershell", "complete-zsh", "man"}, conflicts: []string{"raw_method_or_url"}},
		{id: "help", long: "help", act: ActHelpShort},
	}
	for _, x := range defs {
		a := &ArgDef{ID: x.id, Long: x.long, Short: x.short, ValueName: x.vname, Action: x.act, Possible: x.pv,
			Hidden: x.hidden, Overrides: x.overrides, Conflicts: x.conflicts, Requires: x.requires, Validate: x.validate, InGroup: true}
		a.Help, a.LongHelp = ht(x.long)
		if x.help != "" {
			a.Help = x.help
			a.LongHelp = x.help
		}
		if a.Action == ActAppend {
			a.Multiple = true
		}
		argDefs = append(argDefs, a)
	}
	url := &ArgDef{ID: "raw_method_or_url", ValueName: "[METHOD] URL", Action: ActSet, Positional: true, Index: 1, Required: true,
		RequiredUnless: []string{"generate"}, InGroup: true}
	url.Help, url.LongHelp = ht("raw_method_or_url")
	rest := &ArgDef{ID: "raw_rest_args", ValueName: "REQUEST_ITEM", Action: ActAppend, Positional: true, Index: 2, InGroup: true, Multiple: true}
	rest.Help, rest.LongHelp = ht("raw_rest_args")
	argDefs = append(argDefs, url, rest)

	// negations
	n := len(defs)
	for i := 0; i < n; i++ {
		orig := argDefs[i]
		neg := &ArgDef{ID: "no-" + orig.Long, Long: "no-" + orig.Long, Action: ActSetTrue, Hidden: true, Overrides: []string{orig.ID}}
		argDefs = append(argDefs, neg)
	}
	ver := &ArgDef{ID: "version", Long: "version", Short: 'V', Action: ActVersion}
	ver.Help, ver.LongHelp = ht("version")
	argDefs = append(argDefs, ver)

	for _, a := range argDefs {
		argByID[a.ID] = a
		if a.Long != "" {
			argByLong[a.Long] = a
			longOrder = append(longOrder, a.Long)
		}
		if a.Short != 0 {
			argByShort[a.Short] = a
		}
	}
}

// Ordering of options in help output (definition order, excluding positionals and hidden ones).
func visibleOptions() []*ArgDef {
	var out []*ArgDef
	for _, a := range argDefs {
		if a.Positional || a.Hidden {
			continue
		}
		out = append(out, a)
	}
	return out
}

func positionals() []*ArgDef {
	return []*ArgDef{argByID["raw_method_or_url"], argByID["raw_rest_args"]}
}
EOF
echo ok"}

