func (p *cliParser) react(a *ArgDef, vals []string, ident identKind) error {
	if err := p.resolvePending(); err != nil {
		return err
	}
	if a.TakesValue() && len(vals) == 0 {
		return p.emptyValueError(a)
	}
	switch a.Action {
	case ActSet:
		p.m.remove(a.ID)
		e := p.startArg(a)
		for _, v := range vals {
			if err := p.validateValue(a, v); err != nil {
				return err
			}
			e.vals = append(e.vals, v)
		}
	case ActAppend:
		e := p.startArg(a)
		for _, v := range vals {
			if err := p.validateValue(a, v); err != nil {
				return err
			}
			e.vals = append(e.vals, v)
		}
	case ActSetTrue:
		p.m.remove(a.ID)
		e := p.startArg(a)
		e.vals = []string{"true"}
	case ActCount:
		prev := p.m.Count(a.ID)
		p.m.remove(a.ID)
		e := p.startArg(a)
		if prev < 255 {
			prev++
		}
		e.count = prev
	case ActHelpShort:
		return &ClapError{Message: renderHelp(p.binName, false), ExitCode: 0, ToStdout: true}
	case ActVersion:
		if ident == identLong {
			return &ClapError{Message: "xh " + xhVersion + "\n" + longVersionExtra + "\n", ExitCode: 0, ToStdout: true}
