}

func (p *cliParser) validateValue(a *ArgDef, v string) error {
	if len(a.Possible) > 0 {
		for _, pv := range a.Possible {
			if pv == v {
				return nil
			}
		}
		return p.invalidValueError(a, v)
	}
	if a.Validate != nil {
		if err := a.Validate(v); err != nil {
			return p.valueValidationError(a, v, err.Error())
		}
	}
	return nil
}

func (p *cliParser) pendingValuesMut(id string, ident identKind) *pendingArg {
	if p.m.pending == nil {
		p.m.pending = &pendingArg{id: id, ident: ident}
	}
	return p.m.pending
}

func parseCLI(binName string, args []string) (*Matches, error) {
	p := &cliParser{m: &Matches{}, binName: binName}
	trailing := false
	posCounter := 1
	state := stNone
	stateID := ""
	for i := 0; i < len(args); i++ {
		a := args[i]
		if !trailing {
			if a == "--" {
				trailing = true
				continue
			}
			if strings.HasPrefix(a, "--") {
				body := a[2:]
				name, val, hasVal := strings.Cut(body, "=")
				def := argByLong[name]
				if def == nil {
					_ = p.resolvePending()
					return nil, p.didYouMeanError(name, trailing)
				}
				if def.TakesValue() {
					if hasVal {
						if err := p.react(def, []string{val}, identLong); err != nil {
							return nil, err
						}
						state = stValuesDone
					} else {
						if err := p.resolvePending(); err != nil {
							return nil, err
						}
						p.pendingValuesMut(def.ID, identLong)
						state = stOpt
						stateID = def.ID
					}
					continue
				}
				if hasVal {
					// UnneededAttachedValue
					var used []string
					for _, e := range p.m.entries {
						if e.isGroup {
							used = append(used, e.id)
							continue
						}
						ad := argByID[e.id]
						if ad.Hidden || ad.Required {
							continue
						}
						used = append(used, e.id)
					}
					used = append(used, def.ID)
					_ = p.resolvePending()
					return nil, p.tooManyValuesError(val, def, used)
				}
				if err := p.react(def, nil, identLong); err != nil {
					return nil, err
				}
				state = stValuesDone
				continue
			} else if strings.HasPrefix(a, "-") && a != "-" {
				chars := []rune(a[1:])
				done := false
				for idx := 0; idx < len(chars); idx++ {
					c := chars[idx]
					def := argByShort[c]
					if def == nil {
						_ = p.resolvePending()
						return nil, p.unknownShortError("-"+string(c), trailing)
					}
					if !def.TakesValue() {
						if err := p.react(def, nil, identShort); err != nil {
							return nil, err
						}
						state = stValuesDone
						continue
					}
					rest := string(chars[idx+1:])
					if rest != "" {
						rest = strings.TrimPrefix(rest, "=")
						if err := p.react(def, []string{rest}, identShort); err != nil {
							return nil, err
						}
						state = stValuesDone
					} else {
						if err := p.resolvePending(); err != nil {
							return nil, err
						}
						p.pendingValuesMut(def.ID, identShort)
						state = stOpt
						stateID = def.ID
					}
					done = true
					break
				}
				_ = done
				continue
			}
			if state == stOpt {
				pd := p.pendingValuesMut(stateID, identNone)
				pd.vals = append(pd.vals, a)
				state = stValuesDone
				continue
			}
		}
		// positional
		var pos *ArgDef
		for _, pa := range positionals() {
			if pa.Index == posCounter {
				pos = pa
			}
		}
		if pos == nil {
			_ = p.resolvePending()
			return nil, p.unknownShortError(a, trailing)
		}
		if p.m.pending == nil || p.m.pending.id != pos.ID || !pos.Multiple {
			if err := p.resolvePending(); err != nil {
				return nil, err
			}
		}
		pd := p.pendingValuesMut(pos.ID, identIndex)
		pd.vals = append(pd.vals, a)
		if !pos.Multiple {
			posCounter++
			state = stValuesDone
		} else {
			state = stPos
			stateID = pos.ID
		}
	}
	if err := p.resolvePending(); err != nil {
		return nil, err
	}
	if err := p.validateConflicts(); err != nil {
		return nil, err
	}
	if err := p.validateRequired(); err != nil {
		return nil, err
	}
	return p.m, nil
}

func (p *cliParser) explicitArgs() []string {
	var out []string
	for _, e := range p.m.entries {
		if !e.isGroup {
			out = append(out, e.id)
		}
	}
	return out
}

func (p *cliParser) directConflicts(id string) []string {
	a := argByID[id]
	if a == nil {
		return nil
	}
	return a.Conflicts
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func (p *cliParser) validateConflicts() error {
	present := p.explicitArgs()
	for _, id := range present {
		var conflicts []string
		mine := p.directConflicts(id)
		for _, other := range present {
			if other == id {
				continue
			}
			if contains(mine, other) {
				conflicts = append(conflicts, other)
			}
			if contains(p.directConflicts(other), id) {
				conflicts = append(conflicts, other)
			}
		}
		if len(conflicts) == 0 {
			continue
		}
		var names []string
		seen := map[string]bool{}
		for _, c := range conflicts {
			if seen[c] {
				continue
			}
			seen[c] = true
			names = append(names, argByID[c].String())
		}
		// usage
		var usedFiltered []string
		for _, u := range present {
			if argByID[u].Hidden {
				continue
			}
			if contains(conflicts, u) {
				continue
			}
			usedFiltered = append(usedFiltered, u)
		}
		var required []string
		for _, u := range usedFiltered {
			for _, r := range argByID[u].Requires {
				if !contains(usedFiltered, r) && !contains(conflicts, r) {
					required = append(required, r)
				}
			}
		}
		required = append(required, usedFiltered...)
		usage := p.usage(required, nil)
		msg := "the argument '" + argByID[id].String() + "' cannot be used"
		if len(names) == 1 {
			msg += " with '" + names[0] + "'"
		} else {
			msg += " with:"
			for _, n := range names {
				msg += "\n  " + n
			}
		}
		return p.formatError(msg, "", nil, usage)
	}
	return nil
}

func (p *cliParser) isPresent(id string) bool {
	return p.m.get(id) != nil
}

func (p *cliParser) validateRequired() error {
	var required []string
	for _, a := range argDefs {
		if a.Required {
			required = append(required, a.ID)
		}
	}
	for _, id := range p.explicitArgs() {
		for _, r := range argByID[id].Requires {
			if !contains(required, r) {
				required = append(required, r)
			}
		}
	}
	var missing []string
	for _, r := range required {
		if p.isPresent(r) {
			continue
		}
		a := argByID[r]
		ok := false
		for _, u := range a.RequiredUnless {
			if p.isPresent(u) {
				ok = true
			}
		}
		if ok {
			continue
		}
		missing = append(missing, r)
	}
	if len(missing) == 0 {
		return nil
	}
	// list of missing args: opts first, then positionals
	var opts, poss []string
	for _, r := range append(append([]string{}, required...), missing...) {
		if p.isPresent(r) {
			continue
		}
		if !contains(missing, r) {
			continue
		}
		a := argByID[r]
		t := true
		s := a.stylized(&t)
		if a.Positional {
			if !contains(poss, s) {
				poss = append(poss, s)
			}
		} else if !contains(opts, s) {
			opts = append(opts, s)
		}
	}
	list := append(opts, poss...)
	var used []string
	for _, id := range p.explicitArgs() {
		if argByID[id].Hidden {
			continue
		}
		used = append(used, id)
	}
	used = append(used, missing...)
	usage := p.usage(used, required)
	msg := "the following required arguments were not provided:"
	for _, l := range list {
		msg += "\n  " + l
	}
	return p.formatError(msg, "", nil, usage)
}

// usage renders "Usage: ..." given used ids (incls) and required list (nil => required graph).
func (p *cliParser) usage(used []string, required []string) string {
	return renderUsage(p.binName, used, required)
}

func renderUsage(binName string, used []string, required []string) string {
	parts := []string{binName}
	if len(used) == 0 {
		parts = append(parts, "[OPTIONS]")
	}
	if required == nil {
		for _, a := range argDefs {
			if a.Required {
				required = append(required, a.ID)
			}
		}
	}
	var unrolled []string
	for _, r := range required {
		for _, rr := range argByID[r].Requires {
			unrolled = append(unrolled, rr)
		}
		unrolled = append(unrolled, r)
	}
	all := append(append([]string{}, unrolled...), used...)
	var groups []string
	groupMembers := map[string]bool{}
	for _, r := range all {
		if r == "Cli" {
			if !contains(groups, "Cli") {
				groups = append(groups, "Cli")
			}
			for _, a := range argDefs {
				if a.InGroup {
					groupMembers[a.ID] = true
				}
			}
		}
	}
	var opts []string
	posVals := map[int]string{}
	for _, r := range all {
		if r == "Cli" {
			continue
		}
		a := argByID[r]
		if groupMembers[a.ID] {
			continue
		}
		t := true
		s := a.stylized(&t)
		if a.Positional {
			posVals[a.Index] = s
		} else if !contains(opts, s) {
			opts = append(opts, s)
		}
	}
	for _, pa := range positionals() {
		if pa.Hidden || groupMembers[pa.ID] {
			continue
		}
		if _, ok := posVals[pa.Index]; !ok {
			f := false
			posVals[pa.Index] = pa.stylized(&f)
		}
	}
	for _, g := range groups {
		_ = g
		var names []string
		for _, a := range argDefs {
			if !a.InGroup {
				continue
			}
			if a.Positional {
				names = append(names, a.nameNoBrackets())
			} else {
				names = append(names, a.String())
			}
		}
		parts = append(parts, "<"+strings.Join(names, "|")+">")
	}
	parts = append(parts, opts...)
	var idxs []int
	for k := range posVals {
		idxs = append(idxs, k)
	}
	sort.Ints(idxs)
	for _, k := range idxs {
		parts = append(parts, posVals[k])
	}
	return "Usage: " + strings.Join(parts, " ")
}

func helpUsage(binName string) string {
	return renderUsage(binName, nil, nil)
}

// formatError renders a clap-style error.
// tips: suggestion lines (already formatted without the "  tip: " prefix)
func (p *cliParser) formatError(msg string, similar string, tips []string, usage string) error {
	return &ClapError{Message: formatClapError(msg, similar, tips, usage), ExitCode: 2}
}

func formatClapError(msg string, similar string, tips []string, usage string) string {
	s := "error: " + msg
	suggested := false
	if similar != "" {
		s += "\n\n" + similar
		suggested = true
	}
	if len(tips) > 0 {
		if !suggested {
			s += "\n"
		}
		for _, t := range tips {
			s += "\n  tip: " + t
		}
	}
	if usage != "" {
		s += "\n\n" + usage
	}
	s += "\n\nFor more information, try '--help'.\n"
	return s
}

func (p *cliParser) emptyValueError(a *ArgDef) error {
	msg := "a value is required for '" + a.String() + "' but none was supplied"
	if len(a.Possible) > 0 {
		msg += "\n  [possible values: " + strings.Join(escapeVals(a.Possible), ", ") + "]"
	}
	return p.formatError(msg, "", nil, "")
}

func escapeVals(vs []string) []string {
	var out []string
	for _, v := range vs {
		if strings.ContainsAny(v, " ") {
			out = append(out, "\""+v+"\"")
		} else {
			out = append(out, v)
		}
	}
	return out
}

func (p *cliParser) invalidValueError(a *ArgDef, v string) error {
	if v == "" {
		return p.emptyValueError(a)
	}
	msg := "invalid value '" + v + "' for '" + a.String() + "'"
	msg += "\n  [possible values: " + strings.Join(escapeVals(a.Possible), ", ") + "]"
	similar := ""
	if s := didYouMean(v, a.Possible); s != "" {
		similar = "  tip: a similar value exists: '" + s + "'"
	}
	return p.formatError(msg, similar, nil, "")
}

func (p *cliParser) valueValidationError(a *ArgDef, v string, e string) error {
	msg := "invalid value '" + v + "' for '" + a.String() + "': " + e
	return p.formatError(msg, "", nil, "")
}

func (p *cliParser) tooManyValuesError(val string, a *ArgDef, used []string) error {
	msg := "unexpected value '" + val + "' for '" + a.String() + "' found; no more were expected"
	return p.formatError(msg, "", nil, p.usage(used, nil))
}

func (p *cliParser) unknownShortError(arg string, trailing bool) error {
	msg := "unexpected argument '" + arg + "' found"
	var tips []string
	if !trailing {
		tips = append(tips, "to pass '"+arg+"' as a value, use '-- "+arg+"'")
	}
	return p.formatError(msg, "", tips, helpUsage(p.binName))
}

func (p *cliParser) didYouMeanError(name string, trailing bool) error {
	cand := didYouMean(name, longOrder)
	if cand != "" {
		if def := argByLong[cand]; def != nil {
			p.startArg(def)
		}
	}
	var used []string
	for _, e := range p.m.entries {
		if e.isGroup {
			continue
		}
		if argByID[e.id].Hidden {
			continue
		}
		used = append(used, e.id)
	}
	arg := "--" + name
	msg := "unexpected argument '" + arg + "' found"
	similar := ""
	var tips []string
	if cand != "" {
		similar = "  tip: a similar argument exists: '--" + cand + "'"
	} else if !trailing {
		tips = append(tips, "to pass '"+arg+"' as a value, use '-- "+arg+"'")
	}
	return p.formatError(msg, similar, tips, p.usage(used, nil))
}

// didYouMean returns the best candidate with jaro similarity > 0.7.
func didYouMean(v string, candidates []string) string {
	best := ""
	bestScore := -1.0
	for _, c := range candidates {
		s := jaro(v, c)
		if s > 0.7 && s >= bestScore {
			best = c
			bestScore = s
		}
	}
	return best
}

func jaro(a, b string) float64 {
	ar := []rune(a)
	br := []rune(b)
	al, bl := len(ar), len(br)
	if al == 0 && bl == 0 {
		return 1.0
	}
	if al == 0 || bl == 0 {
		return 0.0
	}
	sr := al
	if bl > sr {
		sr = bl
	}
	sr = sr / 2
	if sr > 0 {
		sr--
	}
	af := make([]bool, al)
	bf := make([]bool, bl)
	matches := 0
	for i := 0; i < al; i++ {
		minB := 0
		if i > sr {
			minB = i - sr
		}
		maxB := i + sr + 1
		if maxB > bl {
			maxB = bl
		}
		for j := minB; j < maxB; j++ {
			if ar[i] == br[j] && !bf[j] {
				af[i] = true
				bf[j] = true
				matches++
				break
			}
		}
	}
	if matches == 0 {
		return 0.0
	}
	trans := 0
	j := 0
	for i := 0; i < al; i++ {
		if af[i] {
			for !bf[j] {
				j++
			}
			if ar[i] != br[j] {
				trans++
			}
			j++
		}
	}
	trans /= 2
	m := float64(matches)
	return (m/float64(al) + m/float64(bl) + (m-float64(trans))/m) / 3.0
}
EOF
echo ok"}

actions.command:
cd /workspace; cat > cli_parse.go <<'EOF'
package main

import (
	"sort"
	"strings"
)

type identKind int

const (
	identNone identKind = iota
	identShort
	identLong
	identIndex
)

type matchEntry struct {
	id      string
	vals    []string
	count   int
	isGroup bool
}

type pendingArg struct {
	id    string
	ident identKind
	vals  []string
}

type Matches struct {
	entries []*matchEntry
	pending *pendingArg
}

func (m *Matches) get(id string) *matchEntry {
	for _, e := range m.entries {
		if e.id == id {
			return e
		}
	}
	return nil
}

func (m *Matches) remove(id string) bool {
	for i, e := range m.entries {
		if e.id == id {
			m.entries = append(m.entries[:i], m.entries[i+1:]...)
			return true
		}
	}
	return false
}

func (m *Matches) Has(id string) bool { return m.get(id) != nil }

func (m *Matches) Flag(id string) bool { return m.get(id) != nil }

func (m *Matches) Count(id string) int {
	e := m.get(id)
	if e == nil {
		return 0
	}
	return e.count
}

func (m *Matches) Value(id string) (string, bool) {
	e := m.get(id)
	if e == nil || len(e.vals) == 0 {
		return "", false
	}
	return e.vals[len(e.vals)-1], true
}

func (m *Matches) Values(id string) []string {
	e := m.get(id)
	if e == nil {
		return nil
	}
	return e.vals
}

// ClapError is a command line parsing error (or help/version display).
type ClapError struct {
	Message  string // full rendered text
	ExitCode int
	ToStdout bool
}

func (e *ClapError) Error() string { return e.Message }

type parseState int

const (
	stNone parseState = iota
	stOpt
	stPos
	stValuesDone
)

type cliParser struct {
	m       *Matches
	binName string
}

func (p *cliParser) startArg(a *ArgDef) *matchEntry {
	p.removeOverrides(a)
	e := p.m.get(a.ID)
	if e == nil {
		e = &matchEntry{id: a.ID}
		p.m.entries = append(p.m.entries, e)
	}
	if a.InGroup {
		if p.m.get("Cli") == nil {
			p.m.entries = append(p.m.entries, &matchEntry{id: "Cli", isGroup: true})
		}
	}
	return e
}

func (p *cliParser) removeOverrides(a *ArgDef) {
	for _, o := range a.Overrides {
		p.m.remove(o)
	}
	var trans []string
	for _, e := range p.m.entries {
		if e.isGroup {
			continue
		}
		other := argByID[e.id]
		if other == nil {
			continue
		}
		for _, o := range other.Overrides {
			if o == a.ID {
				trans = append(trans, other.ID)
			}
		}
	}
	for _, t := range trans {
		p.m.remove(t)
	}
}

func (p *cliParser) resolvePending() error {
	pd := p.m.pending
	if pd == nil {
		return nil
	}
	p.m.pending = nil
	a := argByID[pd.id]
	return p.react(a, pd.vals, pd.ident)
}

func (p *cliParser) react(a *ArgDef, vals []string, ident identKind) error {
	if err := p.resolvePending(); err != nil {
		return err
	}
	if a.TakesValue() && len(vals) == 0 {
		return p.emptyValueError(a)
	}
	switch a.Action {
	case ActSet:
		p.m.remove(a.ID)
		e := p.startArg(a)
		for _, v := range vals {
			if err := p.validateValue(a, v); err != nil {
				return err
			}
			e.vals = append(e.vals, v)
		}
	case ActAppend:
		e := p.startArg(a)
		for _, v := range vals {
			if err := p.validateValue(a, v); err != nil {
				return err
			}
			e.vals = append(e.vals, v)
		}
	case ActSetTrue:
		p.m.remove(a.ID)
		e := p.startArg(a)
		e.vals = []string{"true"}
	case ActCount:
		prev := p.m.Count(a.ID)
		p.m.remove(a.ID)
		e := p.startArg(a)
		if prev < 255 {
			prev++
		}
		e.count = prev
	case ActHelpShort:
		return &ClapError{Message: renderHelp(p.binName, false), ExitCode: 0, ToStdout: true}
	case ActVersion:
		if ident == identLong {
			return &ClapError{Message: "xh " + xhVersion + "\n" + longVersionExtra + "\n", ExitCode: 0, ToStdout: true}
		}
		return &ClapError{Message: "xh " + xhVersion + "\n", ExitCode: 0, ToStdout: true}
	}
	return nil
}

func (p *cliParser) validateValue(a *ArgDef, v string) error {
	if len(a.Possible) > 0 {
		for _, pv := range a.Possible {
			if pv == v {
				return nil
			}
		}
		return p.invalidValueError(a, v)
	}
	if a.Validate != nil {
		if err := a.Validate(v); err != nil {
			return p.valueValidationError(a, v, err.Error())
		}
	}
	return nil
}

func (p *cliParser) pendingValuesMut(id string, ident identKind) *pendingArg {
	if p.m.pending == nil {
		p.m.pending = &pendingArg{id: id, ident: ident}
	}
	return p.m.pending
}

func parseCLI(binName string, args []string) (*Matches, error) {
	p := &cliParser{m: &Matches{}, binName: binName}
	trailing := false
	posCounter := 1
	state := stNone
	stateID := ""
	for i := 0; i < len(args); i++ {
		a := args[i]
		if !trailing {
			if a == "--" {
				trailing = true
				continue
			}
			if strings.HasPrefix(a, "--") {
				body := a[2:]
				name, val, hasVal := strings.Cut(body, "=")
				def := argByLong[name]
				if def == nil {
					_ = p.resolvePending()
					return nil, p.didYouMeanError(name, trailing)
				}
				if def.TakesValue() {
					if hasVal {
						if err := p.react(def, []string{val}, identLong); err != nil {
							return nil, err
						}
						state = stValuesDone
					} else {
						if err := p.resolvePending(); err != nil {
							return nil, err
						}
						p.pendingValuesMut(def.ID, identLong)
						state = stOpt
						stateID = def.ID
					}
					continue
				}
				if hasVal {
					// UnneededAttachedValue
					var used []string
					for _, e := range p.m.entries {
						if e.isGroup {
							used = append(used, e.id)
							continue
						}
						ad := argByID[e.id]
						if ad.Hidden || ad.Required {
							continue
						}
						used = append(used, e.id)
					}
					used = append(used, def.ID)
					_ = p.resolvePending()
					return nil, p.tooManyValuesError(val, def, used)
				}
				if err := p.react(def, nil, identLong); err != nil {
					return nil, err
				}
				state = stValuesDone
				continue
			} else if strings.HasPrefix(a, "-") && a != "-" {
				chars := []rune(a[1:])
				done := false
				for idx := 0; idx < len(chars); idx++ {
					c := chars[idx]
					def := argByShort[c]
					if def == nil {
						_ = p.resolvePending()
						return nil, p.unknownShortError("-"+string(c), trailing)
					}
					if !def.TakesValue() {
						if err := p.react(def, nil, identShort); err != nil {
							return nil, err
						}
						state = stValuesDone
						continue
					}
					rest := string(chars[idx+1:])
					if rest != "" {
						rest = strings.TrimPrefix(rest, "=")
						if err := p.react(def, []string{rest}, identShort); err != nil {
							return nil, err
						}
						state = stValuesDone
					} else {
						if err := p.resolvePending(); err != nil {
							return nil, err
						}
						p.pendingValuesMut(def.ID, identShort)
						state = stOpt
						stateID = def.ID
					}
					done = true
					break
				}
				_ = done
				continue
			}
			if state == stOpt {
				pd := p.pendingValuesMut(stateID, identNone)
				pd.vals = append(pd.vals, a)
				state = stValuesDone
				continue
			}
		}
		// positional
		var pos *ArgDef
		for _, pa := range positionals() {
			if pa.Index == posCounter {
				pos = pa
			}
		}
		if pos == nil {
			_ = p.resolvePending()
			return nil, p.unknownShortError(a, trailing)
		}
		if p.m.pending == nil || p.m.pending.id != pos.ID || !pos.Multiple {
			if err := p.resolvePending(); err != nil {
				return nil, err
			}
		}
		pd := p.pendingValuesMut(pos.ID, identIndex)
		pd.vals = append(pd.vals, a)
		if !pos.Multiple {
			posCounter++
			state = stValuesDone
		} else {
			state = stPos
			stateID = pos.ID
		}
	}
	if err := p.resolvePending(); err != nil {
		return nil, err
	}
	if err := p.validateConflicts(); err != nil {
		return nil, err
	}
	if err := p.validateRequired(); err != nil {
		return nil, err
	}
	return p.m, nil
}

func (p *cliParser) explicitArgs() []string {
	var out []string
	for _, e := range p.m.entries {
		if !e.isGroup {
			out = append(out, e.id)
		}
	}
	return out
}

func (p *cliParser) directConflicts(id string) []string {
	a := argByID[id]
	if a == nil {
		return nil
	}
	return a.Conflicts
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func (p *cliParser) validateConflicts() error {
	present := p.explicitArgs()
	for _, id := range present {
		var conflicts []string
		mine := p.directConflicts(id)
		for _, other := range present {
			if other == id {
				continue
			}
			if contains(mine, other) {
				conflicts = append(conflicts, other)
			}
			if contains(p.directConflicts(other), id) {
				conflicts = append(conflicts, other)
			}
		}
		if len(conflicts) == 0 {
			continue
		}
		var names []string
		seen := map[string]bool{}
		for _, c := range conflicts {
			if seen[c] {
				continue
			}
			seen[c] = true
			names = append(names, argByID[c].String())
		}
		// usage
		var usedFiltered []string
		for _, u := range present {
			if argByID[u].Hidden {
				continue
			}
			if contains(conflicts, u) {
				continue
			}
			usedFiltered = append(usedFiltered, u)
		}
		var required []string
		for _, u := range usedFiltered {
			for _, r := range argByID[u].Requires {
				if !contains(usedFiltered, r) && !contains(conflicts, r) {
					required = append(required, r)
				}
			}
		}
		required = append(required, usedFiltered...)
		usage := p.usage(required, nil)
		msg := "the argument '" + argByID[id].String() + "' cannot be used"
		if len(names) == 1 {
			msg += " with '" + names[0] + "'"
		} else {
			msg += " with:"
			for _, n := range names {
				msg += "\n  " + n
			}
		}
		return p.formatError(msg, "", nil, usage)
	}
	return nil
}

func (p *cliParser) isPresent(id string) bool {
	return p.m.get(id) != nil
}

func (p *cliParser) validateRequired() error {
	var required []string
	for _, a := range argDefs {
		if a.Required {
			required = append(required, a.ID)
		}
	}
	for _, id := range p.explicitArgs() {
		for _, r := range argByID[id].Requires {
			if !contains(required, r) {
				required = append(required, r)
			}
		}
	}
	var missing []string
	for _, r := range required {
		if p.isPresent(r) {
			continue
		}
		a := argByID[r]
		ok := false
		for _, u := range a.RequiredUnless {
			if p.isPresent(u) {
				ok = true
			}
		}
		if ok {
			continue
		}
		missing = append(missing, r)
	}
	if len(missing) == 0 {
		return nil
	}
	// list of missing args: opts first, then positionals
	var opts, poss []string
	for _, r := range append(append([]string{}, required...), missing...) {
		if p.isPresent(r) {
			continue
		}
		if !contains(missing, r) {
			continue
		}
		a := argByID[r]
		t := true
		s := a.stylized(&t)
		if a.Positional {
			if !contains(poss, s) {
				poss = append(poss, s)
			}
		} else if !contains(opts, s) {
			opts = append(opts, s)
		}
	}
	list := append(opts, poss...)
	var used []string
	for _, id := range p.explicitArgs() {
		if argByID[id].Hidden {
			continue
		}
		used = append(used, id)
	}
	used = append(used, missing...)
	usage := p.usage(used, required)
	msg := "the following required arguments were not provided:"
	for _, l := range list {
		msg += "\n  " + l
	}
	return p.formatError(msg, "", nil, usage)
}

// usage renders "Usage: ..." given used ids (incls) and required list (nil => required graph).
func (p *cliParser) usage(used []string, required []string) string {
	return renderUsage(p.binName, used, required)
}

func renderUsage(binName string, used []string, required []string) string {
	parts := []string{binName}
	if len(used) == 0 {
		parts = append(parts, "[OPTIONS]")
	}
	if required == nil {
		for _, a := range argDefs {
			if a.Required {
				required = append(required, a.ID)
			}
		}
	}
	var unrolled []string
	for _, r := range required {
		for _, rr := range argByID[r].Requires {
			unrolled = append(unrolled, rr)
		}
		unrolled = append(unrolled, r)
	}
	all := append(append([]string{}, unrolled...), used...)
	var groups []string
	groupMembers := map[string]bool{}
	for _, r := range all {
		if r == "Cli" {
			if !contains(groups, "Cli") {
				groups = append(groups, "Cli")
			}
			for _, a := range argDefs {
				if a.InGroup {
					groupMembers[a.ID] = true
				}
			}
		}
	}
	var opts []string
	posVals := map[int]string{}
	for _, r := range all {
		if r == "Cli" {
			continue
		}
		a := argByID[r]
		if groupMembers[a.ID] {
			continue
		}
		t := true
		s := a.stylized(&t)
		if a.Positional {
			posVals[a.Index] = s
		} else if !contains(opts, s) {
			opts = append(opts, s)
		}
	}
	for _, pa := range positionals() {
		if pa.Hidden || groupMembers[pa.ID] {
			continue
		}
		if _, ok := posVals[pa.Index]; !ok {
			f := false
			posVals[pa.Index] = pa.stylized(&f)
		}
	}
	for _, g := range groups {
		_ = g
		var names []string
		for _, a := range argDefs {
			if !a.InGroup {
				continue
			}
			if a.Positional {
				names = append(names, a.nameNoBrackets())
			} else {
				names = append(names, a.String())
			}
		}
		parts = append(parts, "<"+strings.Join(names, "|")+">")
	}
	parts = append(parts, opts...)
	var idxs []int
	for k := range posVals {
		idxs = append(idxs, k)
	}
	sort.Ints(idxs)
	for _, k := range idxs {
		parts = append(parts, posVals[k])
	}
	return "Usage: " + strings.Join(parts, " ")
}

func helpUsage(binName string) string {
	return renderUsage(binName, nil, nil)
}

// formatError renders a clap-style error.
// tips: suggestion lines (already formatted without the "  tip: " prefix)
func (p *cliParser) formatError(msg string, similar string, tips []string, usage string) error {
	return &ClapError{Message: formatClapError(msg, similar, tips, usage), ExitCode: 2}
}

func formatClapError(msg string, similar string, tips []string, usage string) string {
	s := "error: " + msg
	suggested := false
	if similar != "" {
		s += "\n\n" + similar
		suggested = true
	}
	if len(tips) > 0 {
		if !suggested {
			s += "\n"
		}
		for _, t := range tips {
			s += "\n  tip: " + t
		}
	}
	if usage != "" {
		s += "\n\n" + usage
	}
	s += "\n\nFor more information, try '--help'.\n"
	return s
}

func (p *cliParser) emptyValueError(a *ArgDef) error {
	msg := "a value is required for '" + a.String() + "' but none was supplied"
	if len(a.Possible) > 0 {
		msg += "\n  [possible values: " + strings.Join(escapeVals(a.Possible), ", ") + "]"
	}
	return p.formatError(msg, "", nil, "")
}

func escapeVals(vs []string) []string {
	var out []string
	for _, v := range vs {
		if strings.ContainsAny(v, " ") {
			out = append(out, "\""+v+"\"")
		} else {
			out = append(out, v)
		}
	}
	return out
}

func (p *cliParser) invalidValueError(a *ArgDef, v string) error {
	if v == "" {
		return p.emptyValueError(a)
	}
	msg := "invalid value '" + v + "' for '" + a.String() + "'"
	msg += "\n  [possible values: " + strings.Join(escapeVals(a.Possible), ", ") + "]"
	similar := ""
	if s := didYouMean(v, a.Possible); s != "" {
		similar = "  tip: a similar value exists: '" + s + "'"
	}
	return p.formatError(msg, similar, nil, "")
}

func (p *cliParser) valueValidationError(a *ArgDef, v string, e string) error {
	msg := "invalid value '" + v + "' for '" + a.String() + "': " + e
	return p.formatError(msg, "", nil, "")
}

func (p *cliParser) tooManyValuesError(val string, a *ArgDef, used []string) error {
	msg := "unexpected value '" + val + "' for '" + a.String() + "' found; no more were expected"
	return p.formatError(msg, "", nil, p.usage(used, nil))
}

func (p *cliParser) unknownShortError(arg string, trailing bool) error {
	msg := "unexpected argument '" + arg + "' found"
	var tips []string
	if !trailing {
		tips = append(tips, "to pass '"+arg+"' as a value, use '-- "+arg+"'")
	}
	return p.formatError(msg, "", tips, helpUsage(p.binName))
}

func (p *cliParser) didYouMeanError(name string, trailing bool) error {
	cand := didYouMean(name, longOrder)
	if cand != "" {
		if def := argByLong[cand]; def != nil {
			p.startArg(def)
		}
	}
	var used []string
	for _, e := range p.m.entries {
		if e.isGroup {
			continue
		}
		if argByID[e.id].Hidden {
			continue
		}
		used = append(used, e.id)
	}
	arg := "--" + name
	msg := "unexpected argument '" + arg + "' found"
	similar := ""
	var tips []string
	if cand != "" {
		similar = "  tip: a similar argument exists: '--" + cand + "'"
	} else if !trailing {
		tips = append(tips, "to pass '"+arg+"' as a value, use '-- "+arg+"'")
	}
	return p.formatError(msg, similar, tips, p.usage(used, nil))
}

// didYouMean returns the best candidate with jaro similarity > 0.7.
func didYouMean(v string, candidates []string) string {
	best := ""
	bestScore := -1.0
	for _, c := range candidates {
		s := jaro(v, c)
		if s > 0.7 && s >= bestScore {
			best = c
			bestScore = s
		}
	}
	return best
}

func jaro(a, b string) float64 {
	ar := []rune(a)
	br := []rune(b)
	al, bl := len(ar), len(br)
	if al == 0 && bl == 0 {
		return 1.0
	}
	if al == 0 || bl == 0 {
		return 0.0
	}
	sr := al
	if bl > sr {
		sr = bl
	}
	sr = sr / 2
	if sr > 0 {
		sr--
	}
	af := make([]bool, al)
	bf := make([]bool, bl)
	matches := 0
	for i := 0; i < al; i++ {
		minB := 0
		if i > sr {
			minB = i - sr
		}
		maxB := i + sr + 1
		if maxB > bl {
			maxB = bl
		}
		for j := minB; j < maxB; j++ {
			if ar[i] == br[j] && !bf[j] {
				af[i] = true
				bf[j] = true
				matches++
				break
			}
		}
	}
	if matches == 0 {
		return 0.0
	}
	trans := 0
	j := 0
	for i := 0; i < al; i++ {
		if af[i] {
			for !bf[j] {
				j++
			}
			if ar[i] != br[j] {
				trans++
			}
			j++
		}
	}
	trans /= 2
	m := float64(matches)
	return (m/float64(al) + m/float64(bl) + (m-float64(trans))/m) / 3.0
}
EOF
echo ok

