package main

import (
	"errors"
	"math"
	"net"
	"regexp"
	"strconv"
	"strings"
)

func rustParseUsize(s string) (uint64, error) {
	if s == "" {
		return 0, errors.New("cannot parse integer from empty string")
	}
	t := s
	if t[0] == '+' {
		t = t[1:]
		if t == "" {
			return 0, errors.New("invalid digit found in string")
		}
	}
	var v uint64
	overflow := false
	for _, c := range []byte(t) {
		if c < '0' || c > '9' {
			return 0, errors.New("invalid digit found in string")
		}
		if !overflow {
			if v > (math.MaxUint64-uint64(c-'0'))/10 {
				overflow = true
			} else {
				v = v*10 + uint64(c-'0')
			}
		}
	}
	if overflow {
		return 0, errors.New("number too large to fit in target type")
	}
	return v, nil
}

func validateUsize(s string) error {
	_, err := rustParseUsize(s)
	return err
}

var rustFloatRe = regexp.MustCompile(`^[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|(?i:inf|infinity|nan))$`)

func rustParseF64(s string) (float64, bool) {
	if !rustFloatRe.MatchString(s) {
		return 0, false
	}
	l := strings.ToLower(s)
	neg := strings.HasPrefix(l, "-")
	l = strings.TrimLeft(l, "+-")
	switch l {
	case "inf", "infinity":
		if neg {
			return math.Inf(-1), true
		}
		return math.Inf(1), true
	case "nan":
		return math.NaN(), true
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		// range errors: ParseFloat returns +-Inf or 0 with err
		var ne *strconv.NumError
		if errors.As(err, &ne) && ne.Err == strconv.ErrRange {
			return f, true
		}
		return 0, false
	}
	return f, true
}

func parseTimeout(s string) (float64, error) {
	f, ok := rustParseF64(s)
	if !ok || math.IsNaN(f) {
		return 0, errors.New("Connection timeout is not a valid number")
	}
	if math.Signbit(f) {
		return 0, errors.New("Connection timeout is negative")
	}
	if f >= 18446744073709551616.0 {
		return 0, errors.New("Connection timeout is too big")
	}
	return f, nil
}

func validateTimeout(s string) error {
	_, err := parseTimeout(s)
	return err
}

type proxySpec struct {
	Protocol string // http, https, all
	URL      *URL
	Raw      string
}

func parseProxy(s string) (*proxySpec, error) {
	proto, rest, ok := strings.Cut(s, ":")
	if !ok {
		return nil, errors.New("The value passed to --proxy should be formatted as <PROTOCOL>:<PROXY_URL>")
	}
	lp := strings.ToLower(proto)
	u, err := ParseURL(rest)
	if err != nil {
		return nil, errors.New("Invalid proxy URL '" + rest + "' for protocol '" + proto + "': " + err.Error())
	}
	switch lp {
	case "http", "https", "all":
	default:
		return nil, errors.New("Unknown protocol to set a proxy for: " + proto)
	}
	return &proxySpec{Protocol: lp, URL: u, Raw: rest}, nil
}

func validateProxy(s string) error {
	_, err := parseProxy(s)
	return err
}

type resolveSpec struct {
	Host string
	IP   net.IP
}

func parseRustIP(s string) net.IP {
	t := s
	if strings.HasPrefix(t, "[") && strings.HasSuffix(t, "]") {
		inner := t[1 : len(t)-1]
		if strings.Contains(inner, ":") {
			ip := net.ParseIP(inner)
			if ip != nil {
				return ip
			}
		}
		return nil
	}
	if strings.ContainsAny(t, "%") {
		return nil
	}
	return net.ParseIP(t)
}

func parseResolve(s string) (*resolveSpec, error) {
	host, addr, ok := strings.Cut(s, ":")
	if !ok {
		return nil, errors.New("Value should be formatted as <HOST>:<ADDRESS>")
	}
	ip := parseRustIP(addr)
	if ip == nil {
		if strings.Count(addr, ":") == 1 {
			return nil, errors.New("Value should be formatted as <HOST>:<ADDRESS> (not <HOST>:<PORT>:<ADDRESS>)")
		}
		return nil, errors.New("Invalid address '" + addr + "'")
	}
	return &resolveSpec{Host: host, IP: ip}, nil
}

func validateResolve(s string) error {
	_, err := parseResolve(s)
	return err
}

type formatOptions struct {
	JSONIndent  *uint64
	JSONFormat  *bool
