	HasFragment  bool
}

var specialSchemes = map[string]int{"ftp": 21, "file": -1, "http": 80, "https": 443, "ws": 80, "wss": 443}

func isSpecial(s string) bool { _, ok := specialSchemes[s]; return ok }

func defaultPort(s string) int {
	if p, ok := specialSchemes[s]; ok {
		return p
	}
	return -1
}

