	errEmptyHost          = errors.New("empty host")
	errIdna               = errors.New("invalid international domain name")
	errInvalidPort        = errors.New("invalid port number")
	errInvalidIPv4        = errors.New("invalid IPv4 address")
	errInvalidIPv6        = errors.New("invalid IPv6 address")
	errInvalidDomainChar  = errors.New("invalid domain character")
	errRelativeNoBase     = errors.New("relative URL without a base")
	errRelativeCannotBase = errors.New("relative URL with a cannot-be-a-base base")
)

type encodeSet func(c byte) bool

func c0Set(c byte) bool       { return c < 0x20 || c > 0x7e }
func fragmentSet(c byte) bool { return c0Set(c) || c == ' ' || c == '"' || c == '<' || c == '>' || c == '`' }
func querySet(c byte) bool    { return c0Set(c) || c == ' ' || c == '"' || c == '#' || c == '<' || c == '>' }
func specialQuerySet(c byte) bool {
	return querySet(c) || c == '\''
}
func pathSet(c byte) bool {
	return fragmentSet(c) || c == '#' || c == '?' || c == '{' || c == '}'
}
func userinfoSet(c byte) bool {
	return pathSet(c) || c == '/' || c == ':' || c == ';' || c == '=' || c == '@' || c == '[' || c == '\\' || c == ']' || c == '^' || c == '|'
}

const upperHex = "0123456789ABCDEF"

func pctEncodeString(s string, set encodeSet) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if set(c) {
			b.WriteByte('%')
			b.WriteByte(upperHex[c>>4])
			b.WriteByte(upperHex[c&15])
		} else {
			b.WriteByte(c)
		}
	}
	return b.String()
}

func pctDecode(s string) []byte {
	var out []byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '%' && i+2 < len(s) && isHex(s[i+1]) && isHex(s[i+2]) {
			out = append(out, unhex(s[i+1])<<4|unhex(s[i+2]))
			i += 2
		} else {
			out = append(out, c)
		}
	}
	return out
}

func isHex(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}
func unhex(c byte) byte {
	switch {
	case c >= '0' && c <= '9':
		return c - '0'
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10
	default:
		return c - 'A' + 10
	}
}

func isASCIIAlpha(c rune) bool    { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') }
func isASCIIDigit(c rune) bool    { return c >= '0' && c <= '9' }
func isASCIIAlnum(c rune) bool    { return isASCIIAlpha(c) || isASCIIDigit(c) }
func isWindowsLetter(s []rune, normalizedOnly bool) bool {
	if len(s) < 2 || !isASCIIAlpha(s[0]) {
		return false
	}
	if s[1] == ':' {
		return true
	}
	return !normalizedOnly && s[1] == '|'
}

func startsWithWindowsLetter(r []rune) bool {
	if len(r) < 2 || !isWindowsLetter(r[:2], false) {
		return false
	}
	if len(r) == 2 {
