		sSchemeStart = iota
		sScheme
		sNoScheme
		sSpecialRelOrAuth
		sPathOrAuth
		sRelative
		sRelativeSlash
		sSpecialAuthSlashes
		sSpecialAuthIgnoreSlashes
		sAuthority
		sHost
		sPort
		sFile
		sFileSlash
		sFileHost
		sPathStart
		sPath
		sOpaquePath
		sQuery
		sFragment
