				}
			}
		case sRelativeSlash:
			if isSpecial(u.Scheme) && (c == '/' || c == '\\') {
				state = sSpecialAuthIgnoreSlashes
			} else if c == '/' {
				state = sAuthority
			} else {
				u.Username, u.Password, u.Host, u.HasHost, u.HostKind, u.Port = base.Username, base.Password, base.Host, base.HasHost, base.HostKind, base.Port
				state = sPath
				ptr--
			}
		case sSpecialAuthSlashes:
			if c == '/' && remaining(1) == '/' {
				state = sSpecialAuthIgnoreSlashes
				ptr++
			} else {
				state = sSpecialAuthIgnoreSlashes
				ptr--
			}
		case sSpecialAuthIgnoreSlashes:
			if c != '/' && c != '\\' {
				state = sAuthority
				ptr--
			}
		case sAuthority:
			if c == '@' {
				if atSignSeen {
					s := buf.String()
					buf.Reset()
					buf.WriteString("%40")
					buf.WriteString(s)
				}
				atSignSeen = true
				s := buf.String()
				buf.Reset()
				for _, cp := range s {
					if cp == ':' && !passwordTokenSeen {
						passwordTokenSeen = true
						continue
					}
					enc := pctEncodeString(string(cp), userinfoSet)
					if passwordTokenSeen {
						u.Password += enc
					} else {
						u.Username += enc
					}
				}
			} else if c == EOF || c == '/' || c == '?' || c == '#' || (isSpecial(u.Scheme) && c == '\\') {
				if atSignSeen && buf.Len() == 0 {
					return nil, errEmptyHost
				}
				ptr -= utf8.RuneCountInString(buf.String()) + 1
				buf.Reset()
				state = sHost
			} else {
				buf.WriteRune(c)
			}
		case sHost:
			if c == ':' && !insideBrackets {
				if buf.Len() == 0 {
					return nil, errEmptyHost
				}
				h, kind, err := parseHost(buf.String(), !isSpecial(u.Scheme))
				if err != nil {
					return nil, err
				}
				u.Host, u.HostKind, u.HasHost = h, kind, true
				buf.Reset()
				state = sPort
			} else if c == EOF || c == '/' || c == '?' || c == '#' || (isSpecial(u.Scheme) && c == '\\') {
				ptr--
				if isSpecial(u.Scheme) && buf.Len() == 0 {
					return nil, errEmptyHost
				}
				h, kind, err := parseHost(buf.String(), !isSpecial(u.Scheme))
				if err != nil {
					return nil, err
				}
				u.Host, u.HostKind, u.HasHost = h, kind, true
				buf.Reset()
				state = sPathStart
			} else {
				if c == '[' {
					insideBrackets = true
				}
				if c == ']' {
					insideBrackets = false
				}
				buf.WriteRune(c)
			}
		case sPort:
			if c != EOF && isASCIIDigit(c) {
				buf.WriteRune(c)
			} else if c == EOF || c == '/' || c == '?' || c == '#' || (isSpecial(u.Scheme) && c == '\\') {
				if buf.Len() != 0 {
					s := strings.TrimLeft(buf.String(), "0")
					port := 0
					if len(s) > 5 {
						return nil, errInvalidPort
					}
					if s != "" {
						p, _ := strconv.Atoi(s)
						port = p
					}
					if port > 65535 {
						return nil, errInvalidPort
					}
					if port == defaultPort(u.Scheme) {
						u.Port = -1
					} else {
						u.Port = port
					}
					buf.Reset()
				}
				state = sPathStart
				ptr--
			} else {
				return nil, errInvalidPort
			}
		case sFile:
			u.Scheme = "file"
			u.Host, u.HasHost, u.HostKind = "", true, 0
			if c == '/' || c == '\\' {
				state = sFileSlash
			} else if base != nil && base.Scheme == "file" {
				u.Host, u.HasHost = base.Host, base.HasHost
				u.Path = append([]string{}, base.Path...)
				u.Query, u.HasQuery = base.Query, base.HasQuery
				if c == '?' {
					u.Query, u.HasQuery = "", true
					state = sQuery
				} else if c == '#' {
					u.Fragment, u.HasFragment = "", true
					state = sFragment
				} else if c != EOF {
					u.Query, u.HasQuery = "", false
					if !startsWithWindowsLetter(in[ptr:]) {
						u.shortenPath()
					} else {
						u.Path = nil
					}
					state = sPath
					ptr--
				}
			} else {
				state = sPath
				ptr--
			}
		case sFileSlash:
			if c == '/' || c == '\\' {
				state = sFileHost
			} else {
				if base != nil && base.Scheme == "file" {
					u.Host, u.HasHost = base.Host, base.HasHost
					if !startsWithWindowsLetter(in[ptr:]) && len(base.Path) > 0 && isWindowsLetter([]rune(base.Path[0]), true) {
						u.Path = append(u.Path, base.Path[0])
					}
				}
				state = sPath
				ptr--
			}
		case sFileHost:
			if c == EOF || c == '/' || c == '\\' || c == '?' || c == '#' {
				ptr--
				if isWindowsLetter([]rune(buf.String()), false) && len([]rune(buf.String())) == 2 {
					state = sPath
				} else if buf.Len() == 0 {
					u.Host, u.HasHost = "", true
					state = sPathStart
				} else {
					h, kind, err := parseHost(buf.String(), false)
					if err != nil {
						return nil, err
					}
					if h == "localhost" {
						h = ""
					}
					u.Host, u.HostKind, u.HasHost = h, kind, true
					buf.Reset()
					state = sPathStart
				}
			} else {
				buf.WriteRune(c)
			}
		case sPathStart:
			if isSpecial(u.Scheme) {
				state = sPath
				if c != '/' && c != '\\' {
					ptr--
				}
			} else if c == '?' {
				u.Query, u.HasQuery = "", true
				state = sQuery
			} else if c == '#' {
				u.Fragment, u.HasFragment = "", true
				state = sFragment
			} else if c != EOF {
				state = sPath
				if c != '/' {
					ptr--
				}
			}
		case sPath:
			if c == EOF || c == '/' || (isSpecial(u.Scheme) && c == '\\') || c == '?' || c == '#' {
				seg := buf.String()
				if isDoubleDot(seg) {
					u.shortenPath()
					if c != '/' && !(isSpecial(u.Scheme) && c == '\\') {
						u.Path = append(u.Path, "")
					}
				} else if isSingleDot(seg) && c != '/' && !(isSpecial(u.Scheme) && c == '\\') {
					u.Path = append(u.Path, "")
				} else if !isSingleDot(seg) {
					if u.Scheme == "file" && len(u.Path) == 0 && isWindowsLetter([]rune(seg), false) && len([]rune(seg)) == 2 {
						r := []rune(seg)
						seg = string(r[0]) + ":"
					}
					u.Path = append(u.Path, seg)
				}
				buf.Reset()
				if c == '?' {
					u.Query, u.HasQuery = "", true
					state = sQuery
				}
				if c == '#' {
					u.Fragment, u.HasFragment = "", true
					state = sFragment
				}
			} else {
				buf.WriteString(pctEncodeString(string(c), pathSet))
			}
		case sOpaquePath:
			if c == '?' {
				u.Query, u.HasQuery = "", true
				state = sQuery
			} else if c == '#' {
				u.Fragment, u.HasFragment = "", true
				state = sFragment
			} else if c != EOF {
				u.OpaquePath += pctEncodeString(string(c), c0Set)
			}
		case sQuery:
			if c == '#' || c == EOF {
				set := querySet
				if isSpecial(u.Scheme) {
					set = specialQuerySet
				}
				u.Query += pctEncodeString(buf.String(), set)
				buf.Reset()
				if c == '#' {
					u.Fragment, u.HasFragment = "", true
					state = sFragment
				}
			} else if c != EOF {
				buf.WriteRune(c)
			}
		case sFragment:
			if c != EOF {
				u.Fragment += pctEncodeString(string(c), fragmentSet)
			}
		}
		if c == EOF {
			break
		}
		ptr++
		if ptr > len(in) {
			break
		}
	}
	return u, nil
}

func toLowerASCII(c rune) rune {
	if c >= 'A' && c <= 'Z' {
		return c + 32
	}
	return c
}

// parseHost returns serialized host and kind.
func parseHost(input string, notSpecial bool) (string, int, error) {
	if strings.HasPrefix(input, "[") {
		if !strings.HasSuffix(input, "]") {
			return "", 0, errInvalidIPv6
		}
		addr, ok := parseIPv6(input[1 : len(input)-1])
		if !ok {
			return "", 0, errInvalidIPv6
		}
		return "[" + serializeIPv6(addr) + "]", 2, nil
	}
	if notSpecial {
		// opaque host
		for _, c := range input {
			switch c {
			case 0, '\t', '\n', '\r', ' ', '#', '/', ':', '<', '>', '?', '@', '[', '\\', ']', '^', '|':
				return "", 0, errInvalidDomainChar
			}
		}
		return pctEncodeString(input, c0Set), 3, nil
	}
	domain := string(pctDecode(input))
	ascii, err := domainToASCII(domain)
	if err != nil {
		return "", 0, errIdna
	}
	if ascii == "" {
		return "", 0, errEmptyHost
	}
	for i := 0; i < len(ascii); i++ {
		c := ascii[i]
		if c <= 0x1f || c == ' ' || c == '#' || c == '%' || c == '/' || c == ':' || c == '<' || c == '>' || c == '?' || c == '@' || c == '[' || c == '\\' || c == ']' || c == '^' || c == 0x7f || c == '|' {
			return "", 0, errInvalidDomainChar
		}
	}
	if endsInANumber(ascii) {
		v, err := parseIPv4(ascii)
		if err != nil {
			return "", 0, err
		}
		return serializeIPv4(v), 1, nil
	}
	return ascii, 0, nil
}

func endsInANumber(s string) bool {
	parts := strings.Split(s, ".")
	if parts[len(parts)-1] == "" {
		if len(parts) == 1 {
			return false
		}
		parts = parts[:len(parts)-1]
	}
	last := parts[len(parts)-1]
	if last != "" {
		allDigits := true
		for _, c := range last {
			if !isASCIIDigit(c) {
				allDigits = false
			}
		}
		if allDigits {
			return true
		}
	}
	_, ok := parseIPv4Number(last)
	return ok
}

func parseIPv4Number(s string) (uint64, bool) {
	if s == "" {
		return 0, false
	}
	radix := 10
	if len(s) >= 2 && (strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X")) {
		s = s[2:]
		radix = 16
	} else if len(s) >= 2 && s[0] == '0' {
		s = s[1:]
		radix = 8
	}
	if s == "" {
		return 0, true
	}
	for _, c := range s {
		switch radix {
		case 10:
			if !isASCIIDigit(c) {
				return 0, false
			}
		case 8:
			if c < '0' || c > '7' {
				return 0, false
			}
		case 16:
			if !isHex(byte(c)) || c > 127 {
				return 0, false
			}
		}
	}
	v, err := strconv.ParseUint(s, radix, 64)
	if err != nil {
		return 1 << 40, true // too big
	}
	return v, true
}

func parseIPv4(s string) (uint32, error) {
	parts := strings.Split(s, ".")
	if parts[len(parts)-1] == "" {
		if len(parts) > 1 {
			parts = parts[:len(parts)-1]
		}
	}
	if len(parts) > 4 {
		return 0, errInvalidIPv4
	}
	var nums []uint64
	for _, p := range parts {
		n, ok := parseIPv4Number(p)
		if !ok {
			return 0, errInvalidIPv4
		}
		nums = append(nums, n)
	}
	for i, n := range nums {
		if n > 255 && i != len(nums)-1 {
			return 0, errInvalidIPv4
		}
	}
	last := nums[len(nums)-1]
	limit := uint64(1) << (8 * uint(5-len(nums)))
	if last >= limit {
		return 0, errInvalidIPv4
	}
	ipv4 := last
	for i := 0; i < len(nums)-1; i++ {
		ipv4 += nums[i] << (8 * uint(3-i))
	}
	return uint32(ipv4), nil
}

func serializeIPv4(v uint32) string {
	return strconv.Itoa(int(v>>24)) + "." + strconv.Itoa(int(v>>16&255)) + "." + strconv.Itoa(int(v>>8&255)) + "." + strconv.Itoa(int(v&255))
}

func parseIPv6(input string) ([8]uint16, bool) {
	var addr [8]uint16
	in := []rune(input)
	pieceIndex := 0
	compress := -1
	p := 0
	at := func(i int) rune {
		if i < len(in) {
			return in[i]
		}
		return -1
	}
	if at(p) == ':' {
		if at(p+1) != ':' {
			return addr, false
		}
		p += 2
		pieceIndex++
		compress = pieceIndex
	}
	for at(p) != -1 {
		if pieceIndex == 8 {
			return addr, false
		}
		if at(p) == ':' {
			if compress != -1 {
				return addr, false
			}
			p++
			pieceIndex++
			compress = pieceIndex
			continue
		}
		value, length := 0, 0
		for length < 4 && at(p) != -1 && at(p) < 128 && isHex(byte(at(p))) {
			value = value*16 + int(unhex(byte(at(p))))
			p++
			length++
		}
		if at(p) == '.' {
			if length == 0 {
				return addr, false
			}
			p -= length
			if pieceIndex > 6 {
				return addr, false
			}
			numbersSeen := 0
			for at(p) != -1 {
				ipv4Piece := -1
				if numbersSeen > 0 {
					if at(p) == '.' && numbersSeen < 4 {
						p++
					} else {
						return addr, false
					}
				}
				if at(p) == -1 || !isASCIIDigit(at(p)) {
					return addr, false
				}
				for at(p) != -1 && isASCIIDigit(at(p)) {
					n := int(at(p) - '0')
					if ipv4Piece == -1 {
						ipv4Piece = n
					} else if ipv4Piece == 0 {
						return addr, false
					} else {
						ipv4Piece = ipv4Piece*10 + n
					}
					if ipv4Piece > 255 {
						return addr, false
					}
					p++
				}
				addr[pieceIndex] = addr[pieceIndex]*0x100 + uint16(ipv4Piece)
				numbersSeen++
				if numbersSeen == 2 || numbersSeen == 4 {
					pieceIndex++
				}
			}
			if numbersSeen != 4 {
				return addr, false
			}
			break
		} else if at(p) == ':' {
			p++
			if at(p) == -1 {
				return addr, false
			}
		} else if at(p) != -1 {
			return addr, false
		}
		addr[pieceIndex] = uint16(value)
		pieceIndex++
	}
	if compress != -1 {
		swaps := pieceIndex - compress
		pieceIndex = 7
		for pieceIndex != 0 && swaps > 0 {
			addr[pieceIndex], addr[compress+swaps-1] = addr[compress+swaps-1], addr[pieceIndex]
			pieceIndex--
			swaps--
		}
	} else if pieceIndex != 8 {
		return addr, false
	}
	return addr, true
}

func serializeIPv6(addr [8]uint16) string {
	// find longest run of zeros (len >= 2)
	bestStart, bestLen := -1, 0
	for i := 0; i < 8; {
		if addr[i] == 0 {
			j := i
			for j < 8 && addr[j] == 0 {
				j++
			}
			if j-i > bestLen && j-i >= 2 {
				bestStart, bestLen = i, j-i
			}
			i = j
		} else {
			i++
		}
	}
	var b strings.Builder
	ignore0 := false
	for i := 0; i < 8; i++ {
		if ignore0 && addr[i] == 0 {
			continue
		}
		ignore0 = false
		if bestStart == i {
			if i == 0 {
				b.WriteString("::")
			} else {
				b.WriteString(":")
			}
			ignore0 = true
			continue
		}
		b.WriteString(strconv.FormatUint(uint64(addr[i]), 16))
		if i != 7 {
			b.WriteString(":")
		}
	}
	return b.String()
}

// Serialize returns the href.
func (u *URL) String() string {
	var b strings.Builder
	b.WriteString(u.Scheme)
	b.WriteString(":")
	if u.HasHost {
		b.WriteString("//")
		if u.Username != "" || u.Password != "" {
			b.WriteString(u.Username)
			if u.Password != "" {
				b.WriteString(":" + u.Password)
			}
			b.WriteString("@")
		}
		b.WriteString(u.Host)
		if u.Port >= 0 {
			b.WriteString(":" + strconv.Itoa(u.Port))
		}
	} else if !u.IsOpaque && len(u.Path) > 1 && u.Path[0] == "" {
		b.WriteString("/.")
	}
	b.WriteString(u.PathString())
	if u.HasQuery {
		b.WriteString("?" + u.Query)
	}
	if u.HasFragment {
		b.WriteString("#" + u.Fragment)
	}
	return b.String()
}

func (u *URL) PathString() string {
	if u.IsOpaque {
		return u.OpaquePath
	}
	var b strings.Builder
	for _, seg := range u.Path {
		b.WriteString("/")
		b.WriteString(seg)
	}
	return b.String()
}

// HostStr returns host without brackets processing (like rust-url host_str).
func (u *URL) HostStr() string { return u.Host }

// PortOrDefault returns explicit port or the scheme default.
func (u *URL) PortOrDefault() int {
	if u.Port >= 0 {
		return u.Port
	}
	return defaultPort(u.Scheme)
}

func (u *URL) Clone() *URL {
	c := *u
	c.Path = append([]string{}, u.Path...)
	return &c
}

// Join resolves a reference against this URL.
func (u *URL) Join(ref string) (*URL, error) {
	return parseURLWithBase(ref, u)
}

// AppendQueryPairs appends form-urlencoded pairs to the query.
func (u *URL) AppendQueryPairs(pairs [][2]string) {
	if len(pairs) == 0 {
		return
	}
	q := u.Query
	if !u.HasQuery {
		q = ""
	}
	for _, p := range pairs {
		if q != "" {
			q += "&"
		}
		q += formURLEncode(p[0]) + "=" + formURLEncode(p[1])
	}
	u.Query = q
	u.HasQuery = true
}

func formURLEncode(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '*' || c == '-' || c == '.' || c == '_':
			b.WriteByte(c)
		case c == ' ':
			b.WriteByte('+')
		default:
			b.WriteByte('%')
			b.WriteByte(upperHex[c>>4])
			b.WriteByte(upperHex[c&15])
		}
	}
	return b.String()
}
