package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

// ---------- JSON value model (ordered) ----------

type JKind int

const (
	JNull JKind = iota
	JBool
	JNumber
	JString
	JArray
	JObject
)

type NumKind int

const (
	NumU64 NumKind = iota
	NumI64
	NumF64
)

type JValue struct {
	Kind  JKind
	Bool  bool
	NK    NumKind
	U     uint64
	I     int64
	F     float64
	Str   string
	Arr   []*JValue
	Keys  []string
	Vals  map[string]*JValue
}

func jNull() *JValue           { return &JValue{Kind: JNull} }
func jString(s string) *JValue { return &JValue{Kind: JString, Str: s} }
func jObject() *JValue         { return &JValue{Kind: JObject, Vals: map[string]*JValue{}} }
func jArray() *JValue          { return &JValue{Kind: JArray} }

func (v *JValue) Get(k string) *JValue {
	if v.Vals == nil {
		return nil
	}
	return v.Vals[k]
}

// Set inserts or replaces (preserving position like IndexMap::insert).
func (v *JValue) Set(k string, val *JValue) {
	if v.Vals == nil {
		v.Vals = map[string]*JValue{}
	}
	if _, ok := v.Vals[k]; !ok {
		v.Keys = append(v.Keys, k)
	}
	v.Vals[k] = val
}

// ---------- serde_json-compatible errors ----------

type JSONError struct {
	Msg    string
	Line   int
	Column int
	NoPos  bool
}

func (e *JSONError) Error() string {
	if e.NoPos || e.Line == 0 {
		return e.Msg
	}
	return fmt.Sprintf("%s at line %d column %d", e.Msg, e.Line, e.Column)
}

type jsonParser struct {
	s     []byte
	i     int
	depth int
}

func (p *jsonParser) positionOf(i int) (int, int) {
	if i > len(p.s) {
		i = len(p.s)
	}
	startOfLine := 0
	line := 1
	for j := 0; j < i; j++ {
		if p.s[j] == '\n' {
			line++
			startOfLine = j + 1
		}
	}
	return line, i - startOfLine
}

func (p *jsonParser) err(msg string) *JSONError {
	l, c := p.positionOf(p.i)
	return &JSONError{Msg: msg, Line: l, Column: c}
}

func (p *jsonParser) peekErr(msg string) *JSONError {
	i := p.i + 1
	if i > len(p.s) {
		i = len(p.s)
	}
	l, c := p.positionOf(i)
	return &JSONError{Msg: msg, Line: l, Column: c}
}

func (p *jsonParser) peek() (byte, bool) {
	if p.i < len(p.s) {
		return p.s[p.i], true
	}
	return 0, false
}

func (p *jsonParser) peekOrNull() byte {
	if p.i < len(p.s) {
		return p.s[p.i]
	}
	return 0
}

func (p *jsonParser) next() (byte, bool) {
	if p.i < len(p.s) {
		c := p.s[p.i]
		p.i++
		return c, true
	}
	return 0, false
}

func (p *jsonParser) parseWhitespace() (byte, bool) {
	for p.i < len(p.s) {
		switch p.s[p.i] {
		case ' ', '\n', '\t', '\r':
			p.i++
		default:
			return p.s[p.i], true
		}
	}
	return 0, false
}

func (p *jsonParser) parseIdent(ident string) *JSONError {
	for k := 0; k < len(ident); k++ {
		c, ok := p.next()
		if !ok {
			return p.err("EOF while parsing a value")
		}
		if c != ident[k] {
			return p.err("expected ident")
		}
	}
	return nil
}

type parsedNum struct {
	kind NumKind
	u    uint64
	i    int64
	f    float64
}

var pow10 [309]float64

func init() {
	for i := range pow10 {
		pow10[i], _ = strconv.ParseFloat("1e"+strconv.Itoa(i), 64)
	}
}

func (p *jsonParser) f64FromParts(positive bool, significand uint64, exponent int32) (float64, *JSONError) {
	f := float64(significand)
	for {
		e := exponent
		if e < 0 {
			e = -e
		}
		if int(e) < len(pow10) && exponent != math.MinInt32 {
			pow := pow10[e]
			if exponent >= 0 {
				f *= pow
				if math.IsInf(f, 0) {
					return 0, p.err("number out of range")
				}
			} else {
				f /= pow
			}
			break
		}
		if f == 0 {
			break
		}
		if exponent >= 0 {
			return 0, p.err("number out of range")
		}
		f /= 1e308
		exponent += 308
	}
	if positive {
		return f, nil
	}
	return -f, nil
}

func overflowU64(a uint64, b uint64) bool {
	const c = math.MaxUint64
	return a >= c/10 && (a > c/10 || b > c%10)
}

func overflowI32(a int32, b int32) bool {
	const c = math.MaxInt32
	return a >= c/10 && (a > c/10 || b > c%10)
}

func (p *jsonParser) parseAnyNumber(positive bool) (parsedNum, *JSONError) {
	c, ok := p.next()
	if !ok {
		return parsedNum{}, p.err("EOF while parsing a value")
	}
	switch {
	case c == '0':
		if d := p.peekOrNull(); d >= '0' && d <= '9' {
			return parsedNum{}, p.peekErr("invalid number")
		}
		return p.parseNumber(positive, 0)
	case c >= '1' && c <= '9':
		sig := uint64(c - '0')
		for {
			d := p.peekOrNull()
			if d >= '0' && d <= '9' {
				digit := uint64(d - '0')
				if overflowU64(sig, digit) {
					f, err := p.parseLongInteger(positive, sig)
					if err != nil {
						return parsedNum{}, err
					}
					return parsedNum{kind: NumF64, f: f}, nil
				}
				p.i++
				sig = sig*10 + digit
			} else {
				return p.parseNumber(positive, sig)
			}
		}
	default:
		return parsedNum{}, p.err("invalid number")
	}
}

func (p *jsonParser) parseNumber(positive bool, sig uint64) (parsedNum, *JSONError) {
	switch p.peekOrNull() {
	case '.':
		f, err := p.parseDecimal(positive, sig, 0)
		return parsedNum{kind: NumF64, f: f}, err
	case 'e', 'E':
		f, err := p.parseExponent(positive, sig, 0)
		return parsedNum{kind: NumF64, f: f}, err
	}
	if positive {
		return parsedNum{kind: NumU64, u: sig}, nil
	}
	neg := -int64(sig)
	if neg >= 0 {
		return parsedNum{kind: NumF64, f: -float64(sig)}, nil
	}
	return parsedNum{kind: NumI64, i: neg}, nil
}

func (p *jsonParser) parseDecimal(positive bool, sig uint64, expBefore int32) (float64, *JSONError) {
	p.i++
	var expAfter int32
	for {
		d := p.peekOrNull()
		if d < '0' || d > '9' {
			break
		}
		digit := uint64(d - '0')
		if overflowU64(sig, digit) {
			return p.parseDecimalOverflow(positive, sig, expBefore+expAfter)
		}
		p.i++
		sig = sig*10 + digit
		expAfter--
	}
	if expAfter == 0 {
		if _, ok := p.peek(); ok {
			return 0, p.peekErr("invalid number")
		}
		return 0, p.peekErr("EOF while parsing a value")
	}
	exp := expBefore + expAfter
	switch p.peekOrNull() {
	case 'e', 'E':
		return p.parseExponent(positive, sig, exp)
	}
	return p.f64FromParts(positive, sig, exp)
}

func (p *jsonParser) parseDecimalOverflow(positive bool, sig uint64, exp int32) (float64, *JSONError) {
	for {
		d := p.peekOrNull()
		if d < '0' || d > '9' {
			break
		}
		p.i++
	}
	switch p.peekOrNull() {
	case 'e', 'E':
		return p.parseExponent(positive, sig, exp)
	}
	return p.f64FromParts(positive, sig, exp)
}

func (p *jsonParser) parseLongInteger(positive bool, sig uint64) (float64, *JSONError) {
	var exp int32
	for {
		switch d := p.peekOrNull(); {
		case d >= '0' && d <= '9':
			p.i++
			exp++
		case d == '.':
			return p.parseDecimal(positive, sig, exp)
		case d == 'e' || d == 'E':
			return p.parseExponent(positive, sig, exp)
		default:
			return p.f64FromParts(positive, sig, exp)
		}
	}
}

func satAdd(a, b int32) int32 {
	r := int64(a) + int64(b)
	if r > math.MaxInt32 {
		return math.MaxInt32
	}
	if r < math.MinInt32 {
		return math.MinInt32
	}
	return int32(r)
}

func (p *jsonParser) parseExponent(positive bool, sig uint64, startExp int32) (float64, *JSONError) {
	p.i++
	positiveExp := true
	switch p.peekOrNull() {
	case '+':
		p.i++
	case '-':
		p.i++
		positiveExp = false
	}
	c, ok := p.next()
	if !ok {
		return 0, p.err("EOF while parsing a value")
	}
	if c < '0' || c > '9' {
		return 0, p.err("invalid number")
	}
	exp := int32(c - '0')
	for {
		d := p.peekOrNull()
		if d < '0' || d > '9' {
			break
		}
		p.i++
		digit := int32(d - '0')
		if overflowI32(exp, digit) {
			zero := sig == 0
			if !zero && positiveExp {
				return 0, p.err("number out of range")
			}
			for {
				d := p.peekOrNull()
				if d < '0' || d > '9' {
					break
				}
				p.i++
			}
			if positive {
				return 0, nil
			}
			return math.Copysign(0, -1), nil
		}
		exp = exp*10 + digit
	}
	var final int32
	if positiveExp {
		final = satAdd(startExp, exp)
	} else {
		final = satAdd(startExp, -exp)
	}
	return p.f64FromParts(positive, sig, final)
}

func (p *jsonParser) decodeHexEscape() (uint16, *JSONError) {
	var n uint16
	for k := 0; k < 4; k++ {
		c, ok := p.next()
		if !ok {
			return 0, p.err("EOF while parsing a string")
		}
		var v byte
		switch {
		case c >= '0' && c <= '9':
			v = c - '0'
		case c >= 'a' && c <= 'f':
			v = c - 'a' + 10
		case c >= 'A' && c <= 'F':
			v = c - 'A' + 10
		default:
			return 0, p.err("invalid escape")
		}
		n = n*16 + uint16(v)
	}
	return n, nil
}

// parseStr parses after the opening quote.
func (p *jsonParser) parseStr() (string, *JSONError) {
	var b []byte
	for {
		start := p.i
		for p.i < len(p.s) {
			c := p.s[p.i]
			if c == '"' || c == '\\' || c < 0x20 {
				break
			}
			p.i++
		}
		if p.i == len(p.s) {
			return "", p.err("EOF while parsing a string")
		}
		b = append(b, p.s[start:p.i]...)
		c := p.s[p.i]
		switch {
		case c == '"':
			p.i++
			if !utf8.Valid(b) {
				// serde_json reports invalid unicode code point
				return "", p.err("invalid unicode code point")
			}
			return string(b), nil
		case c == '\\':
			p.i++
			e, ok := p.next()
			if !ok {
				return "", p.err("EOF while parsing a string")
			}
			switch e {
			case '"':
				b = append(b, '"')
			case '\\':
				b = append(b, '\\')
			case '/':
				b = append(b, '/')
			case 'b':
				b = append(b, '\b')
			case 'f':
				b = append(b, '\f')
			case 'n':
				b = append(b, '\n')
			case 'r':
				b = append(b, '\r')
			case 't':
				b = append(b, '\t')
			case 'u':
				n, err := p.decodeHexEscape()
				if err != nil {
					return "", err
				}
				var r rune
				switch {
				case n >= 0xDC00 && n <= 0xDFFF:
					return "", p.err("lone leading surrogate in hex escape")
				case n >= 0xD800 && n <= 0xDBFF:
					c1, ok := p.peek()
					if !ok {
						return "", p.err("EOF while parsing a string")
					}
					if c1 != '\\' {
						p.i++
						return "", p.err("unexpected end of hex escape")
					}
					p.i++
					c2, ok := p.peek()
					if !ok {
						return "", p.err("EOF while parsing a string")
					}
					if c2 != 'u' {
						p.i++
						return "", p.err("unexpected end of hex escape")
					}
					p.i++
					n2, err := p.decodeHexEscape()
					if err != nil {
						return "", err
					}
					if n2 < 0xDC00 || n2 > 0xDFFF {
						return "", p.err("lone leading surrogate in hex escape")
					}
					r = rune((uint32(n)-0xD800)<<10|(uint32(n2)-0xDC00)) + 0x10000
				default:
					r = rune(n)
				}
				b = utf8.AppendRune(b, r)
			default:
				return "", p.err("invalid escape")
			}
		default:
			p.i++
			return "", p.err("control character (\\u0000-\\u001F) found while parsing a string")
		}
	}
}

// parseValue parses a JSON value (deserialize_any into Value).
func (p *jsonParser) parseValue() (*JValue, *JSONError) {
	c, ok := p.parseWhitespace()
	if !ok {
		return nil, p.peekErr("EOF while parsing a value")
	}
	switch {
	case c == 'n':
		p.i++
		if err := p.parseIdent("ull"); err != nil {
			return nil, err
		}
		return jNull(), nil
	case c == 't':
		p.i++
		if err := p.parseIdent("rue"); err != nil {
			return nil, err
		}
		return &JValue{Kind: JBool, Bool: true}, nil
	case c == 'f':
		p.i++
		if err := p.parseIdent("alse"); err != nil {
			return nil, err
		}
		return &JValue{Kind: JBool, Bool: false}, nil
	case c == '-':
		p.i++
		n, err := p.parseAnyNumber(false)
		if err != nil {
			return nil, err
		}
		return numToValue(n), nil
	case c >= '0' && c <= '9':
		n, err := p.parseAnyNumber(true)
		if err != nil {
			return nil, err
		}
		return numToValue(n), nil
	case c == '"':
		p.i++
		s, err := p.parseStr()
		if err != nil {
			return nil, err
		}
		return jString(s), nil
	case c == '[':
		p.depth++
		if p.depth > 128 {
			return nil, p.err("recursion limit exceeded")
		}
		p.i++
		arr := jArray()
		first := true
		for {
			c, ok := p.parseWhitespace()
			if !ok {
				return nil, p.peekErr("EOF while parsing a list")
			}
			if c == ']' {
				break
			}
			if !first {
				if c != ',' {
					return nil, p.peekErr("expected `,` or `]`")
				}
				p.i++
				c, ok = p.parseWhitespace()
				if !ok {
					return nil, p.peekErr("EOF while parsing a value")
				}
				if c == ']' {
					return nil, p.peekErr("trailing comma")
				}
			}
			first = false
			v, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			arr.Arr = append(arr.Arr, v)
		}
		p.depth--
		p.i++
		return arr, nil
	case c == '{':
		p.depth++
		if p.depth > 128 {
			return nil, p.err("recursion limit exceeded")
		}
		p.i++
		obj := jObject()
		first := true
		for {
			c, ok := p.parseWhitespace()
			if !ok {
				return nil, p.peekErr("EOF while parsing an object")
			}
			if c == '}' {
				break
			}
			if !first {
				if c != ',' {
					return nil, p.peekErr("expected `,` or `}`")
				}
				p.i++
				c, ok = p.parseWhitespace()
				if !ok {
					return nil, p.peekErr("EOF while parsing a value")
				}
				if c == '}' {
					return nil, p.peekErr("trailing comma")
				}
			}
			first = false
			if c != '"' {
				return nil, p.peekErr("key must be a string")
			}
			p.i++
			k, err := p.parseStr()
			if err != nil {
				return nil, err
			}
			c, ok = p.parseWhitespace()
			if !ok {
				return nil, p.peekErr("EOF while parsing an object")
			}
			if c != ':' {
				return nil, p.peekErr("expected `:`")
			}
			p.i++
			v, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			obj.Set(k, v)
		}
		p.depth--
		p.i++
		return obj, nil
	}
	return nil, p.peekErr("expected value")
}

func numToValue(n parsedNum) *JValue {
	return &JValue{Kind: JNumber, NK: n.kind, U: n.u, I: n.i, F: n.f}
}

// ParseJSON parses a complete JSON document.
func ParseJSON(s []byte) (*JValue, *JSONError) {
	p := &jsonParser{s: s}
	v, err := p.parseValue()
	if err != nil {
		return nil, err
	}
	if _, ok := p.parseWhitespace(); ok {
		return nil, p.peekErr("trailing characters")
	}
	return v, nil
}

// ---------- validity check (IgnoredAny) ----------

func (p *jsonParser) ignoreValue() *JSONError {
	c, ok := p.parseWhitespace()
	if !ok {
		return p.peekErr("EOF while parsing a value")
	}
	switch {
	case c == 'n':
		p.i++
		return p.parseIdent("ull")
	case c == 't':
		p.i++
		return p.parseIdent("rue")
	case c == 'f':
		p.i++
		return p.parseIdent("alse")
	case c == '-':
		p.i++
		return p.ignoreInteger()
	case c >= '0' && c <= '9':
		return p.ignoreInteger()
	case c == '"':
		p.i++
		return p.ignoreStr()
	case c == '[' || c == '{':
		// serde_json ignore_value uses an explicit stack
		var stack []byte
		stack = append(stack, c)
		p.i++
		enclosing := c
		for {
			first := true
			_ = first
			c, ok := p.parseWhitespace()
			if !ok {
				if enclosing == '[' {
					return p.peekErr("EOF while parsing a list")
				}
				return p.peekErr("EOF while parsing an object")
			}
			_ = c
			// handled by recursive approach below
			p.i--
			break
		}
		p.i++
		_ = stack
		return p.ignoreContainerRec(enclosing)
	}
	return p.peekErr("expected value")
}

func (p *jsonParser) ignoreContainerRec(open byte) *JSONError {
	closeCh := byte(']')
	eofMsg := "EOF while parsing a list"
	if open == '{' {
		closeCh = '}'
		eofMsg = "EOF while parsing an object"
	}
	first := true
	for {
		c, ok := p.parseWhitespace()
		if !ok {
			return p.peekErr(eofMsg)
		}
		if c == closeCh {
			p.i++
			return nil
		}
		if !first {
			if c != ',' {
				if open == '[' {
					return p.peekErr("expected `,` or `]`")
				}
				return p.peekErr("expected `,` or `}`")
			}
			p.i++
			c, ok = p.parseWhitespace()
			if !ok {
				return p.peekErr("EOF while parsing a value")
			}
			if c == closeCh {
				return p.peekErr("trailing comma")
			}
		}
		first = false
		if open == '{' {
			if c != '"' {
				return p.peekErr("key must be a string")
			}
			p.i++
			if err := p.ignoreStr(); err != nil {
				return err
			}
			c, ok = p.parseWhitespace()
			if !ok {
				return p.peekErr("EOF while parsing an object")
			}
			if c != ':' {
				return p.peekErr("expected `:`")
			}
			p.i++
		}
		if err := p.ignoreValue(); err != nil {
			return err
		}
	}
}

func (p *jsonParser) ignoreInteger() *JSONError {
	c, ok := p.next()
	if !ok {
		return p.err("EOF while parsing a value")
	}
	switch {
	case c == '0':
		if d := p.peekOrNull(); d >= '0' && d <= '9' {
			return p.peekErr("invalid number")
		}
	case c >= '1' && c <= '9':
		for {
			d := p.peekOrNull()
			if d < '0' || d > '9' {
				break
			}
			p.i++
		}
	default:
		return p.err("invalid number")
	}
	switch p.peekOrNull() {
	case '.':
		return p.ignoreDecimal()
	case 'e', 'E':
		return p.ignoreExponent()
	}
	return nil
}

func (p *jsonParser) ignoreDecimal() *JSONError {
	p.i++
	at := false
	for {
		d := p.peekOrNull()
		if d < '0' || d > '9' {
			break
		}
		p.i++
		at = true
	}
	if !at {
		return p.peekErr("invalid number")
	}
	switch p.peekOrNull() {
	case 'e', 'E':
		return p.ignoreExponent()
	}
	return nil
}

func (p *jsonParser) ignoreExponent() *JSONError {
	p.i++
	switch p.peekOrNull() {
	case '+', '-':
		p.i++
	}
	c, ok := p.next()
	if !ok {
		return p.err("EOF while parsing a value")
	}
	if c < '0' || c > '9' {
		return p.err("invalid number")
	}
	for {
		d := p.peekOrNull()
		if d < '0' || d > '9' {
			break
		}
		p.i++
	}
	return nil
}

func (p *jsonParser) ignoreStr() *JSONError {
	for {
		for p.i < len(p.s) {
			c := p.s[p.i]
			if c == '"' || c == '\\' || c < 0x20 {
				break
			}
			p.i++
		}
		if p.i == len(p.s) {
			return p.err("EOF while parsing a string")
		}
		c := p.s[p.i]
		switch {
		case c == '"':
			p.i++
			return nil
		case c == '\\':
			p.i++
			e, ok := p.next()
			if !ok {
				return p.err("EOF while parsing a string")
			}
			switch e {
			case '"', '\\', '/', 'b', 'f', 'n', 'r', 't':
			case 'u':
				if _, err := p.decodeHexEscape(); err != nil {
					return err
				}
			default:
				return p.err("invalid escape")
			}
		default:
			p.i++
			return p.err("control character (\\u0000-\\u001F) found while parsing a string")
		}
	}
}

// ValidJSON reports whether s is a single valid JSON document.
func ValidJSON(s []byte) bool {
	p := &jsonParser{s: s}
	if err := p.ignoreValue(); err != nil {
		return false
	}
	if _, ok := p.parseWhitespace(); ok {
		return false
	}
	return true
}

// ---------- serialization ----------

func ryuFormat(f float64) string {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return "null"
	}
	if f == 0 {
		if math.Signbit(f) {
			return "-0.0"
		}
		return "0.0"
	}
	neg := f < 0
	if neg {
		f = -f
	}
	// shortest digits
	s := strconv.FormatFloat(f, 'e', -1, 64) // d.ddddde±XX
	mant, expStr, _ := strings.Cut(s, "e")
	digits := strings.Replace(mant, ".", "", 1)
	e, _ := strconv.Atoi(expStr)
	length := len(digits)
	k := e - (length - 1) // value = digits * 10^k
	kk := length + k      // 10^(kk-1) <= v < 10^kk
	var out string
	switch {
	case 0 <= k && kk <= 16:
		out = digits + strings.Repeat("0", k) + ".0"
	case 0 < kk && kk <= 16:
		out = digits[:kk] + "." + digits[kk:]
	case -5 < kk && kk <= 0:
		out = "0." + strings.Repeat("0", -kk) + digits
	case length == 1:
		out = digits + "e" + strconv.Itoa(kk-1)
	default:
		out = digits[:1] + "." + digits[1:] + "e" + strconv.Itoa(kk-1)
	}
	if neg {
		return "-" + out
	}
	return out
}

func writeJSONString(b *strings.Builder, s string) {
	b.WriteByte('"')
	const hex = "0123456789abcdef"
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var esc string
		switch c {
		case '"':
			esc = "\\\""
		case '\\':
			esc = "\\\\"
		case '\b':
			esc = "\\b"
		case '\f':
			esc = "\\f"
		case '\n':
			esc = "\\n"
		case '\r':
			esc = "\\r"
		case '\t':
			esc = "\\t"
		default:
			if c < 0x20 {
				esc = "\\u00" + string(hex[c>>4]) + string(hex[c&15])
			} else {
				continue
			}
		}
		b.WriteString(s[start:i])
		b.WriteString(esc)
		start = i + 1
	}
	b.WriteString(s[start:])
	b.WriteByte('"')
}

func numString(v *JValue) string {
	switch v.NK {
	case NumU64:
		return strconv.FormatUint(v.U, 10)
	case NumI64:
		return strconv.FormatInt(v.I, 10)
	default:
		return ryuFormat(v.F)
	}
}

// CompactJSON serializes like serde_json::to_string.
func CompactJSON(v *JValue) string {
	var b strings.Builder
	writeCompact(&b, v)
	return b.String()
}

func writeCompact(b *strings.Builder, v *JValue) {
	switch v.Kind {
	case JNull:
		b.WriteString("null")
	case JBool:
		if v.Bool {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case JNumber:
		b.WriteString(numString(v))
	case JString:
		writeJSONString(b, v.Str)
	case JArray:
		b.WriteByte('[')
		for i, e := range v.Arr {
			if i > 0 {
				b.WriteByte(',')
			}
			writeCompact(b, e)
		}
		b.WriteByte(']')
	case JObject:
		b.WriteByte('{')
		for i, k := range v.Keys {
			if i > 0 {
				b.WriteByte(',')
			}
			writeJSONString(b, k)
			b.WriteByte(':')
			writeCompact(b, v.Vals[k])
		}
		b.WriteByte('}')
	}
}

// ---------- streaming pretty transcoder ----------

type prettyWriter struct {
	b         strings.Builder
	indent    string
	level     int
	hasValue  bool
}

func (w *prettyWriter) writeIndent() {
	for i := 0; i < w.level; i++ {
		w.b.WriteString(w.indent)
	}
}

// TranscodePretty parses JSON from s and writes pretty output; on error the
// partial output is returned together with the error.
func TranscodePretty(s []byte, indent string) (string, *JSONError) {
	p := &jsonParser{s: s}
	w := &prettyWriter{indent: indent}
	err := p.transcodeValue(w)
	if err == nil {
		if _, ok := p.parseWhitespace(); ok {
			err = p.peekErr("trailing characters")
		}
	}
	return w.b.String(), err
}

func (p *jsonParser) transcodeValue(w *prettyWriter) *JSONError {
	c, ok := p.parseWhitespace()
	if !ok {
		return p.peekErr("EOF while parsing a value")
	}
	switch {
	case c == 'n':
		p.i++
		if err := p.parseIdent("ull"); err != nil {
			return err
		}
		w.b.WriteString("null")
	case c == 't':
		p.i++
		if err := p.parseIdent("rue"); err != nil {
			return err
		}
		w.b.WriteString("true")
	case c == 'f':
		p.i++
		if err := p.parseIdent("alse"); err != nil {
			return err
		}
		w.b.WriteString("false")
	case c == '-' || (c >= '0' && c <= '9'):
		pos := true
		if c == '-' {
			p.i++
			pos = false
		}
		n, err := p.parseAnyNumber(pos)
		if err != nil {
			return err
		}
		w.b.WriteString(numString(numToValue(n)))
	case c == '"':
		p.i++
		s, err := p.parseStr()
		if err != nil {
			return err
		}
		writeJSONString(&w.b, s)
	case c == '[':
		p.depth++
		if p.depth > 128 {
			return p.err("recursion limit exceeded")
		}
		p.i++
		w.level++
		w.hasValue = false
		w.b.WriteByte('[')
		first := true
		for {
			c, ok := p.parseWhitespace()
			if !ok {
				return p.peekErr("EOF while parsing a list")
			}
			if c == ']' {
				break
			}
			if !first {
				if c != ',' {
					return p.peekErr("expected `,` or `]`")
				}
				p.i++
				c, ok = p.parseWhitespace()
				if !ok {
					return p.peekErr("EOF while parsing a value")
				}
				if c == ']' {
					return p.peekErr("trailing comma")
				}
			}
			if first {
				w.b.WriteByte('\n')
			} else {
				w.b.WriteString(",\n")
			}
			w.writeIndent()
			first = false
			if err := p.transcodeValue(w); err != nil {
				return err
			}
			w.hasValue = true
		}
		p.depth--
		p.i++
		w.level--
		if w.hasValue {
			w.b.WriteByte('\n')
			w.writeIndent()
		}
		w.b.WriteByte(']')
	case c == '{':
		p.depth++
		if p.depth > 128 {
			return p.err("recursion limit exceeded")
		}
		p.i++
		w.level++
		w.hasValue = false
		w.b.WriteByte('{')
		first := true
		for {
			c, ok := p.parseWhitespace()
			if !ok {
				return p.peekErr("EOF while parsing an object")
			}
			if c == '}' {
				break
			}
			if !first {
				if c != ',' {
					return p.peekErr("expected `,` or `}`")
				}
				p.i++
				c, ok = p.parseWhitespace()
				if !ok {
					return p.peekErr("EOF while parsing a value")
				}
				if c == '}' {
					return p.peekErr("trailing comma")
				}
			}
			if c != '"' {
				return p.peekErr("key must be a string")
			}
			if first {
				w.b.WriteByte('\n')
			} else {
				w.b.WriteString(",\n")
			}
			w.writeIndent()
			first = false
			p.i++
			k, err := p.parseStr()
			if err != nil {
				return err
			}
			writeJSONString(&w.b, k)
			c, ok = p.parseWhitespace()
			if !ok {
				return p.peekErr("EOF while parsing an object")
			}
			if c != ':' {
				return p.peekErr("expected `:`")
			}
			p.i++
			w.b.WriteString(": ")
			if err := p.transcodeValue(w); err != nil {
				return err
			}
			w.hasValue = true
		}
		p.depth--
		p.i++
		w.level--
		if w.hasValue {
			w.b.WriteByte('\n')
			w.writeIndent()
		}
		w.b.WriteByte('}')
	default:
		return p.peekErr("expected value")
	}
	return nil
}
