// decodeUTF8Lossy mimics String::from_utf8_lossy / encoding_rs replacement behaviour.
func decodeUTF8Lossy(b []byte) string {
	if utf8.Valid(b) {
		return string(b)
	}
	var sb strings.Builder
	for len(b) > 0 {
		r, size := utf8.DecodeRune(b)
		if r == utf8.RuneError && size <= 1 {
			// determine maximal invalid subpart length per WHATWG
			n := invalidSubpartLen(b)
			sb.WriteRune(0xfffd)
			b = b[n:]
			continue
		}
		sb.WriteRune(r)
		b = b[size:]
	}
	return sb.String()
}

func invalidSubpartLen(b []byte) int {
	c := b[0]
	var need int
	lower, upper := byte(0x80), byte(0xbf)
	switch {
	case c >= 0xc2 && c <= 0xdf:
		need = 1
	case c >= 0xe0 && c <= 0xef:
		need = 2
		if c == 0xe0 {
			lower = 0xa0
		} else if c == 0xed {
			upper = 0x9f
		}
	case c >= 0xf0 && c <= 0xf4:
		need = 3
		if c == 0xf0 {
			lower = 0x90
		} else if c == 0xf4 {
			upper = 0x8f
		}
	default:
		return 1
	}
	i := 1
	for k := 0; k < need; k++ {
		if i >= len(b) {
			return i
		}
		if b[i] < lower || b[i] > upper {
			return i
		}
		lower, upper = 0x80, 0xbf
		i++
	}
	return i
}

// decodeWith decodes bytes in the named encoding (WHATWG name).
func decodeWith(enc string, b []byte) string {
	switch enc {
	case "UTF-8", "":
		b = trimBOM(b, []byte{0xef, 0xbb, 0xbf})
		return decodeUTF8Lossy(b)
	case "UTF-16LE", "UTF-16BE":
		be := enc == "UTF-16BE"
		if len(b) >= 2 {
			if !be && b[0] == 0xff && b[1] == 0xfe {
				b = b[2:]
			} else if be && b[0] == 0xfe && b[1] == 0xff {
				b = b[2:]
			}
		}
		var u []uint16
		for i := 0; i+1 < len(b); i += 2 {
			if be {
				u = append(u, uint16(b[i])<<8|uint16(b[i+1]))
			} else {
				u = append(u, uint16(b[i+1])<<8|uint16(b[i]))
			}
		}
		s := string(utf16.Decode(u))
		if len(b)%2 == 1 {
			s += "\ufffd"
		}
		return s
	case "replacement":
		if len(b) == 0 {
			return ""
		}
		return "\ufffd"
	case "x-user-defined":
		var sb strings.Builder
		for _, c := range b {
			if c < 0x80 {
				sb.WriteByte(c)
			} else {
				sb.WriteRune(0xf780 + rune(c) - 0x80)
			}
		}
		return sb.String()
	}
	if t, ok := singleByteTables[enc]; ok {
		var sb strings.Builder
		for _, c := range b {
			if c < 0x80 {
				sb.WriteByte(c)
			} else {
				sb.WriteRune(t[c-0x80])
			}
		}
		return sb.String()
	}
	// unsupported multi-byte encodings: fall back to lossy utf-8
	return decodeUTF8Lossy(b)
}

func trimBOM(b []byte, bom []byte) []byte {
	if len(b) >= len(bom) && string(b[:len(bom)]) == string(bom) {
		return b[len(bom):]
	}
	return b
}
