package main

import (
	"errors"
	"fmt"
	"os"
	"strings"
	"unicode"
	"unicode/utf8"
)

type ItemKind int

const (
	ItemHeader ItemKind = iota
	ItemHeaderFile
	ItemHeaderToUnset
	ItemURLParam
	ItemURLParamFile
	ItemDataField
	ItemDataFieldFile
	ItemJSONField
	ItemJSONFieldFile
	ItemFormFile
)

type RequestItem struct {
	Kind     ItemKind
	Key      string
	RawKey   string
	Value    string
	JSON     *JValue
	FileType *string
	FileName *string
	Orig     string
}

const itemSpecialChars = "=@:;\\"

var itemSeps = []string{"==@", "=@", ":=@", ":@", "==", ":=", "=", "@", ":"}

// rustDebugStr formats a string like Rust's {:?}.
func rustDebugStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		case 0:
			b.WriteString("\\0")
		default:
			if r == utf8.RuneError {
				if _, sz := utf8.DecodeRuneInString(s[i:]); sz == 1 {
					b.WriteString("\\u{fffd}")
					continue
				}
			}
			if !unicode.IsPrint(r) && r != ' ' && !(r == 0xa0) {
				b.WriteString(fmt.Sprintf("\\u{%x}", r))
			} else if i == 0 && unicode.Is(unicode.Mn, r) {
				b.WriteString(fmt.Sprintf("\\u{%x}", r))
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

type itemParseError struct{ msg string }

func (e *itemParseError) Error() string { return e.msg }

func splitItem(item string) (key, rawKey, sep, value string, ok bool) {
	var kb, rb strings.Builder
	runes := []rune(item)
	// byte offsets
	offs := make([]int, len(runes)+1)
	o := 0
	for i, r := range runes {
		offs[i] = o
		o += utf8.RuneLen(r)
	}
	offs[len(runes)] = o
	for i := 0; i < len(runes); i++ {
		ch := runes[i]
		if ch == '\\' {
			if i+1 < len(runes) {
				next := runes[i+1]
				if strings.ContainsRune(itemSpecialChars, next) {
					kb.WriteRune(next)
					if next == '\\' {
						rb.WriteString("\\\\")
					} else {
						rb.WriteRune('\\')
						rb.WriteRune(next)
					}
				} else {
					kb.WriteRune(ch)
					kb.WriteRune(next)
					rb.WriteRune(ch)
					rb.WriteRune(next)
				}
				i++
			} else {
				kb.WriteRune(ch)
				rb.WriteRune(ch)
			}
			continue
		}
		rest := item[offs[i]:]
		for _, s := range itemSeps {
			if strings.HasPrefix(rest, s) {
				return kb.String(), rb.String(), s, rest[len(s):], true
			}
		}
		if ch == ';' && i == len(runes)-1 {
			return kb.String(), rb.String(), ";", "", true
		}
		kb.WriteRune(ch)
		rb.WriteRune(ch)
	}
	return "", "", "", "", false
}

func parseRequestItem(item string) (*RequestItem, error) {
	key, rawKey, sep, value, ok := splitItem(item)
	invalid := func(extra string) error {
		msg := "Invalid value for '[REQUEST_ITEM]...': " + rustDebugStr(item)
		if extra != "" {
			msg += " " + extra
		}
		return &itemParseError{msg}
	}
	if !ok {
		return nil, invalid("")
	}
	it := &RequestItem{Key: key, RawKey: rawKey, Value: value, Orig: item}
	switch sep {
	case "==":
		it.Kind = ItemURLParam
	case "==@":
		it.Kind = ItemURLParamFile
	case "=":
		it.Kind = ItemDataField
	case "=@":
		it.Kind = ItemDataFieldFile
	case ":=":
		it.Kind = ItemJSONField
		v, err := ParseJSON([]byte(value))
		if err != nil {
			return nil, invalid(err.Error())
		}
		it.JSON = v
