	var kb, rb strings.Builder
	runes := []rune(item)
	// byte offsets
	offs := make([]int, len(runes)+1)
	o := 0
	for i, r := range runes {
		offs[i] = o
		o += utf8.RuneLen(r)
	}
	offs[len(runes)] = o
	for i := 0; i < len(runes); i++ {
		ch := runes[i]
		if ch == '\\' {
