// rustIOError formats like std::io::Error Display.
type rustIOError struct {
	msg   string
	errno syscall.Errno
}

func (e *rustIOError) Error() string { return e.msg }

func errnoString(en syscall.Errno) string {
	s := en.Error()
	if s == "" {
		return s
	}
	b := []byte(s)
	if b[0] >= 'a' && b[0] <= 'z' {
		b[0] -= 32
	}
	return string(b)
}

func ioErr(err error) error {
	if err == nil {
		return nil
	}
	var en syscall.Errno
	if errors.As(err, &en) {
		return &rustIOError{msg: errnoString(en) + " (os error " + itoa(int(en)) + ")", errno: en}
	}
	var pe *fs.PathError
	if errors.As(err, &pe) {
		return ioErr(pe.Err)
	}
	var le *os.LinkError
	if errors.As(err, &le) {
		return ioErr(le.Err)
	}
	return err
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b [20]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

// chainError represents an error with a cause chain (like anyhow).
type chainError struct {
	msg    string
	causes []string
}

func (e *chainError) Error() string { return e.msg }

// formatAnyhow formats like anyhow's Debug output.
func formatAnyhow(err error) string {
	var ce *chainError
	if errors.As(err, &ce) {
		s := ce.msg
		if len(ce.causes) == 1 {
			s += "\n\nCaused by:\n    " + indentCont(ce.causes[0], "    ")
		} else if len(ce.causes) > 1 {
			s += "\n\nCaused by:"
			for i, c := range ce.causes {
				s += "\n    " + itoa(i) + ": " + indentCont(c, "       ")
			}
		}
		return s
	}
	return err.Error()
}

func indentCont(s, ind string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		out += string(s[i])
		if s[i] == '\n' {
			out += ind
		}
	}
	return out
}
