			toks = append(toks, pathTok{kind: 1, start: i, end: i + 1})
		case c == ']':
			flush(i)
			toks = append(toks, pathTok{kind: 2, start: i, end: i + 1})
		default:
			if curStart < 0 {
				curStart = i
			}
			cur.WriteRune(c)
		}
	}
	flush(len(runes))
	return toks
}

func parseNestedPath(raw string) ([]pathComp, error) {
	toks := tokenizePath(raw)
	n := len([]rune(raw))
	perr := func(msg string, pos int) error {
		return &nestedJSONError{msg: msg, path: raw, start: pos, end: pos + 1}
	}
	var comps []pathComp
	i := 0
	if len(toks) == 0 {
		return nil, perr("expected text or '['", 0)
	}
	parseBracket := func(rootFirst bool) error {
		// toks[i] is '['
		open := toks[i]
		i++
		if i >= len(toks) {
			if rootFirst {
				return perr("expected number or ']'", n)
			}
			return perr("expected text, number or ']'", n)
		}
		t := toks[i]
		switch t.kind {
		case 2:
			comps = append(comps, pathComp{kind: pkAppend, start: open.start, end: t.end})
			i++
			return nil
		case 1:
			if rootFirst {
				return perr("expected number or ']'", t.start)
			}
			return perr("expected text, number or ']'", t.start)
		}
		// text
		idx, err := rustParseUsize(t.text)
		isNum := err == nil
		if rootFirst && !isNum {
			return perr("expected number or ']'", t.start)
		}
		i++
		if i >= len(toks) {
			return perr("expected ']'", n)
		}
		if toks[i].kind != 2 {
			return perr("expected ']'", toks[i].start)
		}
		c := pathComp{start: open.start, end: toks[i].end}
		if isNum {
			c.kind = pkIndex
			c.index = idx
		} else {
			c.kind = pkKey
			c.key = t.text
		}
		comps = append(comps, c)
		i++
		return nil
	}
	if toks[0].kind == 0 {
		comps = append(comps, pathComp{kind: pkKey, key: toks[0].text, start: toks[0].start, end: toks[0].end})
		i = 1
	} else if toks[0].kind == 1 {
		if err := parseBracket(true); err != nil {
			return nil, err
		}
	} else {
		return nil, perr("expected text or '['", toks[0].start)
	}
	for i < len(toks) {
		if toks[i].kind != 1 {
			return nil, perr("expected '['", toks[i].start)
		}
		if err := parseBracket(false); err != nil {
			return nil, err
		}
	}
	return comps, nil
}

func jsonTypeName(v *JValue) string {
	switch v.Kind {
	case JNull:
		return "null"
	case JBool:
		return "bool"
	case JNumber:
		return "number"
	case JString:
		return "string"
	case JArray:
		return "array"
	}
	return "object"
}

func objectFor(k pathKind) *JValue {
	if k == pkKey {
		return jObject()
	}
	return jArray()
}

// insertNested sets value at raw path in root (root may be nil) and returns the new root.
func insertNested(root *JValue, raw string, value *JValue) (*JValue, error) {
	comps, err := parseNestedPath(raw)
	if err != nil {
		return root, err
	}
	if root == nil {
		root = objectFor(comps[0].kind)
	}
	cursor := root
	runes := []rune(raw)
	for i, c := range comps {
		var want JKind
		op := "key"
		switch c.kind {
		case pkKey:
			want = JObject
		case pkIndex:
			want = JArray
			op = "index"
		case pkAppend:
			want = JArray
			op = "append"
		}
		if cursor.Kind != want {
			wantName := "object"
			if want == JArray {
				wantName = "array"
			}
			msg := "Can't perform '" + op + "' based access on '" + string(runes[:c.start]) + "' which has a type of '" + jsonTypeName(cursor) + "' but this operation requires a type of '" + wantName + "'."
			return root, &nestedJSONError{msg: msg, path: raw, start: c.start, end: c.end}
		}
		last := i == len(comps)-1
		switch c.kind {
		case pkKey:
			if last {
				cursor.Set(c.key, value)
				return root, nil
			}
			ex := cursor.Get(c.key)
			if ex == nil {
				ex = objectFor(comps[i+1].kind)
				cursor.Set(c.key, ex)
			}
			cursor = ex
		case pkIndex:
			if c.index > 50000000 {
				return root, &chainError{msg: "memory allocation failed"}
			}
			idx := int(c.index)
			fresh := idx >= len(cursor.Arr)
			for len(cursor.Arr) <= idx {
				cursor.Arr = append(cursor.Arr, jNull())
			}
			if last {
				cursor.Arr[idx] = value
				return root, nil
			}
			if fresh {
				cursor.Arr[idx] = objectFor(comps[i+1].kind)
			}
			cursor = cursor.Arr[idx]
		case pkAppend:
			if last {
				cursor.Arr = append(cursor.Arr, value)
				return root, nil
			}
			nv := objectFor(comps[i+1].kind)
			cursor.Arr = append(cursor.Arr, nv)
			cursor = nv
		}
	}
	return root, nil
}
