		return
	}
	h.entries = append(h.entries, &hentry{name: name, vals: []string{value}})
}

func (h *HeaderMap) Insert(name, value string) {
	name = strings.ToLower(name)
	if i := h.find(name); i >= 0 {
		h.entries[i].vals = []string{value}
		return
	}
	h.entries = append(h.entries, &hentry{name: name, vals: []string{value}})
}

// Remove uses swap_remove semantics.
func (h *HeaderMap) Remove(name string) bool {
	name = strings.ToLower(name)
	i := h.find(name)
	if i < 0 {
		return false
	}
	last := len(h.entries) - 1
	h.entries[i] = h.entries[last]
	h.entries = h.entries[:last]
	return true
}

func (h *HeaderMap) Get(name string) (string, bool) {
	if i := h.find(strings.ToLower(name)); i >= 0 {
		return h.entries[i].vals[0], true
	}
	return "", false
}

func (h *HeaderMap) GetAll(name string) []string {
	if i := h.find(strings.ToLower(name)); i >= 0 {
		return h.entries[i].vals
	}
	return nil
}

func (h *HeaderMap) Contains(name string) bool { return h.find(strings.ToLower(name)) >= 0 }

func (h *HeaderMap) Clone() *HeaderMap {
	n := &HeaderMap{}
	for _, e := range h.entries {
		n.entries = append(n.entries, &hentry{name: e.name, vals: append([]string{}, e.vals...)})
	}
	return n
}

// Pairs returns all (name, value) pairs in iteration order.
func (h *HeaderMap) Pairs() [][2]string {
	var out [][2]string
	for _, e := range h.entries {
		for _, v := range e.vals {
			out = append(out, [2]string{e.name, v})
		}
	}
	return out
}

func (h *HeaderMap) Len() int { return len(h.entries) }

// ReplaceFrom mimics reqwest's replace_headers.
func (h *HeaderMap) ReplaceFrom(src *HeaderMap) {
	for _, e := range src.entries {
		if i := h.find(e.name); i >= 0 {
			h.entries[i].vals = append([]string{}, e.vals...)
		} else {
			h.entries = append(h.entries, &hentry{name: e.name, vals: append([]string{}, e.vals...)})
		}
	}
}

func (h *HeaderMap) SortedPairs() [][2]string {
	es := append([]*hentry{}, h.entries...)
	sort.SliceStable(es, func(i, j int) bool { return es[i].name < es[j].name })
	var out [][2]string
	for _, e := range es {
		for _, v := range e.vals {
			out = append(out, [2]string{e.name, v})
		}
	}
	return out
}

func isTokenChar(c byte) bool {
	if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' {
		return true
	}
	return strings.IndexByte("!#$%&'*+-.^_`|~", c) >= 0
}

var errInvalidHeaderName = errors.New("invalid HTTP header name")
var errInvalidHeaderValue = errors.New("failed to parse header value")

func validHeaderName(s string) error {
	if s == "" {
		return errInvalidHeaderName
	}
	for i := 0; i < len(s); i++ {
