			return errInvalidHeaderName
		}
	}
	return nil
}

func validHeaderValue(s string) error {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 32 && c != 127 || c == '\t') {
			return errInvalidHeaderValue
		}
	}
	return nil
}

func titleCase(name string) string {
	b := []byte(name)
	up := true
	for i, c := range b {
		if up {
			if c >= 'a' && c <= 'z' {
				b[i] = c - 32
			}
		} else if c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
		up = c == '-'
	}
	return string(b)
}

// displayHeaderValue renders header value bytes like xh does.
func displayHeaderValue(v string) string {
	ascii := true
	for i := 0; i < len(v); i++ {
		if v[i] >= 0x80 {
			ascii = false
			break
		}
	}
	if ascii {
		return v
	}
	var b strings.Builder
	for i := 0; i < len(v); i++ {
		b.WriteRune(rune(v[i]))
	}
	if utf8.ValidString(v) {
		b.WriteString(" (UTF-8: " + v + ")")
	}
	return b.String()
}
