package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var stdout *bufio.Writer

type Names struct {
	Usage string // file_name for clap usage
	Stem  string // file_stem for logs/completions
}

func getNames() Names {
	a0 := ""
	if len(os.Args) > 0 {
		a0 = os.Args[0]
	}
	if a0 == "" {
		return Names{Usage: "xh", Stem: "xh"}
	}
	base := filepath.Base(a0)
	stem := base
	if i := strings.LastIndex(base, "."); i > 0 {
		stem = base[:i]
	}
	return Names{Usage: base, Stem: stem}
}

func testMode() bool {
	_, ok := os.LookupEnv("XH_TEST_MODE")
	return ok
}

func testPretendTerm() bool {
	_, ok := os.LookupEnv("XH_TEST_MODE_TERM")
	return ok
}

func testDefaultColor() bool {
	_, ok := os.LookupEnv("XH_TEST_MODE_COLOR")
	return ok
}

var logName = "xh"
var quietLevel = 0

func warn(msg string) {
	if quietLevel >= 2 {
		return
	}
	stdout.Flush()
	fmt.Fprintf(os.Stderr, "%s: warning: %s\n", logName, msg)
}

func main() {
	stdout = bufio.NewWriterSize(os.Stdout, 64*1024)
	code := realMain()
	stdout.Flush()
	os.Exit(code)
}

func configDir() string {
	if d, ok := os.LookupEnv("XH_CONFIG_DIR"); ok {
		return d
	}
	if d := os.Getenv("XDG_CONFIG_HOME"); d != "" && filepath.IsAbs(d) {
		return filepath.Join(d, "xh")
	}
	h, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(h, ".config", "xh")
}

func loadDefaultOptions() []string {
	dir := configDir()
	if dir == "" {
		return nil
	}
	path := filepath.Join(dir, "config.json")
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		fmt.Fprintf(os.Stderr, "\nxh: warning: Unable to read config file: %s\n\n", ioErr(err).Error())
		return nil
	}
	opts, perr := parseConfig(data)
	if perr != nil {
		fmt.Fprintf(os.Stderr, "\nxh: warning: Unable to parse config file: %s\n\n", perr.Error())
		return nil
	}
	return opts
}

func realMain() int {
	names := getNames()
	logName = names.Stem
	rawArgs := os.Args[1:]
	defaults := loadDefaultOptions()
	all := append(append([]string{}, defaults...), rawArgs...)
	m, err := parseCLI(names.Usage, all)
	if err != nil {
		if ce, ok := err.(*ClapError); ok {
			if ce.ToStdout {
				stdout.WriteString(ce.Message)
			} else {
				stdout.Flush()
				os.Stderr.WriteString(ce.Message)
			}
			return ce.ExitCode
		}
		fmt.Fprintf(os.Stderr, "%s: error: %s\n", logName, err)
		return 1
	}
	cli, err := buildCli(m, names)
	if err != nil {
		if ce, ok := err.(*ClapError); ok {
			if ce.ToStdout {
				stdout.WriteString(ce.Message)
			} else {
				stdout.Flush()
				os.Stderr.WriteString(ce.Message)
			}
			return ce.ExitCode
		}
		stdout.Flush()
		fmt.Fprintf(os.Stderr, "%s: error: %s\n", logName, formatAnyhow(err))
		return 1
	}
	quietLevel = cli.Quiet
	code, err := run(cli)
	if err != nil {
		stdout.Flush()
		if ee, ok := err.(*exitError); ok {
			return ee.code
		}
		if quietLevel < 1 || true {
			fmt.Fprintf(os.Stderr, "%s: error: %s\n", logName, formatAnyhow(err))
		}
		if te, ok := err.(*chainError); ok && te.timeout {
			return 2
		}
		return 1
	}
	return code
}

type exitError struct{ code int }

func (e *exitError) Error() string { return "exit" }

type Cli struct {
	Names           Names
	RequestType     string // json, form, multipart
	Raw             *string
	Pretty          *string
	FormatOptions   []string
	Style           *string
	ResponseCharset *string
	ResponseMime    *string
	Print           *string
	Headers         bool
	Body            bool
	Meta            bool
	Verbose         int
	Debug           bool
	All             bool
	HistoryPrint    *string
	Quiet           int
	Stream          bool
	Compress        int
	Output          *string
	Download        bool
	Resume          bool
	Session         *string
	SessionReadOnly *string
	AuthType        *string
	Auth            *string
	Bearer          *string
	IgnoreNetrc     bool
	Offline         bool
	CheckStatus     *bool
	Follow          bool
	MaxRedirects    *uint64
	Timeout         *float64
	Proxy           []*proxySpec
	Verify          *string
	Cert            *string
	CertKey         *string
	SSL             *string
	NativeTLS       bool
	DefaultScheme   *string
	HTTPS           bool
	HTTPVersion     *string
	Resolve         []*resolveSpec
	Interface       *string
	IPv4, IPv6      bool
	UnixSocket      *string
	IgnoreStdin     bool
	Curl            bool
	CurlLong        bool
	Generate        *string

	Method      string // "" if not given
	RawURL      string
	URL         *URL
	Items       []*RequestItem
	CompatMode  bool
	HTTPSDefault bool

	explicit map[string]bool
}

func optStr(m *Matches, id string) *string {
	if v, ok := m.Value(id); ok {
		return &v
	}
	return nil
}

var methodRe = regexp.MustCompile(`^[a-zA-Z]+$`)
var schemeRe = regexp.MustCompile(`[a-zA-Z0-9]://.+`)

func buildCli(m *Matches, names Names) (*Cli, error) {
	c := &Cli{Names: names, explicit: map[string]bool{}}
	for _, e := range m.entries {
		c.explicit[e.id] = true
	}
	c.RequestType = "json"
	for _, e := range m.entries {
		switch e.id {
		case "json", "form", "multipart":
			c.RequestType = e.id
		}
	}
	c.Raw = optStr(m, "raw")
	c.Pretty = optStr(m, "pretty")
	c.FormatOptions = m.Values("format_options")
	c.Style = optStr(m, "style")
	c.ResponseCharset = optStr(m, "response_charset")
	c.ResponseMime = optStr(m, "response_mime")
	c.Print = optStr(m, "print")
	c.Headers = m.Flag("headers")
	c.Body = m.Flag("body")
	c.Meta = m.Flag("meta")
	c.Verbose = m.Count("verbose")
	c.Debug = m.Flag("debug")
