		a0 = os.Args[0]
	}
	if a0 == "" {
		return Names{Usage: "xh", Stem: "xh"}
	}
	base := filepath.Base(a0)
	stem := base
	if i := strings.LastIndex(base, "."); i > 0 {
		stem = base[:i]
	}
	return Names{Usage: base, Stem: stem}
}

