			} else {
				stdout.Flush()
				os.Stderr.WriteString(ce.Message)
			}
			return ce.ExitCode
		}
		fmt.Fprintf(os.Stderr, "%s: error: %s\n", logName, err)
		return 1
	}
	cli, err := buildCli(m, names)
