package main

import "strconv"

func (p *jsonParser) unexpectedDesc() (string, *JSONError) {
	// mimics peek_invalid_type: consumes scalars
	c, _ := p.peek()
	switch {
	case c == 'n':
		p.i++
		if err := p.parseIdent("ull"); err != nil {
			return "", err
		}
		return "null", nil
	case c == 't':
		p.i++
		if err := p.parseIdent("rue"); err != nil {
			return "", err
		}
		return "boolean `true`", nil
	case c == 'f':
		p.i++
		if err := p.parseIdent("alse"); err != nil {
			return "", err
		}
		return "boolean `false`", nil
	case c == '-' || (c >= '0' && c <= '9'):
		pos := true
		if c == '-' {
			p.i++
			pos = false
		}
		n, err := p.parseAnyNumber(pos)
		if err != nil {
			return "", err
		}
		switch n.kind {
		case NumU64:
			return "integer `" + strconv.FormatUint(n.u, 10) + "`", nil
		case NumI64:
			return "integer `" + strconv.FormatInt(n.i, 10) + "`", nil
		}
		return "floating point `" + ryuFormat(n.f) + "`", nil
	case c == '"':
		p.i++
		s, err := p.parseStr()
		if err != nil {
			return "", err
		}
		return "string " + rustDebugStr(s), nil
	case c == '[':
		return "sequence", nil
	case c == '{':
		return "map", nil
	}
	return "", p.peekErr("expected value")
}

func (p *jsonParser) invalidType(expected string) *JSONError {
	d, err := p.unexpectedDesc()
	if err != nil {
		return err
	}
	e := p.err("invalid type: " + d + ", expected " + expected)
	return e
}

func (p *jsonParser) parseStringList() ([]string, *JSONError) {
	c, ok := p.parseWhitespace()
	if !ok {
		return nil, p.peekErr("EOF while parsing a value")
	}
	if c != '[' {
		return nil, p.invalidType("a sequence")
	}
	p.i++
	var out []string
	first := true
	for {
		c, ok := p.parseWhitespace()
		if !ok {
			return nil, p.peekErr("EOF while parsing a list")
		}
		if c == ']' {
			p.i++
			return out, nil
		}
		if !first {
			if c != ',' {
				return nil, p.peekErr("expected `,` or `]`")
			}
			p.i++
			c, ok = p.parseWhitespace()
			if !ok {
				return nil, p.peekErr("EOF while parsing a value")
			}
			if c == ']' {
				return nil, p.peekErr("trailing comma")
			}
		}
		first = false
		if c != '"' {
			return nil, p.invalidType("a string")
		}
		p.i++
		s, err := p.parseStr()
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
}

func parseConfig(data []byte) ([]string, error) {
	p := &jsonParser{s: data}
	c, ok := p.parseWhitespace()
	if !ok {
		return nil, p.peekErr("EOF while parsing a value")
	}
