		p.i++
		if err := p.parseIdent("ull"); err != nil {
			return "", err
		}
		return "null", nil
	case c == 't':
		p.i++
		if err := p.parseIdent("rue"); err != nil {
			return "", err
		}
		return "boolean `true`", nil
	case c == 'f':
		p.i++
		if err := p.parseIdent("alse"); err != nil {
			return "", err
		}
		return "boolean `false`", nil
	case c == '-' || (c >= '0' && c <= '9'):
		pos := true
		if c == '-' {
			p.i++
			pos = false
		}
		n, err := p.parseAnyNumber(pos)
		if err != nil {
			return "", err
		}
		switch n.kind {
