		case NumI64:
			return "integer `" + strconv.FormatInt(n.i, 10) + "`", nil
		}
		return "floating point `" + ryuFormat(n.f) + "`", nil
	case c == '"':
		p.i++
		s, err := p.parseStr()
		if err != nil {
			return "", err
		}
		return "string " + rustDebugStr(s), nil
	case c == '[':
		return "sequence", nil
	case c == '{':
		return "map", nil
	}
	return "", p.peekErr("expected value")
}

func (p *jsonParser) invalidType(expected string) *JSONError {
	d, err := p.unexpectedDesc()
	if err != nil {
		return err
	}
	e := p.err("invalid type: " + d + ", expected " + expected)
	return e
}

func (p *jsonParser) parseStringList() ([]string, *JSONError) {
	c, ok := p.parseWhitespace()
	if !ok {
		return nil, p.peekErr("EOF while parsing a value")
	}
	if c != '[' {
		return nil, p.invalidType("a sequence")
	}
	p.i++
	var out []string
	first := true
	for {
		c, ok := p.parseWhitespace()
		if !ok {
			return nil, p.peekErr("EOF while parsing a list")
		}
		if c == ']' {
			p.i++
			return out, nil
		}
		if !first {
			if c != ',' {
				return nil, p.peekErr("expected `,` or `]`")
			}
			p.i++
			c, ok = p.parseWhitespace()
			if !ok {
				return nil, p.peekErr("EOF while parsing a value")
			}
			if c == ']' {
				return nil, p.peekErr("trailing comma")
			}
		}
		first = false
		if c != '"' {
			return nil, p.invalidType("a string")
		}
		p.i++
		s, err := p.parseStr()
		if err != nil {
			return nil, err
		}
