			return nil, retErr
		}
	case '[':
		p.i++
		c, ok := p.parseWhitespace()
		if !ok {
			return nil, p.peekErr("EOF while parsing a list")
		}
		if c == ']' {
			p.i++
			l, col := p.positionOf(p.i)
			return nil, &JSONError{Msg: "invalid length 0, expected struct Config with 1 element", Line: l, Column: col}
		}
		l, err := p.parseStringList()
		if err != nil {
			return nil, err
		}
		opts = l
		c, ok = p.parseWhitespace()
		if !ok {
			return nil, p.peekErr("EOF while parsing a list")
		}
		if c == ']' {
			p.i++
		} else if c == ',' {
			p.i++
			if c2, ok2 := p.parseWhitespace(); ok2 && c2 == ']' {
				return nil, p.peekErr("trailing comma")
			}
			return nil, p.peekErr("trailing characters")
		} else {
			return nil, p.peekErr("trailing characters")
		}
	default:
		return nil, p.invalidType("struct Config")
	}
	if _, ok := p.parseWhitespace(); ok {
		return nil, p.peekErr("trailing characters")
	}
	return opts, nil
}
