		if isMimeToken(c) {
			i++
			continue
		}
		return "", invalidTok(i, c)
	}
	// params
	start = start + 1
	for start < len(s) {
		// name
		for {
			if i >= len(s) {
				return "", &mimeErr{"an equals sign (=) was missing between a parameter and its value"}
			}
			c := s[i]
			if c == ' ' && i == start {
				i++
				start = i
				goto nextParam
			}
			if isMimeToken(c) {
				i++
				continue
			}
			if c == '=' && i > start {
				i++
				start = i
				break
			}
			return "", invalidTok(i, c)
		}
		{
			quoted := false
			for {
				if quoted {
					if i >= len(s) {
						return "", &mimeErr{"a quote (\") was missing from a parameter value"}
					}
					c := s[i]
					if c == '"' && i > start {
						i++
						break
					}
					if isRestrictedQuoted(c) {
						i++
						continue
					}
					return "", invalidTok(i, c)
				}
				if i >= len(s) {
					start = len(s)
					goto nextParam
				}
				c := s[i]
				if c == '"' && i == start {
					quoted = true
					i++
					start = i
					continue
				}
				if isMimeToken(c) {
					i++
					continue
				}
				if c == ';' && i > start {
					i++
					start = i
					goto nextParam
				}
				return "", invalidTok(i, c)
			}
			// after quoted
			for {
				if i >= len(s) {
					start = len(s)
					break
				}
				c := s[i]
				if c == ';' {
					i++
					start = i
					break
				}
				if c == ' ' {
					i++
					continue
				}
				return "", invalidTok(i, c)
			}
		}
	nextParam:
	}
	return strings.ToLower(s[:strings.IndexByte(s, ';')]) + s[strings.IndexByte(s, ';'):], nil
}

