	"bytes"
	"io"
	"os"
	"strings"
)

const binarySuppressor = "+-----------------------------------------+\n| NOTE: binary data not shown in terminal |\n+-----------------------------------------+\n\n"

type OutBuffer struct {
	w          io.Writer
	isTerminal bool
	kind       string // stdout, redirect, file, stderr
	file       *os.File
}

func (b *OutBuffer) Print(s string) error {
	_, err := io.WriteString(b.w, s)
	return err
}

func (b *OutBuffer) Write(p []byte) (int, error) {
	return b.w.Write(p)
}

func (b *OutBuffer) Flush() {
	if b.w == stdout {
		stdout.Flush()
	}
}

type Printer struct {
	buf         *OutBuffer
	color       bool
	indentJSON  bool
	sortHeaders bool
	stream      bool
	theme       string
	jsonIndent  int
}

type ContentType int

const (
	CTUnknown ContentType = iota
	CTJSON
	CTHTML
	CTXML
	CTJS
	CTCSS
	CTText
	CTMultipart
	CTForm
)

func contentTypeOf(ct string) ContentType {
	switch {
	case strings.Contains(ct, "json"):
		return CTJSON
	case strings.Contains(ct, "html"):
		return CTHTML
	case strings.Contains(ct, "xml"):
		return CTXML
	case strings.Contains(ct, "multipart"):
		return CTMultipart
	case strings.Contains(ct, "x-www-form-urlencoded"):
		return CTForm
	case strings.Contains(ct, "javascript"):
		return CTJS
	case strings.Contains(ct, "css"):
		return CTCSS
	case strings.HasPrefix(ct, "text"):
		return CTText
	}
	return CTUnknown
}

func (p *Printer) headersToString(h *HeaderMap, version string) string {
	var pairs [][2]string
	if p.sortHeaders {
		pairs = h.SortedPairs()
	} else {
		pairs = h.Pairs()
	}
	var b strings.Builder
	for _, kv := range pairs {
		name := kv[0]
		if version != "HTTP/2.0" && version != "HTTP/3.0" {
			name = titleCase(name)
		}
		b.WriteString(name)
		b.WriteString(": ")
		b.WriteString(displayHeaderValue(kv[1]))
		b.WriteString("\n")
	}
	return b.String()
}

