	h := req.Headers.Clone()
	if req.BodyKind == BodyBytes {
		if !h.Contains("content-length") {
			h.Insert("content-length", itoa(len(req.Body)))
		}
	}
	if cookieHeader != "" && !h.Contains("cookie") {
		h.Insert("cookie", cookieHeader)
	}
	if req.URL.HasHost && req.URL.Host != "" {
		if !h.Contains("host") {
			var hv string
			if testMode() {
				hv = "http.mock"
			} else if req.URL.Port >= 0 {
				hv = req.URL.Host + ":" + itoa(req.URL.Port)
			} else {
				hv = req.URL.Host
			}
			h.Insert("host", hv)
		}
	}
