}

type Print struct {
	ReqHeaders, ReqBody, RespHeaders, RespBody, RespMeta bool
}

func parsePrint(s string) Print {
	var p Print
	for _, c := range s {
		switch c {
		case 'H':
			p.ReqHeaders = true
		case 'B':
			p.ReqBody = true
		case 'h':
			p.RespHeaders = true
		case 'b':
			p.RespBody = true
		case 'm':
			p.RespMeta = true
		}
	}
	return p
}

func newPrint(c *Cli, isTerminal bool) Print {
	switch {
	case c.Verbose > 0:
		return Print{true, true, true, true, c.Verbose > 1}
	case c.Quiet > 0:
		return Print{}
	case c.Offline:
		return Print{ReqHeaders: true, ReqBody: true}
	case c.Headers:
		return Print{RespHeaders: true}
	case c.Body || !isTerminal:
		return Print{RespBody: true}
	case c.Meta:
		return Print{RespMeta: true}
	}
	return Print{RespHeaders: true, RespBody: true}
}

func stdinIsTerminal() bool { return isTerminal(os.Stdin) }
func stdoutIsTerminal() bool {
	return isTerminal(os.Stdout) || testPretendTerm()
}

func guessPretty(isTerm bool) string {
	if testDefaultColor() {
		return "all"
	}
	if testPretendTerm() {
		return "format"
	}
	if isTerm {
		if _, ok := os.LookupEnv("NO_COLOR"); ok {
			return "format"
		}
		return "all"
	}
	return "none"
}

func run(c *Cli) (int, error) {
	if c.Generate != nil {
		return 0, generate(c.Names, *c.Generate)
	}
	if c.Curl {
		return 0, printCurl(c)
	}
	userHeaders, unset, err := headersFromItems(c.Items)
	if err != nil {
		return 0, err
	}
	useStdin := !(c.IgnoreStdin || stdinIsTerminal() || testPretendTerm())
	bodyItems := hasBodyItems(c.Items)
	if c.Raw != nil && bodyItems {
		return 0, &ClapError{Message: formatClapError("Request body (from --raw) and request data (key=value) cannot be mixed.", "", nil, helpUsage("xh")), ExitCode: 2}
	}
	spec, err := bodyFromItems(c.Items, c.RequestType)
	if err != nil {
		return 0, err
	}
	if useStdin {
		if !spec.isEmpty() {
			return 0, errors.New("Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.")
		}
		if c.Raw != nil {
			return 0, errors.New("Request body from stdin and --raw cannot be mixed. Pass --ignore-stdin to ignore standard input.")
		}
		b, err := readAllStdin()
		if err != nil {
			return 0, err
		}
		spec = &bodySpec{kind: "raw", raw: b}
	} else if c.Raw != nil {
		spec = &bodySpec{kind: "raw", raw: []byte(*c.Raw)}
	}

	method := c.Method
	if method == "" {
		if spec.isEmpty() {
			method = "GET"
		} else {
			method = "POST"
		}
	}

	version := "HTTP/1.1"
	if c.HTTPVersion != nil {
		switch *c.HTTPVersion {
		case "1.0":
			version = "HTTP/1.0"
		case "2", "2-prior-knowledge":
			version = "HTTP/2.0"
		case "3-prior-knowledge":
			version = "HTTP/3.0"
		}
	}

	if c.NativeTLS {
		return 0, errors.New("This binary was built without native-tls support")
	}

	req := &Request{Method: method, URL: c.URL.Clone(), Version: version, Headers: &HeaderMap{}}
	if !req.URL.HasHost || req.URL.Host == "" {
		return 0, &chainError{msg: "builder error for url (" + req.URL.String() + ")", causes: []string{"URL scheme is not allowed"}}
	}
	// URL credentials
	if req.URL.Username != "" || req.URL.Password != "" {
		user := string(pctDecode(req.URL.Username))
		var pass *string
		if req.URL.Password != "" {
			s := string(pctDecode(req.URL.Password))
			pass = &s
		}
		req.URL.Username = ""
		req.URL.Password = ""
		req.Headers.Append("authorization", basicAuthValue(user, pass))
	}
	if c.Download {
		req.Headers.Append("accept-encoding", "identity")
	} else {
		req.Headers.Append("accept-encoding", "gzip, deflate, br, zstd")
	}
	req.Headers.Append("user-agent", userAgent())
	if c.HTTPVersion == nil || *c.HTTPVersion == "1.0" || *c.HTTPVersion == "1.1" {
		req.Headers.Append("connection", "keep-alive")
	}

	switch spec.kind {
	case "json":
		req.Headers.Append("accept", jsonAccept)
		req.Headers.Append("content-type", jsonContentType)
		req.BodyKind = BodyBytes
		req.Body = []byte(CompactJSON(spec.json))
	case "form":
		req.Headers.Append("content-type", formContentType)
		req.BodyKind = BodyBytes
		req.Body = []byte(formEncode(spec.form))
	case "multipart":
		req.Boundary = randomBoundary()
		req.Headers.Append("content-type", "multipart/form-data; boundary="+req.Boundary)
		data, err := encodeMultipart(spec.parts, req.Boundary)
		if err != nil {
			return 0, err
		}
		req.BodyKind = BodyMultipart
		req.Body = data
	case "raw":
		if c.RequestType == "json" {
			req.Headers.Append("accept", jsonAccept)
			req.Headers.Append("content-type", jsonContentType)
		} else {
			req.Headers.Append("content-type", formContentType)
		}
		req.BodyKind = BodyBytes
		req.Body = spec.raw
	case "file":
		ct := ""
		if spec.fileType != nil {
			ct = *spec.fileType
		} else if g := guessMime(spec.filePath); g != "" {
			ct = g
		} else {
			ct = jsonContentType
		}
		req.Headers.Append("content-type", ct)
		data, err := os.ReadFile(expandTilde(spec.filePath))
		if err != nil {
			return 0, ioErr(err)
		}
		req.BodyKind = BodyFile
		req.Body = data
		req.FilePath = spec.filePath
	}

	// auth
	authType := "basic"
	if c.AuthType != nil {
		authType = *c.AuthType
	}
	auth := c.Auth
	if c.Bearer != nil {
		authType = "bearer"
		auth = c.Bearer
	}
	var digestCreds *[2]string
	if auth != nil {
		switch authType {
		case "bearer":
			req.Headers.Append("authorization", "Bearer "+*auth)
		case "basic", "digest":
			user, pass, ok := strings.Cut(*auth, ":")
			if !ok {
				p, err := promptPassword(user)
				if err != nil {
					return 0, err
				}
				pass = p
			}
			if authType == "basic" {
				req.Headers.Append("authorization", basicAuthValue(user, &pass))
			} else {
				digestCreds = &[2]string{user, pass}
			}
		}
	}
	_ = digestCreds

	req.Headers.ReplaceFrom(userHeaders)
	for _, u := range unset {
		req.Headers.Remove(u)
	}

	if c.Compress > 0 && (req.BodyKind == BodyBytes || req.BodyKind == BodyFile) {
		if req.Headers.Contains("content-encoding") {
			warn("--compress can't be used with a 'Content-Encoding:' header. --compress will be disabled.")
		} else {
			var zb bytes.Buffer
			zw := zlib.NewWriter(&zb)
			zw.Write(req.Body)
			zw.Close()
			comp := zb.Bytes()
			if len(comp) < len(req.Body) || c.Compress > 1 {
				req.Body = comp
				req.BodyKind = BodyBytes
				req.Headers.Insert("content-encoding", "deflate")
			}
		}
	}

	if !req.Headers.Contains("accept") {
		req.Headers.Insert("accept", "*/*")
	}

	// output buffer
	buf, err := newOutBuffer(c)
	if err != nil {
		return 0, err
	}
	pretty := ""
	if c.Pretty != nil {
		pretty = *c.Pretty
	} else {
		pretty = guessPretty(buf.isTerminal)
	}
	fo := &formatOptions{}
	for _, f := range c.FormatOptions {
		parseFormatOptions(f, fo)
	}
	printer := &Printer{buf: buf, stream: c.Stream, theme: "ansi", jsonIndent: 4}
	if c.Style != nil && *c.Style != "auto" {
		printer.theme = *c.Style
	}
	if fo.JSONIndent != nil {
		printer.jsonIndent = int(*fo.JSONIndent)
	}
	jsonFormat := fo.JSONFormat == nil || *fo.JSONFormat
	headersSort := fo.HeadersSort == nil || *fo.HeadersSort
	printer.color = pretty == "all" || pretty == "colors"
	isFormat := pretty == "all" || pretty == "format"
	printer.indentJSON = isFormat && jsonFormat
	printer.sortHeaders = isFormat && headersSort

	var pr Print
	if c.Print != nil {
		pr = parsePrint(*c.Print)
	} else {
		pr = newPrint(c, buf.isTerminal)
	}

	if c.Offline {
		if pr.ReqHeaders {
			if err := printer.PrintRequestHeaders(req, ""); err != nil {
				return 0, err
			}
		}
		if pr.ReqBody {
			if err := printer.PrintRequestBody(req); err != nil {
				return 0, err
			}
		}
		buf.Flush()
		return 0, nil
	}
	return execute(c, req, printer, pr, buf, digestCreds)
}

func newOutBuffer(c *Cli) (*OutBuffer, error) {
	if c.Download {
		return &OutBuffer{w: &stderrWriter{}, isTerminal: true, kind: "stderr"}, nil
	}
	if c.Output != nil {
		f, err := os.Create(*c.Output)
		if err != nil {
			return nil, ioErr(err)
		}
		return &OutBuffer{w: f, isTerminal: false, kind: "file", file: f}, nil
	}
	if stdoutIsTerminal() {
		return &OutBuffer{w: stdout, isTerminal: true, kind: "stdout"}, nil
	}
	return &OutBuffer{w: stdout, isTerminal: false, kind: "redirect"}, nil
}

type stderrWriter struct{}

func (s *stderrWriter) Write(p []byte) (int, error) {
	stdout.Flush()
	return os.Stderr.Write(p)
}
