{"command":"cd /workspace; cat > curl.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type curlCmd struct {
	long     bool
	args     []string
	env      [][2]string
	warnings []string
}

func (c *curlCmd) opt(short, long string) {
	if c.long {
		c.args = append(c.args, long)
	} else {
		c.args = append(c.args, short)
	}
}
func (c *curlCmd) arg(a string)       { c.args = append(c.args, a) }
func (c *curlCmd) warn(m string)      { c.warnings = append(c.warnings, m) }
func (c *curlCmd) header(n, v string) { c.opt("-H", "--header"); c.arg(n + ": " + v) }

func (c *curlCmd) String() string {
	var b strings.Builder
	for _, e := range c.env {
		b.WriteString(e[0] + "=" + e[1] + " ")
	}
	b.WriteString("curl")
	for _, a := range c.args {
		b.WriteString(" ")
		b.WriteString(shellQuote(a))
	}
	return b.String()
}

const specialShellStart = "~#!"
const specialShellChars = "|&;<>()$`\\\"'*?[]=^{} \t\n"
const doubleUnsafe = "\"`$\\"

func requiresEscape(r rune) bool {
	return unicode.IsControl(r) || unicode.Is(unicode.Zl, r) || unicode.Is(unicode.Zp, r) || (unicode.Is(unicode.Cf, r) && !isBidi(r)) || r == utf8.RuneError
}

func isBidi(r rune) bool {
	switch r {
	case 0x202A, 0x202B, 0x202C, 0x202D, 0x202E, 0x2066, 0x2067, 0x2068, 0x2069:
		return true
	}
	return false
}

func shellQuote(text string) string {
	singleSafe := true
	doubleSafe := true
	requiresQuote := false
	if text == "" {
		requiresQuote = true
	} else {
		first, _ := utf8.DecodeRuneInString(text)
		if strings.ContainsRune(specialShellStart, first) {
			requiresQuote = true
		}
	}
	isBidiText := false
	for _, ch := range text {
		if ch < 128 {
			c := byte(ch)
			if c == '\'' {
				singleSafe = false
			}
			if doubleSafe && strings.IndexByte(doubleUnsafe, c) >= 0 {
				doubleSafe = false
			}
			if !requiresQuote && strings.IndexByte(specialShellChars, c) >= 0 {
				requiresQuote = true
			}
			if c < 0x20 || c == 0x7f {
				return writeEscaped(text)
			}
		} else {
			if !requiresQuote && (unicode.IsSpace(ch) || ch == 0x2800) {
				requiresQuote = true
			}
			if isBidi(ch) {
				isBidiText = true
			}
			if requiresEscape(ch) {
				return writeEscaped(text)
			}
		}
	}
	_ = isBidiText
	if !requiresQuote {
		return text
	}
	if singleSafe {
		return "'" + text + "'"
	}
	if doubleSafe {
		return "\"" + text + "\""
	}
	parts := strings.Split(text, "'")
	var b strings.Builder
	if parts[0] != "" {
		b.WriteString("'" + parts[0] + "'")
	}
	for _, p := range parts[1:] {
		b.WriteString("\\'")
		if p != "" {
			b.WriteString("'" + p + "'")
		}
	}
	return b.String()
}

func writeEscaped(text string) string {
	var b strings.Builder
	b.WriteString("$'")
	inEscape := false
	for i := 0; i < len(text); {
		r, sz := utf8.DecodeRuneInString(text[i:])
		if r == utf8.RuneError && sz == 1 {
			fmt.Fprintf(&b, "\\x%02X", text[i])
			inEscape = true
			i++
			continue
		}
		wasEscape := inEscape
		inEscape = false
		switch {
		case r == '\n':
			b.WriteString("\\n")
		case r == '\t':
			b.WriteString("\\t")
		case r == '\r':
			b.WriteString("\\r")
		case requiresEscape(r) || isBidi(r):
			for _, by := range []byte(string(r)) {
				fmt.Fprintf(&b, "\\x%02X", by)
			}
			inEscape = true
		case r == '\\' || r == '\'':
			b.WriteByte('\\')
			b.WriteRune(r)
		case wasEscape && r < 128 && isHex(byte(r)):
			b.WriteString("'$'")
			b.WriteRune(r)
		default:
			b.WriteRune(r)
		}
		i += sz
	}
	b.WriteString("'")
	return b.String()
}

func rustF64Display(f float64) string {
	return strconv.FormatFloat(f, 'f', -1, 64)
}

func printCurl(c *Cli) error {
	cmd := &curlCmd{long: c.CurlLong}
	ignored := []struct {
		present bool
		flag    string
	}{
		{c.Offline, "--offline"},
		{c.Body, "-b/--body"},
		{c.Print != nil, "-p/--print"},
		{c.Pretty != nil, "--pretty"},
		{c.Style != nil, "-s/--style"},
		{c.Compress > 0, "-x/--compress"},
		{c.ResponseCharset != nil, "--response-charset"},
		{c.ResponseMime != nil, "--response-mime"},
		{c.All, "--all"},
		{c.HistoryPrint != nil, "-P/--history-print"},
		{c.Session != nil || c.SessionReadOnly != nil, "--session"},
		{c.NativeTLS, "--native-tls"},
	}
	for _, ig := range ignored {
		if ig.present {
			cmd.warn("Ignored " + ig.flag)
		}
	}

	headers, unset, err := headersFromItems(c.Items)
	if err != nil {
		return err
	}

	// Determine method
	spec, err := bodyFromItems(c.Items, c.RequestType)
	if err != nil {
		return err
	}
	hasBody := !spec.isEmpty() || c.Raw != nil
	method := c.Method
	explicitMethod := method != ""
	if method == "" {
		if hasBody {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	if c.Verbose > 0 {
		cmd.opt("-v", "--verbose")
	}
	if c.Quiet > 0 {
		cmd.opt("-s", "--silent")
	}
	if c.Debug {
		cmd.arg("--trace")
		cmd.arg("-")
	}
	if c.Stream {
		cmd.opt("-N", "--no-buffer")
	}
	if (c.CheckStatus != nil && *c.CheckStatus) || c.Download {
		cmd.opt("-f", "--fail")
	}
	if c.Follow {
		cmd.opt("-L", "--location")
	}
	if c.MaxRedirects != nil {
		cmd.arg("--max-redirs")
		cmd.arg(strconv.FormatUint(*c.MaxRedirects, 10))
	}
	if c.Output != nil {
		cmd.opt("-o", "--output")
		cmd.arg(*c.Output)
	} else if c.Download {
		cmd.opt("-O", "--remote-name")
	}
	if c.Resume {
		cmd.opt("-C", "--continue-at")
		cmd.arg("-")
	}
	if c.Verify != nil {
		switch strings.ToLower(*c.Verify) {
		case "no", "false":
			cmd.opt("-k", "--insecure")
		case "yes", "true":
		default:
			cmd.arg("--cacert")
			cmd.arg(*c.Verify)
		}
	}
	if c.Cert != nil {
		cmd.opt("-E", "--cert")
		cmd.arg(*c.Cert)
	}
	if c.CertKey != nil {
		cmd.arg("--key")
		cmd.arg(*c.CertKey)
	}
	if c.SSL != nil {
		v := ""
		switch *c.SSL {
		case "tls1":
			v = "1.0"
		case "tls1.1":
			v = "1.1"
		case "tls1.2":
			v = "1.2"
		case "tls1.3":
			v = "1.3"
		}
		if v != "" {
			cmd.arg("--tlsv" + v)
			cmd.arg("--tls-max")
			cmd.arg(v)
		}
	}
	for _, p := range c.Proxy {
		switch p.Protocol {
		case "http":
			cmd.env = append(cmd.env, [2]string{"http_proxy", p.URL.String()})
		case "https":
			cmd.env = append(cmd.env, [2]string{"https_proxy", p.URL.String()})
		case "all":
			cmd.opt("-x", "--proxy")
			cmd.arg(p.URL.String())
		}
	}
	if c.Timeout != nil && *c.Timeout > 0 {
		d := durationSecs(*c.Timeout)
		if d > 0 {
			cmd.arg("--max-time")
			cmd.arg(rustF64Display(d))
		}
	}
	if c.HTTPVersion != nil {
		switch *c.HTTPVersion {
		case "1.0":
			cmd.arg("--http1.0")
		case "1.1":
			cmd.arg("--http1.1")
		case "2":
			cmd.arg("--http2")
		case "2-prior-knowledge":
			cmd.arg("--http2-prior-knowledge")
		case "3-prior-knowledge":
			cmd.arg("--http3-only")
		}
	}
	usedX := false
	if method == "HEAD" {
		cmd.opt("-I", "--head")
	} else if method == "OPTIONS" {
		cmd.opt("-i", "--include")
		cmd.opt("-X", "--request")
		cmd.arg(method)
		usedX = true
	} else {
		if c.Headers {
			cmd.opt("-I", "--head")
		}
		if explicitMethod || c.Headers {
			cmd.opt("-X", "--request")
			cmd.arg(method)
			usedX = true
		}
	}
	if usedX && c.Follow {
		cmd.warn("Using a combination of -X/--request and -L/--location which may cause unintended side effects.")
	}
	if c.Headers && method != "GET" && method != "HEAD" && method != "OPTIONS" {
		cmd.warn("-I/--head is incompatible with sending data. Consider omitting -h/--headers.")
	}

	cmd.arg(c.URL.String())

	if c.IPv4 {
		cmd.opt("-4", "--ipv4")
	}
	if c.IPv6 {
		cmd.opt("-6", "--ipv6")
	}
	if c.Interface != nil {
		cmd.arg("--interface")
		cmd.arg(*c.Interface)
	}
	if c.UnixSocket != nil {
		cmd.arg("--unix-socket")
		cmd.arg(*c.UnixSocket)
	}
	if len(c.Resolve) > 0 {
		port := c.URL.PortOrDefault()
		for _, r := range c.Resolve {
			cmd.arg("--resolve")
			cmd.arg(r.Host + ":" + itoa(port) + ":" + r.IP.String())
		}
		cmd.warn("Inferred port number in --resolve from request URL.")
	}

	for _, kv := range headers.Pairs() {
		cmd.opt("-H", "--header")
		if kv[1] == "" {
			cmd.arg(kv[0] + ";")
		} else {
			cmd.arg(kv[0] + ": " + kv[1])
		}
	}
	for _, u := range unset {
		cmd.opt("-H", "--header")
		cmd.arg(u + ":")
	}
	if c.IgnoreNetrc {
		cmd.arg("--no-netrc")
	}

	// auth
	authType := "basic"
	if c.AuthType != nil {
		authType = *c.AuthType
	}
	auth := c.Auth
	if c.Bearer != nil {
		authType = "bearer"
		auth = c.Bearer
	}
	if auth != nil {
		switch authType {
		case "basic":
			cmd.arg("--basic")
			cmd.opt("-u", "--user")
			cmd.arg(*auth)
		case "digest":
			cmd.arg("--digest")
			cmd.opt("-u", "--user")
			cmd.arg(*auth)
		case "bearer":
			cmd.arg("--oauth2-bearer")
			cmd.arg(*auth)
		}
	}

	// body
	if c.Raw != nil {
		if c.RequestType == "json" {
			cmd.header("content-type", jsonContentType)
			cmd.header("accept", jsonAccept)
		} else {
			cmd.header("content-type", formContentType)
		}
		cmd.opt("-d", "--data")
		cmd.arg(*c.Raw)
	} else {
		switch spec.kind {
		case "json":
			cmd.header("content-type", jsonContentType)
			cmd.header("accept", jsonAccept)
			cmd.opt("-d", "--data")
			cmd.arg(CompactJSON(spec.json))
		case "file":
			ct := ""
			if spec.fileType != nil {
				ct = *spec.fileType
			} else if g := guessMime(spec.filePath); g != "" {
				ct = g
			} else {
				ct = jsonContentType
			}
			cmd.header("content-type", ct)
			cmd.arg("--data-binary")
			cmd.arg("@" + spec.filePath)
