package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type curlCmd struct {
	long     bool
	args     []string
	env      [][2]string
	warnings []string
}

func (c *curlCmd) opt(short, long string) {
	if c.long {
		c.args = append(c.args, long)
	} else {
		c.args = append(c.args, short)
	}
}
func (c *curlCmd) arg(a string)       { c.args = append(c.args, a) }
func (c *curlCmd) warn(m string)      { c.warnings = append(c.warnings, m) }
func (c *curlCmd) header(n, v string) { c.opt("-H", "--header"); c.arg(n + ": " + v) }

func (c *curlCmd) String() string {
	var b strings.Builder
	for _, e := range c.env {
		b.WriteString(e[0] + "=" + e[1] + " ")
	}
	b.WriteString("curl")
	for _, a := range c.args {
		b.WriteString(" ")
		b.WriteString(shellQuote(a))
	}
	return b.String()
}

const specialShellStart = "~#!"
const specialShellChars = "|&;<>()$`\\\"'*?[]=^{} \t\n"
const doubleUnsafe = "\"`$\\"

func requiresEscape(r rune) bool {
	return unicode.IsControl(r) || unicode.Is(unicode.Zl, r) || unicode.Is(unicode.Zp, r) || (unicode.Is(unicode.Cf, r) && !isBidi(r)) || r == utf8.RuneError
}

func isBidi(r rune) bool {
	switch r {
	case 0x202A, 0x202B, 0x202C, 0x202D, 0x202E, 0x2066, 0x2067, 0x2068, 0x2069:
		return true
	}
	return false
}

func shellQuote(text string) string {
	singleSafe := true
	doubleSafe := true
	requiresQuote := false
	if text == "" {
		requiresQuote = true
	} else {
		first, _ := utf8.DecodeRuneInString(text)
		if strings.ContainsRune(specialShellStart, first) {
			requiresQuote = true
		}
	}
	isBidiText := false
	for _, ch := range text {
		if ch < 128 {
			c := byte(ch)
			if c == '\'' {
				singleSafe = false
			}
			if doubleSafe && strings.IndexByte(doubleUnsafe, c) >= 0 {
				doubleSafe = false
			}
			if !requiresQuote && strings.IndexByte(specialShellChars, c) >= 0 {
				requiresQuote = true
			}
			if c < 0x20 || c == 0x7f {
				return writeEscaped(text)
			}
		} else {
			if !requiresQuote && (unicode.IsSpace(ch) || ch == 0x2800) {
				requiresQuote = true
			}
			if isBidi(ch) {
				isBidiText = true
			}
			if requiresEscape(ch) {
				return writeEscaped(text)
			}
		}
	}
	_ = isBidiText
	if !requiresQuote {
		return text
	}
	if singleSafe {
		return "'" + text + "'"
	}
	if doubleSafe {
		return "\"" + text + "\""
	}
	parts := strings.Split(text, "'")
	var b strings.Builder
	if parts[0] != "" {
		b.WriteString("'" + parts[0] + "'")
	}
	for _, p := range parts[1:] {
		b.WriteString("\\'")
		if p != "" {
			b.WriteString("'" + p + "'")
		}
	}
	return b.String()
}

func writeEscaped(text string) string {
	var b strings.Builder
	b.WriteString("$'")
	inEscape := false
	for i := 0; i < len(text); {
		r, sz := utf8.DecodeRuneInString(text[i:])
		if r == utf8.RuneError && sz == 1 {
			fmt.Fprintf(&b, "\\x%02X", text[i])
			inEscape = true
			i++
			continue
		}
		wasEscape := inEscape
		inEscape = false
		switch {
		case r == '\n':
			b.WriteString("\\n")
		case r == '\t':
			b.WriteString("\\t")
		case r == '\r':
			b.WriteString("\\r")
		case requiresEscape(r) || isBidi(r):
			for _, by := range []byte(string(r)) {
				fmt.Fprintf(&b, "\\x%02X", by)
			}
			inEscape = true
		case r == '\\' || r == '\'':
			b.WriteByte('\\')
			b.WriteRune(r)
		case wasEscape && r < 128 && isHex(byte(r)):
			b.WriteString("'$'")
			b.WriteRune(r)
		default:
			b.WriteRune(r)
		}
		i += sz
	}
	b.WriteString("'")
	return b.String()
}

