	if c.HTTPVersion != nil {
		switch *c.HTTPVersion {
		case "1.0":
			cmd.arg("--http1.0")
		case "1.1":
			cmd.arg("--http1.1")
		case "2":
			cmd.arg("--http2")
		case "2-prior-knowledge":
			cmd.arg("--http2-prior-knowledge")
		case "3-prior-knowledge":
			cmd.arg("--http3-only")
		}
	}
