		} else {
			cmd.arg(kv[0] + ": " + kv[1])
		}
	}
	for _, u := range unset {
		cmd.opt("-H", "--header")
		cmd.arg(u + ":")
	}
	if c.IgnoreNetrc {
		cmd.arg("--no-netrc")
	}

	// auth
	authType := "basic"
	if c.AuthType != nil {
		authType = *c.AuthType
	}
	auth := c.Auth
	if c.Bearer != nil {
		authType = "bearer"
		auth = c.Bearer
	}
	if auth != nil {
