			pool := x509.NewCertPool()
			pool.AppendCertsFromPEM(data)
			tc.RootCAs = pool
		}
	} else if ca := caBundleEnv(); ca != "" {
		data, err := os.ReadFile(ca)
		if err == nil {
			pool := x509.NewCertPool()
			pool.AppendCertsFromPEM(data)
			tc.RootCAs = pool
		}
	}
	if c.SSL != nil {
		switch *c.SSL {
		case "tls1.2":
			tc.MinVersion, tc.MaxVersion = tls.VersionTLS12, tls.VersionTLS12
		case "tls1.3":
			tc.MinVersion, tc.MaxVersion = tls.VersionTLS13, tls.VersionTLS13
		}
	}
	if c.Cert != nil {
		certData, err := os.ReadFile(*c.Cert)
		if err != nil {
			return nil, &chainError{msg: "Failed to open the cert file: " + *c.Cert}
		}
		keyData := certData
		if c.CertKey != nil {
			kd, err := os.ReadFile(*c.CertKey)
			if err != nil {
				return nil, &chainError{msg: "Failed to open the cert key file: " + *c.CertKey}
			}
			keyData = kd
		}
		cert, err := tls.X509KeyPair(certData, keyData)
		if err != nil {
			return nil, &chainError{msg: "builder error", causes: []string{"Failed to parse cert: " + err.Error()}}
		}
		tc.Certificates = []tls.Certificate{cert}
	}
	hc.tlsConf = tc
	return hc, nil
}

func caBundleEnv() string {
	if v := os.Getenv("REQUESTS_CA_BUNDLE"); v != "" {
		return v
	}
	return os.Getenv("CURL_CA_BUNDLE")
}

func sendErr(u *URL, causes ...string) error {
	return &chainError{msg: "error sending request for url (" + u.String() + ")", causes: causes}
}

func timeoutErr(u *URL) error {
	return &chainError{msg: "error sending request for url (" + u.String() + ")", causes: []string{"operation timed out"}, timeout: true}
}

func isTimeout(err error) bool {
	var ne net.Error
	if errors.As(err, &ne) && ne.Timeout() {
		return true
	}
	return errors.Is(err, context.DeadlineExceeded) || errors.Is(err, os.ErrDeadlineExceeded)
}

func osErrString(err error) string {
	var en syscall.Errno
	if errors.As(err, &en) {
		return errnoString(en) + " (os error " + itoa(int(en)) + ")"
	}
	return err.Error()
}

// proxyFor returns the proxy URL to use for a request URL (or nil).
func (hc *httpClient) proxyFor(u *URL) *URL {
	if !hc.useEnvPrx {
		var all *URL
		for _, p := range hc.proxies {
			if p.Protocol == u.Scheme {
				return p.URL
			}
			if p.Protocol == "all" {
				all = p.URL
			}
		}
		return all
	}
	if noProxyMatch(u.Host) {
		return nil
	}
	var v string
	if u.Scheme == "https" {
		v = envAny("HTTPS_PROXY", "https_proxy")
	} else {
		v = envAny("http_proxy")
	}
	if v == "" {
		v = envAny("ALL_PROXY", "all_proxy")
	}
	if v == "" {
		return nil
	}
	if !strings.Contains(v, "://") {
		v = "http://" + v
	}
	pu, err := ParseURL(v)
	if err != nil {
		return nil
	}
	return pu
}

func envAny(names ...string) string {
	for _, n := range names {
		if v := os.Getenv(n); v != "" {
			return v
		}
	}
	return ""
}

func noProxyMatch(host string) bool {
	np := envAny("NO_PROXY", "no_proxy")
	if np == "" {
		return false
	}
	h := strings.Trim(host, "[]")
	for _, e := range strings.Split(np, ",") {
		e = strings.TrimSpace(e)
		if e == "" {
			continue
		}
		if e == "*" {
			return true
		}
		e = strings.TrimPrefix(e, ".")
		if h == e || strings.HasSuffix(h, "."+e) {
			return true
		}
		if _, n, err := net.ParseCIDR(e); err == nil {
			if ip := net.ParseIP(h); ip != nil && n.Contains(ip) {
				return true
			}
		}
	}
	return false
}

func (hc *httpClient) dialContext() (context.Context, context.CancelFunc) {
	if !hc.deadline.IsZero() {
		return context.WithDeadline(context.Background(), hc.deadline)
	}
	return context.Background(), func() {}
}

func (hc *httpClient) dialTCP(u *URL, host string, port int) (net.Conn, error) {
	c := hc.cli
	ctx, cancel := hc.dialContext()
	defer cancel()
	d := &net.Dialer{}
	if c.Interface != nil {
		if ip := net.ParseIP(*c.Interface); ip != nil {
			d.LocalAddr = &net.TCPAddr{IP: ip}
		} else {
			iface := *c.Interface
			d.Control = func(network, address string, rc syscall.RawConn) error {
				var serr error
				rc.Control(func(fd uintptr) {
					serr = syscall.SetsockoptString(int(fd), syscall.SOL_SOCKET, syscall.SO_BINDTODEVICE, iface)
				})
				return serr
			}
		}
	}
	h := strings.Trim(host, "[]")
	var ips []net.IP
	if ip, ok := hc.resolve[strings.ToLower(h)]; ok {
		ips = []net.IP{ip}
	} else if ip := net.ParseIP(h); ip != nil {
		ips = []net.IP{ip}
	} else {
		addrs, err := net.DefaultResolver.LookupIPAddr(ctx, h)
		if err != nil {
			if isTimeout(err) {
				return nil, timeoutErr(u)
			}
			msg := "failed to lookup address information: Name or service not known"
			var de *net.DNSError
			if errors.As(err, &de) && (de.IsTemporary || de.IsTimeout || strings.Contains(de.Err, "server misbehaving") || strings.Contains(de.Err, "no such host") && !de.IsNotFound) {
				msg = "failed to lookup address information: Temporary failure in name resolution"
			}
			if errors.As(err, &de) && !de.IsNotFound {
				msg = "failed to lookup address information: Temporary failure in name resolution"
			}
			return nil, sendErr(u, "client error (Connect)", "dns error", msg)
		}
		for _, a := range addrs {
			ips = append(ips, a.IP)
		}
	}
	var filtered []net.IP
	for _, ip := range ips {
		if c.IPv4 && ip.To4() == nil {
			continue
		}
		if c.IPv6 && ip.To4() != nil {
			continue
		}
		filtered = append(filtered, ip)
	}
	if len(filtered) == 0 {
		return nil, sendErr(u, "client error (Connect)", "dns error", "failed to lookup address information: Name or service not known")
	}
	var lastErr error
	for _, ip := range filtered {
		conn, err := d.DialContext(ctx, "tcp", net.JoinHostPort(ip.String(), strconv.Itoa(port)))
		if err == nil {
			return conn, nil
		}
		lastErr = err
		if isTimeout(err) {
			return nil, timeoutErr(u)
		}
	}
	return nil, sendErr(u, "client error (Connect)", "tcp connect error", osErrString(lastErr))
}

func (hc *httpClient) connect(u *URL) (*pconn, bool, error) {
	c := hc.cli
	proxy := hc.proxyFor(u)
	key := u.Scheme + "://" + u.Host + ":" + itoa(u.PortOrDefault())
	if proxy != nil {
		key += "|" + proxy.String()
	}
	if pc, ok := hc.pool[key]; ok && !pc.broken {
		return pc, proxy != nil && u.Scheme == "http", nil
	}
	var conn net.Conn
	var err error
	viaHTTPProxy := false
	if c.UnixSocket != nil {
		ctx, cancel := hc.dialContext()
		defer cancel()
		var d net.Dialer
		conn, err = d.DialContext(ctx, "unix", *c.UnixSocket)
		if err != nil {
			if isTimeout(err) {
				return nil, false, timeoutErr(u)
			}
			return nil, false, sendErr(u, "client error (Connect)", osErrString(err))
		}
	} else if proxy != nil {
		pport := proxy.PortOrDefault()
		if pport < 0 {
			pport = 1080
		}
		switch proxy.Scheme {
		case "socks5", "socks5h", "socks4", "socks4a":
			conn, err = hc.dialTCP(u, proxy.Host, pport)
			if err != nil {
				return nil, false, err
			}
			if err := socks5Handshake(conn, proxy, u.Host, u.PortOrDefault(), proxy.Scheme == "socks5h"); err != nil {
				conn.Close()
				return nil, false, sendErr(u, "client error (Connect)", err.Error())
			}
		default:
			conn, err = hc.dialTCP(u, proxy.Host, pport)
			if err != nil {
				return nil, false, err
			}
			if proxy.Scheme == "https" {
				tconn := tls.Client(conn, &tls.Config{ServerName: strings.Trim(proxy.Host, "[]"), InsecureSkipVerify: hc.tlsConf.InsecureSkipVerify, RootCAs: hc.tlsConf.RootCAs})
				if err := tconn.Handshake(); err != nil {
					return nil, false, sendErr(u, "client error (Connect)", err.Error())
				}
				conn = tconn
			}
			if u.Scheme == "https" {
				// CONNECT tunnel
				target := u.Host + ":" + itoa(u.PortOrDefault())
				var b strings.Builder
				b.WriteString("CONNECT " + target + " HTTP/1.1\r\nHost: " + target + "\r\n")
				if proxy.Username != "" || proxy.Password != "" {
					up := string(pctDecode(proxy.Username)) + ":" + string(pctDecode(proxy.Password))
					b.WriteString("Proxy-Authorization: Basic " + base64.StdEncoding.EncodeToString([]byte(up)) + "\r\n")
				}
				b.WriteString("\r\n")
				conn.Write([]byte(b.String()))
				br := bufio.NewReader(conn)
				line, err := br.ReadString('\n')
				if err != nil {
					return nil, false, sendErr(u, "client error (Connect)", "unsuccessful tunnel")
				}
				parts := strings.SplitN(strings.TrimRight(line, "\r\n"), " ", 3)
				for {
					l, err := br.ReadString('\n')
					if err != nil || l == "\r\n" || l == "\n" {
						break
					}
				}
				if len(parts) < 2 || parts[1] != "200" {
					return nil, false, sendErr(u, "client error (Connect)", "unsuccessful tunnel")
				}
			} else {
				viaHTTPProxy = true
			}
		}
	} else {
		conn, err = hc.dialTCP(u, u.Host, u.PortOrDefault())
		if err != nil {
			return nil, false, err
		}
	}
	remote := ""
	if conn.RemoteAddr() != nil && c.UnixSocket == nil {
		remote = conn.RemoteAddr().String()
	}
	if u.Scheme == "https" {
		conf := hc.tlsConf.Clone()
		sn := strings.Trim(u.Host, "[]")
		if net.ParseIP(sn) == nil {
			conf.ServerName = sn
		} else {
			conf.ServerName = sn
		}
		if !hc.deadline.IsZero() {
			conn.SetDeadline(hc.deadline)
		}
		tconn := tls.Client(conn, conf)
		if err := tconn.Handshake(); err != nil {
			conn.Close()
			if isTimeout(err) {
				return nil, false, timeoutErr(u)
			}
			return nil, false, sendErr(u, "client error (Connect)", tlsErrString(err))
		}
		conn = tconn
	}
	pc := &pconn{c: conn, br: bufio.NewReaderSize(conn, 32*1024), remote: remote, key: key}
	hc.pool[key] = pc
	return pc, viaHTTPProxy, nil
}

func tlsErrString(err error) string {
	var ue x509.UnknownAuthorityError
	if errors.As(err, &ue) {
		return "invalid peer certificate: UnknownIssuer"
	}
	var he x509.HostnameError
	if errors.As(err, &he) {
		return "invalid peer certificate: NotValidForName"
	}
	var ce x509.CertificateInvalidError
	if errors.As(err, &ce) {
		if ce.Reason == x509.Expired {
			return "invalid peer certificate: Expired"
		}
		return "invalid peer certificate: BadEncoding"
	}
	var re tls.RecordHeaderError
	if errors.As(err, &re) {
		return "received corrupt message of type InvalidContentType"
	}
	if strings.Contains(err.Error(), "EOF") {
		return "tls handshake eof"
	}
	return err.Error()
}

// wireHeaders builds the header list sent on the wire.
func wireHeaders(req *Request) *HeaderMap {
	h := req.Headers.Clone()
	if req.BodyKind != BodyNone {
		h.Insert("content-length", itoa(len(req.Body)))
	} else if req.Method == "POST" || req.Method == "PUT" || req.Method == "PATCH" {
		// hyper does not add content-length for empty bodies
	}
	if !h.Contains("accept") {
		h.Insert("accept", "*/*")
	}
	if !h.Contains("host") {
		hv := req.URL.Host
		if req.URL.Port >= 0 {
			hv += ":" + itoa(req.URL.Port)
		}
		h.Insert("host", hv)
	}
	return h
}

func (hc *httpClient) roundTrip(req *Request) (*Response, error) {
	u := req.URL
	if u.Scheme != "http" && u.Scheme != "https" {
		return nil, &chainError{msg: "builder error for url (" + u.String() + ")", causes: []string{"URL scheme is not allowed"}}
	}
	for attempt := 0; attempt < 2; attempt++ {
		pc, viaProxy, err := hc.connect(u)
		if err != nil {
			return nil, err
		}
		reused := attempt == 0 && pc.br.Buffered() >= 0 && pc.c != nil && hc.isReused(pc)
		resp, err := hc.exchange(pc, req, viaProxy)
		if err != nil {
			pc.broken = true
			pc.c.Close()
			delete(hc.pool, pc.key)
			if reused && isConnReset(err) {
				continue
			}
			return nil, err
		}
		return resp, nil
	}
	return nil, sendErr(u, "client error (SendRequest)", "connection closed before message completed")
}

func (hc *httpClient) isReused(pc *pconn) bool {
	return pc.remote != "" && false
}

type sendError struct{ cause string }

func (e *sendError) Error() string { return e.cause }

func isConnReset(err error) bool {
	var ce *chainError
	if errors.As(err, &ce) && len(ce.causes) > 0 && strings.Contains(ce.causes[len(ce.causes)-1], "connection closed before message completed") {
		return true
	}
	return false
}

func (hc *httpClient) exchange(pc *pconn, req *Request, viaProxy bool) (*Response, error) {
	u := req.URL
	if !hc.deadline.IsZero() {
		pc.c.SetDeadline(hc.deadline)
	}
	var b strings.Builder
	target := u.PathString()
	if u.HasQuery {
		target += "?" + u.Query
	}
	if target == "" {
		target = "/"
	}
	if viaProxy {
		uu := u.Clone()
		uu.HasFragment = false
		target = uu.String()
	}
	ver := "HTTP/1.1"
	if req.Version == "HTTP/1.0" {
		ver = "HTTP/1.0"
	}
	b.WriteString(req.Method + " " + target + " " + ver + "\r\n")
	h := wireHeaders(req)
	if viaProxy {
		if p := hc.proxyFor(u); p != nil && (p.Username != "" || p.Password != "") && !h.Contains("proxy-authorization") {
			up := string(pctDecode(p.Username)) + ":" + string(pctDecode(p.Password))
			h.Insert("proxy-authorization", "Basic "+base64.StdEncoding.EncodeToString([]byte(up)))
		}
	}
	for _, kv := range h.Pairs() {
		b.WriteString(titleCase(kv[0]) + ": " + kv[1] + "\r\n")
	}
	b.WriteString("\r\n")
	start := time.Now()
	data := []byte(b.String())
	if req.BodyKind != BodyNone {
		data = append(data, req.Body...)
	}
	if _, err := pc.c.Write(data); err != nil {
		if isTimeout(err) {
			return nil, timeoutErr(u)
		}
		return nil, sendErr(u, "client error (SendRequest)", "connection error: "+osErrString(err))
	}
	resp, err := readResponseHead(pc.br, u, req.Method)
	if err != nil {
		return nil, err
	}
	resp.Elapsed = time.Since(start)
	resp.RemoteAddr = pc.remote
	resp.conn = pc
	resp.URL = u
	return resp, nil
}

func readLine(br *bufio.Reader) (string, error) {
	line, err := br.ReadString('\n')
	if err != nil {
		return line, err
	}
	return strings.TrimRight(line, "\r\n"), nil
}

func readResponseHead(br *bufio.Reader, u *URL, method string) (*Response, error) {
	for {
		line, err := br.ReadString('\n')
		if err != nil {
			if isTimeout(err) {
				return nil, timeoutErr(u)
			}
			if line == "" {
				return nil, sendErr(u, "client error (SendRequest)", "connection closed before message completed")
			}
			return nil, sendErr(u, "client error (SendRequest)", "invalid HTTP version parsed")
		}
		line = strings.TrimRight(line, "\r\n")
		if !strings.HasPrefix(line, "HTTP/1.") || len(line) < 12 || (line[7] != '0' && line[7] != '1') || line[8] != ' ' {
			return nil, sendErr(u, "client error (SendRequest)", "invalid HTTP version parsed")
		}
		ver := line[:8]
		rest := line[9:]
		code := rest
		reason := ""
		if i := strings.IndexByte(rest, ' '); i >= 0 {
			code = rest[:i]
			reason = rest[i+1:]
		}
		if len(code) != 3 {
			return nil, sendErr(u, "client error (SendRequest)", "invalid HTTP status-code parsed")
		}
		status, err := strconv.Atoi(code)
		if err != nil || status < 100 {
			return nil, sendErr(u, "client error (SendRequest)", "invalid HTTP status-code parsed")
		}
		h := &HeaderMap{}
		for {
			hl, err := br.ReadString('\n')
			if err != nil {
				if isTimeout(err) {
					return nil, timeoutErr(u)
				}
				return nil, sendErr(u, "client error (SendRequest)", "connection closed before message completed")
			}
			hl = strings.TrimRight(hl, "\r\n")
			if hl == "" {
				break
			}
			name, val, ok := strings.Cut(hl, ":")
			if !ok || name == "" || validHeaderName(name) != nil {
				return nil, sendErr(u, "client error (SendRequest)", "invalid HTTP header parsed")
			}
			h.Append(strings.ToLower(name), strings.Trim(val, " \t"))
		}
		if status >= 100 && status < 200 && status != 101 {
			continue
		}
		resp := &Response{Version: ver, Status: status, Reason: reason, Headers: h, isHead: method == "HEAD"}
		if ver == "HTTP/1.0" {
			resp.Version = "HTTP/1.0"
		}
		resp.bodyReader = bodyReader(br, resp)
		return resp, nil
	}
}

type bodyErr struct{ cause string }

func (e *bodyErr) Error() string { return e.cause }

func bodyReader(br *bufio.Reader, resp *Response) io.Reader {
	if resp.isHead || resp.Status == 204 || resp.Status == 304 || (resp.Status >= 100 && resp.Status < 200) {
		return strings.NewReader("")
	}
	if te, ok := resp.Headers.Get("transfer-encoding"); ok && strings.Contains(strings.ToLower(te), "chunked") {
		return &chunkedReader{br: br}
	}
	if cl, ok := resp.Headers.Get("content-length"); ok {
		n, err := strconv.ParseInt(strings.TrimSpace(cl), 10, 64)
		if err == nil {
			return &lengthReader{r: br, n: n}
		}
	}
	return br
}

type lengthReader struct {
	r io.Reader
	n int64
}

func (l *lengthReader) Read(p []byte) (int, error) {
	if l.n <= 0 {
		return 0, io.EOF
	}
	if int64(len(p)) > l.n {
		p = p[:l.n]
	}
	n, err := l.r.Read(p)
	l.n -= int64(n)
	if err == io.EOF && l.n > 0 {
		return n, &bodyErr{"end of file before message length reached"}
	}
	if err != nil && err != io.EOF {
		return n, err
	}
	return n, nil
}

type chunkedReader struct {
	br   *bufio.Reader
	left int64
	done bool
}

func (c *chunkedReader) Read(p []byte) (int, error) {
	if c.done {
		return 0, io.EOF
	}
	if c.left == 0 {
		line, err := c.br.ReadString('\n')
		if err != nil {
			if isTimeout(err) {
				return 0, err
			}
			return 0, &bodyErr{"end of file before message length reached"}
		}
		line = strings.TrimRight(line, "\r\n")
		if i := strings.IndexByte(line, ';'); i >= 0 {
			line = line[:i]
		}
		line = strings.TrimSpace(line)
		if line == "" || !isHexString(line) {
			return 0, &bodyErr{"Invalid chunk size line: missing size digit"}
		}
		n, err := strconv.ParseInt(line, 16, 64)
		if err != nil {
			return 0, &bodyErr{"Invalid chunk size line: missing size digit"}
		}
		if n == 0 {
			// trailers
			for {
				l, err := c.br.ReadString('\n')
				if err != nil || l == "\r\n" || l == "\n" {
					break
				}
			}
			c.done = true
			return 0, io.EOF
		}
		c.left = n
	}
	if int64(len(p)) > c.left {
		p = p[:c.left]
	}
	n, err := c.br.Read(p)
	c.left -= int64(n)
	if err != nil {
		if err == io.EOF {
			return n, &bodyErr{"end of file before message length reached"}
		}
		return n, err
	}
	if c.left == 0 {
		c.br.ReadString('\n')
	}
	return n, nil
}

func isHexString(s string) bool {
	for i := 0; i < len(s); i++ {
		if !isHex(s[i]) {
			return false
		}
	}
	return true
}

func wrapBodyErr(err error) error {
	if err == nil {
		return nil
	}
	if isTimeout(err) {
		return &chainError{msg: "request or response body error", causes: []string{"operation timed out"}, timeout: true}
	}
	var be *bodyErr
	if errors.As(err, &be) {
		return &chainError{msg: "request or response body error", causes: []string{"error reading a body from connection", be.cause}}
	}
	var ce *chainError
	if errors.As(err, &ce) {
		return err
	}
	return &chainError{msg: "request or response body error", causes: []string{"error reading a body from connection", osErrString(err)}}
}

func socks5Handshake(conn net.Conn, proxy *URL, host string, port int, remoteDNS bool) error {
	user := string(pctDecode(proxy.Username))
	pass := string(pctDecode(proxy.Password))
	methods := []byte{0x00}
	if user != "" || pass != "" {
		methods = []byte{0x02}
	}
	conn.Write(append([]byte{5, byte(len(methods))}, methods...))
	resp := make([]byte, 2)
	if _, err := io.ReadFull(conn, resp); err != nil {
		return err
	}
	if resp[1] == 0x02 {
		msg := []byte{1, byte(len(user))}
		msg = append(msg, user...)
		msg = append(msg, byte(len(pass)))
		msg = append(msg, pass...)
		conn.Write(msg)
		if _, err := io.ReadFull(conn, resp); err != nil {
			return err
		}
		if resp[1] != 0 {
			return errors.New("socks5 authentication failed")
