	switch hdr[3] {
	case 1:
		skip = 4
	case 4:
		skip = 16
	case 3:
		l := make([]byte, 1)
		io.ReadFull(conn, l)
		skip = int(l[0])
	}
	io.ReadFull(conn, make([]byte, skip+2))
	return nil
}
