	}
	return ""
}

// readBody reads the raw body fully.
func readBody(resp *Response) ([]byte, error) {
	if resp.Body != nil {
		return resp.Body, nil
	}
	b, err := io.ReadAll(resp.bodyReader)
	if err != nil {
		if resp.conn != nil {
			resp.conn.broken = true
		}
		return nil, wrapBodyErr(err)
	}
	resp.Body = b
	return b, nil
}

func decompressBody(resp *Response, raw []byte) ([]byte, error) {
	ct := compressionType(resp.Headers)
	if len(raw) == 0 {
		return raw, nil
	}
	switch ct {
	case "gzip":
		zr, err := gzip.NewReader(bytes.NewReader(raw))
		if err != nil {
			return nil, decodeErr("gzip", gzipErrString(err))
		}
		zr.Multistream(false)
		out, err := io.ReadAll(zr)
		if err != nil {
			return nil, decodeErr("gzip", gzipErrString(err))
		}
		return out, nil
	case "deflate":
		zr, err := zlib.NewReader(bytes.NewReader(raw))
		if err != nil {
			if err == io.ErrUnexpectedEOF || err == io.EOF {
				return []byte{}, nil
			}
			return nil, decodeErr("deflate", "corrupt deflate stream")
		}
		out, err := io.ReadAll(zr)
		if err != nil {
			if err == io.ErrUnexpectedEOF {
				return out, nil
			}
			return nil, decodeErr("deflate", "corrupt deflate stream")
		}
		return out, nil
	case "br":
		out, err := brotliDecode(raw)
		if err != nil {
			return nil, decodeErr("brotli", err.Error())
		}
		return out, nil
	case "zstd":
		out, err := zstdDecode(raw)
		if err != nil {
			return nil, decodeErr("zstd", err.Error())
		}
		return out, nil
	}
	return raw, nil
}

func decodeErr(kind, cause string) error {
	return &chainError{msg: "error decoding " + kind + " response body", causes: []string{cause}}
}

func gzipErrString(err error) string {
	switch {
	case err == gzip.ErrHeader:
		return "invalid gzip header"
	case err == gzip.ErrChecksum:
		return "corrupt gzip stream does not have a matching checksum"
	case err == io.ErrUnexpectedEOF || err == io.EOF:
		return "unexpected end of file"
	}
	return "corrupt deflate stream"
}

func (ct ContentType) isText() bool {
	return ct != CTUnknown && ct != CTMultipart
}

func responseCharset(c *Cli, resp *Response) string {
	if c.ResponseCharset != nil {
		return encodingForLabel(*c.ResponseCharset)
	}
	ct, _ := resp.Headers.Get("content-type")
	return charsetFromContentType(ct)
}

func charsetFromContentType(ct string) string {
	for _, part := range strings.Split(ct, ";")[1:] {
		k, v, ok := strings.Cut(strings.TrimSpace(part), "=")
		if ok && strings.EqualFold(strings.TrimSpace(k), "charset") {
			v = strings.Trim(strings.TrimSpace(v), "\"")
			return encodingForLabel(v)
		}
	}
	return ""
}

func guessEncoding(b []byte) string {
	if len(b) >= 3 && b[0] == 0xef && b[1] == 0xbb && b[2] == 0xbf {
		return "UTF-8"
	}
	if len(b) >= 2 && b[0] == 0xff && b[1] == 0xfe {
		return "UTF-16LE"
	}
	if len(b) >= 2 && b[0] == 0xfe && b[1] == 0xff {
		return "UTF-16BE"
	}
	if isValidUTF8(b) {
		return "UTF-8"
	}
	return "windows-1252"
}

func isValidUTF8(b []byte) bool { return strings.ToValidUTF8(string(b), "\x00\x01") == string(b) }

func decodeUnconditional(b []byte, enc string) string {
	if enc == "" {
		enc = guessEncoding(b)
	} else {
		// BOM sniffing overrides
		if len(b) >= 3 && b[0] == 0xef && b[1] == 0xbb && b[2] == 0xbf {
			enc = "UTF-8"
		} else if len(b) >= 2 && b[0] == 0xff && b[1] == 0xfe {
			enc = "UTF-16LE"
		} else if len(b) >= 2 && b[0] == 0xfe && b[1] == 0xff {
			enc = "UTF-16BE"
		}
	}
	return decodeWith(enc, b)
}

func (p *Printer) PrintResponseBody(c *Cli, resp *Response, body []byte) error {
	var ct ContentType
	if c.ResponseMime != nil {
		ct = contentTypeOf(*c.ResponseMime)
	} else {
		h, _ := resp.Headers.Get("content-type")
		ct = contentTypeOf(h)
	}
	enc := responseCharset(c, resp)
	if !p.buf.isTerminal {
		if (p.color || p.indentJSON) && ct.isText() {
			text := decodeUnconditional(body, enc)
			if err := p.printBodyText(ct, text); err != nil {
				return err
			}
		} else {
			if _, err := p.buf.Write(body); err != nil {
				return err
			}
		}
	} else {
		if bytes.IndexByte(body, 0) >= 0 {
			if err := p.buf.Print(binarySuppressor); err != nil {
				return err
			}
		} else {
			text := decodeUnconditional(body, enc)
			if strings.ContainsRune(text, 0) {
				p.buf.Print(binarySuppressor)
			} else {
				if err := p.printBodyText(ct, text); err != nil {
					return err
				}
				if err := p.buf.Print("\n"); err != nil {
					return err
				}
			}
		}
	}
	p.buf.Flush()
	return nil
}

func sameOrigin(a, b *URL) bool {
	return a.Host == b.Host && a.PortOrDefault() == b.PortOrDefault()
}

func nextRedirect(req *Request, resp *Response) *Request {
	switch resp.Status {
	case 301, 302, 303, 307, 308:
	default:
		return nil
	}
	loc, ok := resp.Headers.Get("location")
	if !ok {
		return nil
	}
	nu, err := req.URL.Join(loc)
	if err != nil {
		return nil
	}
	nr := &Request{Method: req.Method, URL: nu, Version: req.Version, Headers: req.Headers.Clone(), BodyKind: req.BodyKind, Body: req.Body, FilePath: req.FilePath}
	if !sameOrigin(nu, req.URL) {
		for _, h := range []string{"authorization", "cookie", "cookie2", "proxy-authorization", "www-authenticate"} {
			nr.Headers.Remove(h)
		}
	}
	if resp.Status == 301 || resp.Status == 302 || resp.Status == 303 {
		for _, h := range []string{"content-type", "content-length", "content-encoding", "transfer-encoding"} {
			nr.Headers.Remove(h)
		}
		nr.BodyKind = BodyNone
		nr.Body = nil
		if nr.Method != "GET" && nr.Method != "HEAD" {
			nr.Method = "GET"
		}
	}
	return nr
}

type exchangeCtx struct {
	c        *Cli
	hc       *httpClient
	p        *Printer
	hist     Print
	jar      *cookieJar
	digest   *[2]string
}

// send performs one request with digest auth handling and cookie processing.
func (x *exchangeCtx) send(req *Request) (*Response, error) {
	x.jar.apply(req)
	resp, err := x.hc.roundTrip(req)
	if err != nil {
		return nil, err
	}
	x.jar.store(req.URL, resp)
	if x.digest != nil && resp.Status == 401 {
		if wa, ok := resp.Headers.Get("www-authenticate"); ok {
			hdr, err := digestResponse(wa, x.digest[0], x.digest[1], req)
			if err != nil {
				return nil, err
			}
			req.Headers.Insert("authorization", hdr)
			if err := x.printIntermediate(resp, req); err != nil {
				return nil, err
			}
			x.jar.apply(req)
			resp2, err := x.hc.roundTrip(req)
			if err != nil {
				return nil, err
			}
			x.jar.store(req.URL, resp2)
			return resp2, nil
		}
	}
	return resp, nil
}

func (x *exchangeCtx) printIntermediate(resp *Response, next *Request) error {
	if !x.c.All {
		readBody(resp)
		return nil
	}
	hp := x.hist
	if hp.RespHeaders {
		if err := x.p.PrintResponseHeaders(resp); err != nil {
			return err
		}
	}
	raw, err := readBody(resp)
	if err != nil {
		return err
	}
	if hp.RespBody {
		body, err := decompressBody(resp, raw)
		if err != nil {
			return err
		}
		if err := x.p.PrintResponseBody(x.c, resp, body); err != nil {
			return err
		}
		if err := x.p.PrintSeparator(); err != nil {
			return err
		}
	}
	if hp.RespMeta {
		if err := x.p.PrintResponseMeta(resp); err != nil {
			return err
		}
	}
	if hp.ReqHeaders {
		if err := x.p.PrintRequestHeaders(next, x.jar.headerFor(next.URL)); err != nil {
			return err
		}
	}
	if hp.ReqBody {
		if err := x.p.PrintRequestBody(next); err != nil {
			return err
		}
	}
	return nil
}

func execute(c *Cli, req *Request, p *Printer, pr Print, buf *OutBuffer, digest *[2]string) (int, error) {
	hc, err := newHTTPClient(c)
	if err != nil {
		return 0, err
	}
	if hc.timeout > 0 {
		hc.deadline = time.Now().Add(hc.timeout)
	}
	hist := pr
	if c.HistoryPrint != nil {
		hist = parsePrint(*c.HistoryPrint)
	}
	jar := newCookieJar(c)
	x := &exchangeCtx{c: c, hc: hc, p: p, hist: hist, jar: jar, digest: digest}

	if pr.ReqHeaders {
		if err := p.PrintRequestHeaders(req, jar.headerFor(req.URL)); err != nil {
			return 0, err
		}
	}
	if pr.ReqBody {
		if err := p.PrintRequestBody(req); err != nil {
			return 0, err
		}
	}
	resp, err := x.send(req)
	if err != nil {
		return 0, err
	}
	if c.Follow {
		max := uint64(10)
		if c.MaxRedirects != nil {
			max = *c.MaxRedirects
		}
		var remaining uint64
		if max > 0 {
			remaining = max - 1
		}
		cur := req
		for {
			next := nextRedirect(cur, resp)
			if next == nil {
				break
			}
			if remaining > 0 {
				remaining--
			} else {
				return 0, &tooManyRedirects{max: max}
			}
			if err := x.printIntermediate(resp, next); err != nil {
				return 0, err
			}
			cur = next
			resp, err = x.send(next)
			if err != nil {
				return 0, err
			}
		}
	}
	jar.save(resp)

	if pr.RespHeaders {
		if err := p.PrintResponseHeaders(resp); err != nil {
			return 0, err
		}
	}
	checkStatus := !c.CompatMode
	if c.CheckStatus != nil {
		checkStatus = *c.CheckStatus
	}
	exitCode := 0
	if checkStatus {
		switch {
		case resp.Status >= 300 && resp.Status < 400 && !c.Follow:
			exitCode = 3
		case resp.Status >= 400 && resp.Status < 500:
			exitCode = 4
		case resp.Status >= 500 && resp.Status < 600:
			exitCode = 5
		}
	}
	if !stdoutIsTerminal() && exitCode != 0 {
		warn(fmt.Sprintf("HTTP %d %s", resp.Status, reasonPhrase(resp)))
	}
	if c.Download {
		if err := downloadBody(c, resp); err != nil {
			return 0, err
		}
		return exitCode, nil
	}
	if pr.RespBody {
		raw, err := readBody(resp)
		if err != nil {
			return 0, err
		}
		body, err := decompressBody(resp, raw)
		if err != nil {
			return 0, err
		}
		if err := p.PrintResponseBody(c, resp, body); err != nil {
			return 0, err
		}
		if pr.RespMeta {
			if err := p.PrintSeparator(); err != nil {
				return 0, err
			}
		}
	}
	if pr.RespMeta {
		if err := p.PrintResponseMeta(resp); err != nil {
			return 0, err
		}
	}
	buf.Flush()
	if buf.file != nil {
		buf.file.Close()
	}
	return exitCode, nil
}

