package main

// A backtracking regular expression engine supporting the Oniguruma subset
// used by sublime-syntax definitions.

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type reKind int

const (
	rkLit reKind = iota
	rkAny
	rkClass
	rkSeq
	rkAlt
	rkGroup
	rkRepeat
	rkBOL
	rkEOL
	rkWordB
	rkNotWordB
	rkStartText
	rkEndText
	rkEndTextNL
	rkSearchStart
	rkLookahead
	rkLookbehind
	rkBackref
	rkAtomic
	rkEmpty
)

type reNode struct {
	kind       reKind
	r          rune
	fold       bool
	cls        *charClass
	subs       []*reNode
	sub        *reNode
	cap        int // capture index for group; -1 non capture
	min, max   int // repeat; max -1 = inf
	greedy     bool
	possessive bool
	neg        bool
	dotNL      bool
}

type classItem struct {
	lo, hi rune
}

type charClass struct {
	items  []classItem
	funcs  []func(rune) bool
	subs   []*charClass // union of nested
	inters []*charClass // intersection
	neg    bool
	fold   bool
}

func (c *charClass) matches(r rune) bool {
	m := c.rawMatch(r)
	if !m && c.fold {
		for f := unicode.SimpleFold(r); f != r; f = unicode.SimpleFold(f) {
			if c.rawMatch(f) {
				m = true
				break
			}
		}
	}
	if c.neg {
		return !m
	}
	return m
}

func (c *charClass) rawMatch(r rune) bool {
	m := false
	for _, it := range c.items {
		if r >= it.lo && r <= it.hi {
			m = true
			break
		}
	}
	if !m {
		for _, f := range c.funcs {
			if f(r) {
				m = true
				break
			}
		}
	}
	if !m {
		for _, s := range c.subs {
			if s.matches(r) {
				m = true
				break
			}
		}
	}
	if m {
		for _, in := range c.inters {
			if !in.matches(r) {
				return false
			}
		}
	}
	return m
}

type Regex struct {
	root    *reNode
	ncap    int
	names   map[string]int
	src     string
	hasBack bool
}

type reParser struct {
	s      []rune
	i      int
	ncap   int
	names  map[string]int
	fold   bool
	ext    bool
	dotNL  bool
	hasBack bool
}

func CompileRegex(src string) (re *Regex, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("regex parse error: %v", r)
		}
	}()
	p := &reParser{s: []rune(src), names: map[string]int{}}
	n := p.parseAlt()
	if p.i < len(p.s) {
		panic("unexpected ) at " + strconv.Itoa(p.i))
	}
	return &Regex{root: n, ncap: p.ncap + 1, names: p.names, src: src, hasBack: p.hasBack}, nil
}

func (p *reParser) more() bool { return p.i < len(p.s) }
func (p *reParser) peek() rune {
	if p.i < len(p.s) {
		return p.s[p.i]
	}
	return -1
}

func (p *reParser) skipExt() {
	for p.ext && p.i < len(p.s) {
		c := p.s[p.i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.i++
		} else if c == '#' {
			for p.i < len(p.s) && p.s[p.i] != '\n' {
				p.i++
			}
		} else {
			break
		}
	}
}

func (p *reParser) parseAlt() *reNode {
	saveFold, saveExt, saveDot := p.fold, p.ext, p.dotNL
	var alts []*reNode
	for {
		alts = append(alts, p.parseSeq())
		if p.peek() == '|' {
			p.i++
			continue
		}
		break
	}
	p.fold, p.ext, p.dotNL = saveFold, saveExt, saveDot
	if len(alts) == 1 {
		return alts[0]
	}
	return &reNode{kind: rkAlt, subs: alts}
}

func (p *reParser) parseSeq() *reNode {
	var items []*reNode
	for {
		p.skipExt()
		if !p.more() {
			break
		}
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom := p.parseAtom()
		if atom == nil {
			continue
		}
		atom = p.parseQuant(atom)
		items = append(items, atom)
	}
	if len(items) == 1 {
		return items[0]
	}
	return &reNode{kind: rkSeq, subs: items}
}

func (p *reParser) parseQuant(atom *reNode) *reNode {
	for {
		p.skipExt()
		if !p.more() {
			return atom
		}
		c := p.peek()
		min, max := -1, -1
		switch c {
		case '*':
			min, max = 0, -1
			p.i++
		case '+':
			min, max = 1, -1
			p.i++
		case '?':
			min, max = 0, 1
			p.i++
		case '{':
			save := p.i
			p.i++
			a, okA := p.readInt()
			b := a
			okB := okA
			if p.peek() == ',' {
				p.i++
				b, okB = p.readInt()
				if !okB {
					b = -1
					okB = true
				}
				if !okA {
					a = 0
					okA = true
				}
			}
			if okA && okB && p.peek() == '}' {
				p.i++
				min, max = a, b
			} else {
				p.i = save
				return atom
			}
		default:
			return atom
		}
		n := &reNode{kind: rkRepeat, sub: atom, min: min, max: max, greedy: true}
		if p.peek() == '?' {
			p.i++
			n.greedy = false
		} else if p.peek() == '+' && c != '{' {
			p.i++
			n.possessive = true
		}
		atom = n
	}
}

func (p *reParser) readInt() (int, bool) {
	start := p.i
	for p.more() && p.peek() >= '0' && p.peek() <= '9' {
		p.i++
	}
	if p.i == start {
		return 0, false
	}
	v, _ := strconv.Atoi(string(p.s[start:p.i]))
	return v, true
}

func (p *reParser) parseAtom() *reNode {
	c := p.s[p.i]
	switch c {
	case '(':
		return p.parseGroup()
	case '.':
		p.i++
		return &reNode{kind: rkAny, dotNL: p.dotNL}
	case '^':
		p.i++
		return &reNode{kind: rkBOL}
	case '$':
		p.i++
		return &reNode{kind: rkEOL}
	case '[':
		p.i++
		cls := p.parseClass()
		return &reNode{kind: rkClass, cls: cls}
	case '\\':
		return p.parseEscape()
	}
	p.i++
	return &reNode{kind: rkLit, r: c, fold: p.fold}
}

func (p *reParser) parseGroup() *reNode {
	p.i++ // (
	if p.peek() == '?' {
		p.i++
		c := p.peek()
		switch c {
		case ':':
			p.i++
			n := p.parseAlt()
			p.expect(')')
			return &reNode{kind: rkGroup, sub: n, cap: -1}
		case '=', '!':
			p.i++
			n := p.parseAlt()
			p.expect(')')
			return &reNode{kind: rkLookahead, sub: n, neg: c == '!'}
		case '>':
			p.i++
			n := p.parseAlt()
			p.expect(')')
			return &reNode{kind: rkAtomic, sub: n}
		case '#':
			for p.more() && p.peek() != ')' {
				p.i++
			}
			p.expect(')')
			return nil
		case '<':
			p.i++
			if p.peek() == '=' || p.peek() == '!' {
				neg := p.peek() == '!'
				p.i++
				n := p.parseAlt()
				p.expect(')')
				return &reNode{kind: rkLookbehind, sub: n, neg: neg}
			}
			name := p.readName('>')
			p.ncap++
			idx := p.ncap
			p.names[name] = idx
			n := p.parseAlt()
			p.expect(')')
			return &reNode{kind: rkGroup, sub: n, cap: idx}
		case 'P':
			p.i++
			if p.peek() == '<' {
				p.i++
				name := p.readName('>')
				p.ncap++
				idx := p.ncap
				p.names[name] = idx
				n := p.parseAlt()
				p.expect(')')
				return &reNode{kind: rkGroup, sub: n, cap: idx}
			}
			panic("bad (?P")
		case '\'':
			p.i++
			name := p.readName('\'')
			p.ncap++
			idx := p.ncap
			p.names[name] = idx
			n := p.parseAlt()
			p.expect(')')
			return &reNode{kind: rkGroup, sub: n, cap: idx}
		default:
			// inline flags
			on := true
			fold, ext, dot := p.fold, p.ext, p.dotNL
			for p.more() {
				f := p.peek()
				if f == '-' {
					on = false
					p.i++
					continue
				}
				if f == 'i' {
					fold = on
				} else if f == 'x' {
					ext = on
				} else if f == 'm' || f == 's' {
					dot = on
				} else if f == ':' || f == ')' {
					break
				}
				p.i++
			}
			if p.peek() == ')' {
				p.i++
				p.fold, p.ext, p.dotNL = fold, ext, dot
				return nil
			}
			p.i++ // ':'
			sf, se, sd := p.fold, p.ext, p.dotNL
			p.fold, p.ext, p.dotNL = fold, ext, dot
			n := p.parseAlt()
			p.fold, p.ext, p.dotNL = sf, se, sd
			p.expect(')')
			return &reNode{kind: rkGroup, sub: n, cap: -1}
		}
	}
	p.ncap++
	idx := p.ncap
	n := p.parseAlt()
	p.expect(')')
	return &reNode{kind: rkGroup, sub: n, cap: idx}
}

func (p *reParser) readName(end rune) string {
	start := p.i
	for p.more() && p.peek() != end {
		p.i++
	}
	name := string(p.s[start:p.i])
	p.i++
	return name
}

func (p *reParser) expect(c rune) {
	if p.peek() != c {
		panic(fmt.Sprintf("expected %c at %d", c, p.i))
	}
	p.i++
}

func isWordRune(r rune) bool {
	return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Nd, r) || unicode.Is(unicode.Pc, r)
}

func isSpaceRune(r rune) bool {
	switch r {
	case ' ', '\t', '\n', '\r', '\f', '\v':
		return true
	}
	return r > 127 && unicode.IsSpace(r)
}

func isHexRune(r rune) bool {
	return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F')
}

func classFor(c rune) *charClass {
	switch c {
	case 'w':
		return &charClass{funcs: []func(rune) bool{isWordRune}}
	case 'W':
		return &charClass{funcs: []func(rune) bool{isWordRune}, neg: true}
	case 'd':
		return &charClass{funcs: []func(rune) bool{unicode.IsDigit}}
	case 'D':
		return &charClass{funcs: []func(rune) bool{unicode.IsDigit}, neg: true}
	case 's':
		return &charClass{funcs: []func(rune) bool{isSpaceRune}}
	case 'S':
		return &charClass{funcs: []func(rune) bool{isSpaceRune}, neg: true}
	case 'h':
		return &charClass{funcs: []func(rune) bool{isHexRune}}
	case 'H':
		return &charClass{funcs: []func(rune) bool{isHexRune}, neg: true}
	}
	return nil
}

func (p *reParser) parseEscapeChar() (rune, bool) {
	// after backslash; returns literal rune
	c := p.s[p.i]
	p.i++
	switch c {
	case 'n':
		return '\n', true
	case 't':
		return '\t', true
	case 'r':
		return '\r', true
	case 'f':
		return '\f', true
	case 'v':
		return '\v', true
	case 'a':
		return 7, true
	case 'e':
		return 27, true
	case '0':
		v := 0
		for k := 0; k < 2 && p.more() && p.peek() >= '0' && p.peek() <= '7'; k++ {
			v = v*8 + int(p.peek()-'0')
			p.i++
		}
		return rune(v), true
	case 'x':
		if p.peek() == '{' {
			p.i++
			start := p.i
			for p.more() && p.peek() != '}' {
				p.i++
			}
			v, _ := strconv.ParseUint(string(p.s[start:p.i]), 16, 32)
			p.i++
			return rune(v), true
		}
		start := p.i
		for k := 0; k < 2 && p.more() && isHexRune(p.peek()); k++ {
			p.i++
		}
		v, _ := strconv.ParseUint(string(p.s[start:p.i]), 16, 32)
		return rune(v), true
	case 'u':
		start := p.i
		for k := 0; k < 4 && p.more() && isHexRune(p.peek()); k++ {
			p.i++
		}
		v, _ := strconv.ParseUint(string(p.s[start:p.i]), 16, 32)
		return rune(v), true
	}
	return c, false
}

func unicodeProp(name string) func(rune) bool {
	neg := false
	if strings.HasPrefix(name, "^") {
		neg = true
		name = name[1:]
	}
	var f func(rune) bool
	switch strings.ToLower(strings.ReplaceAll(name, "_", "")) {
	case "l", "letter", "alpha", "alphabetic":
		f = unicode.IsLetter
	case "lu", "upper", "uppercaseletter":
		f = unicode.IsUpper
	case "ll", "lower", "lowercaseletter":
		f = unicode.IsLower
	case "n", "number":
		f = unicode.IsNumber
	case "nd", "digit":
		f = unicode.IsDigit
	case "alnum":
		f = func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) }
	case "space", "whitespace":
		f = unicode.IsSpace
	case "p", "punct", "punctuation":
		f = unicode.IsPunct
	case "word":
		f = isWordRune
	default:
		if t, ok := unicode.Categories[name]; ok {
			tt := t
			f = func(r rune) bool { return unicode.Is(tt, r) }
		} else if t, ok := unicode.Scripts[name]; ok {
			tt := t
			f = func(r rune) bool { return unicode.Is(tt, r) }
		} else {
			f = func(r rune) bool { return false }
		}
	}
	if neg {
		return func(r rune) bool { return !f(r) }
	}
	return f
}

func (p *reParser) parseEscape() *reNode {
	p.i++ // backslash
	if !p.more() {
		return &reNode{kind: rkLit, r: '\\'}
	}
	c := p.peek()
	switch c {
	case 'b':
		p.i++
		return &reNode{kind: rkWordB}
	case 'B':
		p.i++
		return &reNode{kind: rkNotWordB}
	case 'A':
		p.i++
		return &reNode{kind: rkStartText}
	case 'z':
		p.i++
		return &reNode{kind: rkEndText}
	case 'Z':
		p.i++
		return &reNode{kind: rkEndTextNL}
	case 'G':
		p.i++
		return &reNode{kind: rkSearchStart}
	case 'w', 'W', 'd', 'D', 's', 'S', 'h', 'H':
		p.i++
		cls := classFor(c)
		return &reNode{kind: rkClass, cls: cls}
	case 'p', 'P':
		p.i++
		var name string
		if p.peek() == '{' {
			p.i++
			name = p.readName('}')
		} else {
			name = string(p.peek())
			p.i++
		}
		f := unicodeProp(name)
		return &reNode{kind: rkClass, cls: &charClass{funcs: []func(rune) bool{f}, neg: c == 'P'}}
	case 'k':
		p.i++
		if p.peek() == '<' {
			p.i++
			name := p.readName('>')
			p.hasBack = true
			if idx, ok := p.names[name]; ok {
				return &reNode{kind: rkBackref, cap: idx, fold: p.fold}
			}
			v, _ := strconv.Atoi(name)
			return &reNode{kind: rkBackref, cap: v, fold: p.fold}
		}
		return &reNode{kind: rkLit, r: 'k'}
	}
	if c >= '1' && c <= '9' {
		v := 0
		for p.more() && p.peek() >= '0' && p.peek() <= '9' {
			v = v*10 + int(p.peek()-'0')
			p.i++
		}
		p.hasBack = true
		return &reNode{kind: rkBackref, cap: v, fold: p.fold}
	}
	r, _ := p.parseEscapeChar()
	return &reNode{kind: rkLit, r: r, fold: p.fold}
}

var posixClasses = map[string]func(rune) bool{
	"alpha":  unicode.IsLetter,
	"alnum":  func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) },
	"digit":  func(r rune) bool { return r >= '0' && r <= '9' },
	"upper":  unicode.IsUpper,
	"lower":  unicode.IsLower,
	"space":  isSpaceRune,
	"blank":  func(r rune) bool { return r == ' ' || r == '\t' },
	"punct":  func(r rune) bool { return r < 128 && unicode.IsPunct(r) || r < 128 && unicode.IsSymbol(r) || r >= 128 && unicode.IsPunct(r) },
	"xdigit": isHexRune,
	"word":   isWordRune,
	"cntrl":  unicode.IsControl,
	"print":  func(r rune) bool { return unicode.IsPrint(r) },
	"graph":  func(r rune) bool { return unicode.IsGraphic(r) && r != ' ' },
	"ascii":  func(r rune) bool { return r < 128 },
}

func (p *reParser) parseClass() *charClass {
	cls := &charClass{fold: p.fold}
	if p.peek() == '^' {
		cls.neg = true
		p.i++
	}
	first := true
	cur := cls
	_ = cur
	var pendingInter []*charClass
	acc := &charClass{fold: p.fold}
	for {
		if !p.more() {
			panic("unterminated class")
		}
		c := p.peek()
		if c == ']' && !first {
			p.i++
			break
		}
		first = false
		if c == '&' && p.i+1 < len(p.s) && p.s[p.i+1] == '&' {
			p.i += 2
			pendingInter = append(pendingInter, acc)
			acc = &charClass{fold: p.fold}
			continue
		}
		if c == '[' {
			if p.i+1 < len(p.s) && p.s[p.i+1] == ':' {
				end := strings.Index(string(p.s[p.i:]), ":]")
				if end > 0 {
					name := string(p.s[p.i+2 : p.i+end])
					neg := false
					if strings.HasPrefix(name, "^") {
						neg = true
						name = name[1:]
					}
					if f, ok := posixClasses[name]; ok {
						p.i += end + 2
						if neg {
							ff := f
							acc.funcs = append(acc.funcs, func(r rune) bool { return !ff(r) })
						} else {
							acc.funcs = append(acc.funcs, f)
						}
						continue
					}
				}
			}
			p.i++
			sub := p.parseClass()
			acc.subs = append(acc.subs, sub)
			continue
		}
		var lo rune
		if c == '\\' {
			p.i++
			e := p.peek()
			if cf := classFor(e); cf != nil {
				p.i++
				acc.subs = append(acc.subs, cf)
				continue
			}
			if e == 'p' || e == 'P' {
				p.i++
				var name string
				if p.peek() == '{' {
					p.i++
					name = p.readName('}')
				} else {
					name = string(p.peek())
					p.i++
				}
				f := unicodeProp(name)
				if e == 'P' {
					ff := f
					f = func(r rune) bool { return !ff(r) }
				}
				acc.funcs = append(acc.funcs, f)
				continue
			}
			if e == 'b' {
				p.i++
				lo = 8
			} else {
				lo, _ = p.parseEscapeChar()
			}
		} else {
			p.i++
			lo = c
		}
		hi := lo
		if p.peek() == '-' && p.i+1 < len(p.s) && p.s[p.i+1] != ']' {
			p.i++
			h := p.peek()
			if h == '\\' {
				p.i++
				hi, _ = p.parseEscapeChar()
			} else if h == '[' {
				// treat '-' literally
				acc.items = append(acc.items, classItem{lo, lo}, classItem{'-', '-'})
				continue
			} else {
				p.i++
				hi = h
			}
		}
		acc.items = append(acc.items, classItem{lo, hi})
	}
	if len(pendingInter) > 0 {
		base := pendingInter[0]
		base.inters = append(base.inters, pendingInter[1:]...)
		base.inters = append(base.inters, acc)
		cls.subs = append(cls.subs, base)
	} else {
		cls.items = acc.items
		cls.funcs = acc.funcs
		cls.subs = acc.subs
	}
	return cls
}

// ---------- matching ----------

type reMatcher struct {
	s     string
	caps  []int
	start int
	steps int
}

func (m *reMatcher) runeAt(i int) (rune, int) {
	if i >= len(m.s) {
		return -1, 0
	}
	c := m.s[i]
	if c < utf8.RuneSelf {
		return rune(c), 1
	}
	return utf8.DecodeRuneInString(m.s[i:])
}

func (m *reMatcher) runeBefore(i int) rune {
	if i <= 0 {
		return -1
	}
	r, _ := utf8.DecodeLastRuneInString(m.s[:i])
	return r
}

func foldEq(a, b rune) bool {
	if a == b {
		return true
	}
	for f := unicode.SimpleFold(a); f != a; f = unicode.SimpleFold(f) {
		if f == b {
			return true
		}
	}
	return false
}

func (m *reMatcher) isWordAt(i int) bool {
	r, _ := m.runeAt(i)
	return r >= 0 && isWordRune(r)
}

func (m *reMatcher) match(n *reNode, i int, k func(int) bool) bool {
	m.steps++
	switch n.kind {
	case rkEmpty:
		return k(i)
	case rkLit:
		r, sz := m.runeAt(i)
		if r < 0 {
			return false
		}
		if r == n.r || (n.fold && foldEq(r, n.r)) {
			return k(i + sz)
		}
		return false
	case rkAny:
		r, sz := m.runeAt(i)
		if r < 0 || (r == '\n' && !n.dotNL) {
			return false
		}
		return k(i + sz)
	case rkClass:
		r, sz := m.runeAt(i)
		if r < 0 || !n.cls.matches(r) {
			return false
		}
		return k(i + sz)
	case rkSeq:
		return m.matchSeq(n.subs, 0, i, k)
	case rkAlt:
		for _, a := range n.subs {
			if m.match(a, i, k) {
				return true
			}
		}
		return false
	case rkGroup:
		if n.cap < 0 {
			return m.match(n.sub, i, k)
		}
		os, oe := m.caps[2*n.cap], m.caps[2*n.cap+1]
		if m.match(n.sub, i, func(e int) bool {
			ps, pe := m.caps[2*n.cap], m.caps[2*n.cap+1]
			m.caps[2*n.cap], m.caps[2*n.cap+1] = i, e
			if k(e) {
				return true
			}
			m.caps[2*n.cap], m.caps[2*n.cap+1] = ps, pe
			return false
		}) {
			return true
		}
		m.caps[2*n.cap], m.caps[2*n.cap+1] = os, oe
		return false
	case rkRepeat:
		if n.possessive {
			count := 0
			pos := i
			for n.max < 0 || count < n.max {
				np := -1
				m.match(n.sub, pos, func(e int) bool { np = e; return true })
				if np < 0 || (np == pos && count >= n.min) {
					break
				}
				pos = np
				count++
			}
			if count < n.min {
				return false
			}
			return k(pos)
		}
		return m.matchRepeat(n, i, 0, k)
	case rkBOL:
		if i == 0 || m.s[i-1] == '\n' {
			return k(i)
		}
		return false
	case rkEOL:
		if i == len(m.s) || m.s[i] == '\n' {
			return k(i)
		}
		return false
	case rkWordB:
		if m.isWordAt(i) != (i > 0 && isWordRune(m.runeBefore(i))) {
			return k(i)
		}
		return false
	case rkNotWordB:
		if m.isWordAt(i) == (i > 0 && isWordRune(m.runeBefore(i))) {
			return k(i)
		}
		return false
	case rkStartText:
		if i == 0 {
			return k(i)
		}
		return false
	case rkEndText:
		if i == len(m.s) {
			return k(i)
		}
		return false
	case rkEndTextNL:
		if i == len(m.s) || (i == len(m.s)-1 && m.s[i] == '\n') {
			return k(i)
		}
		return false
	case rkSearchStart:
		if i == m.start {
			return k(i)
		}
		return false
	case rkLookahead:
		saved := append([]int{}, m.caps...)
		ok := m.match(n.sub, i, func(int) bool { return true })
		if n.neg {
			copy(m.caps, saved)
			if ok {
				return false
			}
			return k(i)
		}
		if !ok {
			copy(m.caps, saved)
			return false
		}
		if k(i) {
			return true
		}
		copy(m.caps, saved)
		return false
	case rkLookbehind:
		found := false
		for st := i; st >= 0 && !found; st-- {
			if st < len(m.s) && st > 0 && !utf8.RuneStart(m.s[st]) {
				continue
			}
			if m.match(n.sub, st, func(e int) bool { return e == i }) {
				found = true
			}
		}
		if found != n.neg {
			return k(i)
		}
		return false
	case rkAtomic:
		end := -1
		m.match(n.sub, i, func(e int) bool { end = e; return true })
		if end < 0 {
			return false
		}
		return k(end)
	case rkBackref:
		if n.cap >= len(m.caps)/2 {
			return false
		}
		s, e := m.caps[2*n.cap], m.caps[2*n.cap+1]
		if s < 0 {
			return false
		}
		sub := m.s[s:e]
		if i+len(sub) > len(m.s) {
			return false
		}
		if m.s[i:i+len(sub)] == sub || (n.fold && strings.EqualFold(m.s[i:i+len(sub)], sub)) {
			return k(i + len(sub))
		}
		return false
	}
	return false
}

func (m *reMatcher) matchSeq(subs []*reNode, idx int, i int, k func(int) bool) bool {
	if idx == len(subs) {
		return k(i)
	}
	return m.match(subs[idx], i, func(e int) bool {
		return m.matchSeq(subs, idx+1, e, k)
	})
}

func (m *reMatcher) matchRepeat(n *reNode, i int, count int, k func(int) bool) bool {
	canMore := n.max < 0 || count < n.max
	if count < n.min {
		return m.match(n.sub, i, func(e int) bool {
			if e == i && count+1 >= n.min {
				// empty iteration satisfies min; stop iterating
				return m.matchRepeatTail(n, e, count+1, k, true)
			}
			return m.matchRepeat(n, e, count+1, k)
		})
	}
	if n.greedy {
		if canMore && m.match(n.sub, i, func(e int) bool {
			if e == i {
				return false
			}
			return m.matchRepeat(n, e, count+1, k)
		}) {
			return true
		}
		return k(i)
	}
	if k(i) {
		return true
	}
	if canMore {
		return m.match(n.sub, i, func(e int) bool {
			if e == i {
				return false
			}
			return m.matchRepeat(n, e, count+1, k)
		})
	}
	return false
}

func (m *reMatcher) matchRepeatTail(n *reNode, i int, count int, k func(int) bool, _ bool) bool {
	return k(i)
}

// SearchAt finds the leftmost match starting at or after start. Returns capture positions.
func (re *Regex) SearchAt(s string, start int) []int {
	return re.searchWith(s, start, re.root)
}

func (re *Regex) searchWith(s string, start int, root *reNode) []int {
	m := &reMatcher{s: s, caps: make([]int, 2*re.ncap), start: start}
	for pos := start; pos <= len(s); {
		for j := range m.caps {
			m.caps[j] = -1
		}
		end := -1
		if m.match(root, pos, func(e int) bool { end = e; return true }) {
			m.caps[0], m.caps[1] = pos, end
			return append([]int{}, m.caps...)
		}
		if pos >= len(s) {
			break
		}
		_, sz := utf8.DecodeRuneInString(s[pos:])
		if sz == 0 {
			sz = 1
		}
		pos += sz
	}
	return nil
}
