package main

import (
	"math/rand"
	"regexp"
	"testing"
)

func TestRegexAgainstGo(t *testing.T) {
	pats := []string{`a+b`, `(a|ab)(c|bcd)(d*)`, `[a-c]+?d`, `\w+@\w+\.com`, `(?i)ABC`, `x*`, `(a*)*b`, `^ab|cd$`, `[^a-c]{2,3}`, `(\d+)\.(\d+)?`, `a{2}`, `\bfoo\b`, `(?:ab)+`, `.*?c`, `[[:alpha:]]+`, `\s+\S`, `(a)|b`, `[a-z&&[^aeiou]]+`}
	alpha := "abcdx .@1234c\n"
	r := rand.New(rand.NewSource(1))
	for _, p := range pats {
		re, err := CompileRegex(p)
		if err != nil {
			t.Fatal(p, err)
		}
		gp := p
		if p == `[a-z&&[^aeiou]]+` {
			gp = `[b-df-hj-np-tv-z]+`
		}
		gre := regexp.MustCompile(gp)
		for n := 0; n < 300; n++ {
			l := r.Intn(12)
			b := make([]byte, l)
			for i := range b {
				b[i] = alpha[r.Intn(len(alpha))]
			}
			s := string(b)
			want := gre.FindStringSubmatchIndex(s)
			got := re.SearchAt(s, 0)
			if (want == nil) != (got == nil) {
				t.Errorf("%q on %q: want %v got %v", p, s, want, got)
				continue
			}
			if want != nil {
				for i := range want {
					if want[i] != got[i] {
						t.Errorf("%q on %q: want %v got %v", p, s, want, got)
						break
					}
				}
			}
		}
	}
}

func TestRegexFeatures(t *testing.T) {
	cases := []struct{ p, s string; want []int }{
		{`a(?=b)`, "ab", []int{0, 1}},
		{`a(?!b)`, "abac", []int{2, 3}},
		{`(a)\1`, "xaa", []int{1, 3, 1, 2}},
		{`(?<=a)b`, "cbab", []int{3, 4}},
		{`a*+a`, "aaa", nil},
		{`\h+`, "zz0aF", []int{2, 5}},
		{`(?x) a b # comment`, "ab", []int{0, 2}},
	}
	for _, c := range cases {
		re, err := CompileRegex(c.p)
		if err != nil {
			t.Fatal(err)
		}
		got := re.SearchAt(c.s, 0)
		if len(got) > len(c.want) && c.want != nil {
			got = got[:len(c.want)]
		}
		if (got == nil) != (c.want == nil) {
			t.Errorf("%q %q want %v got %v", c.p, c.s, c.want, got)
			continue
		}
		for i := range c.want {
			if got[i] != c.want[i] {
				t.Errorf("%q %q want %v got %v", c.p, c.s, c.want, got)
			}
		}
	}
}
