package main

// Minimal YAML subset parser sufficient for .sublime-syntax files.

import (
	"fmt"
	"strconv"
	"strings"
)

type yNode struct {
	kind int // 0 scalar, 1 map, 2 seq
	str  string
	keys []string
	m    map[string]*yNode
	seq  []*yNode
	quoted bool
}

type yLine struct {
	indent int
	text   string // without indentation, comments stripped
	raw    string
	num    int
}

type yParser struct {
	lines []yLine
	pos   int
	all   []string
}

func stripYAMLComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inS:
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inS = false
				}
			}
		case inD:
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
		default:
			if c == '\'' && (i == 0 || isYStart(s, i)) {
				inS = true
			} else if c == '"' && (i == 0 || isYStart(s, i)) {
				inD = true
			} else if c == '#' && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return strings.TrimRight(s, " \t")
}

// quotes only start a quoted scalar at value start positions
func isYStart(s string, i int) bool {
	j := i - 1
	for j >= 0 && (s[j] == ' ' || s[j] == '\t') {
		j--
	}
	if j < 0 {
		return true
	}
	return s[j] == ':' || s[j] == '-' || s[j] == '[' || s[j] == ','
}

func parseYAML(src string) (*yNode, error) {
	p := &yParser{}
	raw := strings.Split(strings.ReplaceAll(src, "\r\n", "\n"), "\n")
	p.all = raw
	for i, l := range raw {
		t := strings.TrimLeft(l, " ")
		ind := len(l) - len(t)
		if strings.HasPrefix(t, "%YAML") || t == "---" {
			continue
		}
		p.lines = append(p.lines, yLine{indent: ind, text: t, raw: l, num: i})
	}
	var err error
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("yaml: %v", r)
		}
	}()
