func (p *yParser) cur() yLine {
	if p.pos < len(p.lines) {
		return p.lines[p.pos]
	}
	return yLine{indent: -1}
}

func (p *yParser) skipBlank() {
	for p.pos < len(p.lines) {
		t := stripYAMLComment(p.lines[p.pos].text)
		if t == "" {
			p.pos++
			continue
		}
