func splitKey(t string) (string, string, bool) {
	// returns key, rest
	if strings.HasPrefix(t, "'") || strings.HasPrefix(t, "\"") {
		q := t[0]
		for i := 1; i < len(t); i++ {
			if t[i] == q {
				rest := t[i+1:]
				if strings.HasPrefix(rest, ":") {
					k, _ := parseQuoted(t[:i+1])
					return k, strings.TrimLeft(rest[1:], " "), true
				}
				break
			}
		}
		return "", "", false
	}
	for i := 0; i < len(t); i++ {
		if t[i] == ':' && (i+1 == len(t) || t[i+1] == ' ' || t[i+1] == '\t') {
			return t[:i], strings.TrimLeft(t[i+1:], " \t"), true
