		if rest == "" {
			p.skipBlank()
			nl := p.cur()
			if nl.indent > indent || (nl.indent == indent && (strings.HasPrefix(stripYAMLComment(nl.text), "- ") || stripYAMLComment(nl.text) == "-")) {
