			break
		}
		t := stripYAMLComment(l.text)
		if !(t == "-" || strings.HasPrefix(t, "- ")) {
			break
		}
		p.pos++
		rest := strings.TrimLeft(strings.TrimPrefix(t, "-"), " ")
