func (p *yParser) parseBlockScalar(header string, indent int) *yNode {
	folded := header[0] == '>'
	chomp := "clip"
	if strings.Contains(header, "-") {
		chomp = "strip"
	} else if strings.Contains(header, "+") {
		chomp = "keep"
	}
	var lines []string
	blockIndent := -1
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if strings.TrimSpace(l.raw) == "" {
			lines = append(lines, "")
			p.pos++
			continue
		}
		if l.indent <= indent {
			break
		}
		if blockIndent < 0 {
			blockIndent = l.indent
		}
		if l.indent < blockIndent {
			break
		}
		lines = append(lines, l.raw[blockIndent:])
		p.pos++
	}
	// trailing empty lines
	end := len(lines)
	for end > 0 && lines[end-1] == "" {
		end--
	}
	trailing := lines[end:]
	lines = lines[:end]
	var s string
	if folded {
		var b strings.Builder
		for i, l := range lines {
			if i > 0 {
				if l == "" || lines[i-1] == "" || strings.HasPrefix(l, " ") {
					b.WriteString("\n")
				} else {
					b.WriteString(" ")
				}
			}
			b.WriteString(l)
		}
		s = b.String()
	} else {
		s = strings.Join(lines, "\n")
	}
	switch chomp {
	case "clip":
		if len(lines) > 0 {
			s += "\n"
		}
	case "keep":
		s += "\n" + strings.Repeat("\n", len(trailing))
	}
	return &yNode{kind: 0, str: s, quoted: true}
}

func parseFlowSeq(s string) *yNode {
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "[")
	s = strings.TrimSuffix(s, "]")
	n := &yNode{kind: 2}
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if strings.HasPrefix(part, "'") || strings.HasPrefix(part, "\"") {
			v, _ := parseQuoted(part)
			n.seq = append(n.seq, &yNode{kind: 0, str: v, quoted: true})
		} else {
			n.seq = append(n.seq, &yNode{kind: 0, str: part})
		}
	}
	return n
}

func parseQuoted(s string) (string, int) {
	q := s[0]
	var b strings.Builder
	i := 1
	for i < len(s) {
		c := s[i]
		if q == '\'' {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					b.WriteByte('\'')
					i += 2
					continue
				}
				return b.String(), i + 1
			}
			b.WriteByte(c)
			i++
			continue
		}
		if c == '"' {
			return b.String(), i + 1
		}
		if c == '\\' && i+1 < len(s) {
			e := s[i+1]
			i += 2
			switch e {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '\\':
				b.WriteByte('\\')
			case '"':
				b.WriteByte('"')
			case '/':
				b.WriteByte('/')
			case '0':
				b.WriteByte(0)
			case 'x':
				v, _ := strconv.ParseUint(s[i:i+2], 16, 8)
				b.WriteRune(rune(v))
				i += 2
			case 'u':
				v, _ := strconv.ParseUint(s[i:i+4], 16, 32)
				b.WriteRune(rune(v))
				i += 4
			default:
				b.WriteByte('\\')
				b.WriteByte(e)
			}
			continue
		}
		b.WriteByte(c)
		i++
	}
	return b.String(), i
}

func (n *yNode) get(k string) *yNode {
	if n == nil || n.kind != 1 {
		return nil
	}
	return n.m[k]
}
