{"command":"cd /workspace; cat > syntax.go <<'EOF'
package main

import (
	"embed"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
)

//go:embed assets/syntax/basic/*.sublime-syntax assets/syntax/large/*.sublime-syntax
var syntaxFS embed.FS

type Scope = string

type sOpKind int

const (
	opNone sOpKind = iota
	opPush
	opSet
	opPop
)

type ctxRef struct {
	name   string // context name in syntax
	syntax string // scope of syntax ("" = same)
	inline *sContext
	owner  *sSyntax
	resolved *sContext
}

type sPattern struct {
	isInclude     bool
	include       *ctxRef
	regexSrc      string
	regex         *Regex
	hasBackrefs   bool
	scope         []Scope
	captures      []capScopes
	op            sOpKind
	refs          []*ctxRef
	withPrototype *ctxRef
}

type capScopes struct {
	idx    int
	scopes []Scope
}

type sContext struct {
	name                 string
	metaScope            []Scope
	metaContentScope     []Scope
	metaIncludePrototype bool
	clearScopes          int // -1 none, 0 all, n top n
	patterns             []*sPattern
	prototype            *sContext
	usesBackrefs         bool
	syntax               *sSyntax
	isPrototype          bool
}

type sSyntax struct {
	name      string
	scope     string
	variables map[string]string
	contexts  map[string]*sContext
	inline    []*sContext
	protoName bool
}

type syntaxSet struct {
	byScope map[string]*sSyntax
	byName  map[string]*sSyntax
}

var (
	synSetOnce sync.Once
	synSet     *syntaxSet
)

func loadSyntaxSet() *syntaxSet {
	synSetOnce.Do(func() {
		ss := &syntaxSet{byScope: map[string]*sSyntax{}, byName: map[string]*sSyntax{}}
		files := []string{"assets/syntax/basic/json.sublime-syntax", "assets/syntax/large/css.sublime-syntax", "assets/syntax/large/html.sublime-syntax", "assets/syntax/large/js.sublime-syntax", "assets/syntax/large/xml.sublime-syntax"}
		names := []string{"json", "css", "html", "js", "xml"}
		for i, f := range files {
			data, err := syntaxFS.ReadFile(f)
			if err != nil {
				continue
			}
			syn := parseSublimeSyntax(string(data))
			if syn == nil {
				continue
			}
			ss.byScope[syn.scope] = syn
			ss.byName[names[i]] = syn
		}
		hs := httpSyntax()
		ss.byScope[hs.scope] = hs
		ss.byName["http"] = hs
		// link
		for _, syn := range ss.byScope {
			ss.link(syn)
		}
		synSet = ss
	})
	return synSet
}

var varRe = regexp.MustCompile(`\{\{([A-Za-z0-9_]+)\}\}`)

func (s *sSyntax) resolveVars(src string) string {
	for depth := 0; depth < 20 && strings.Contains(src, "{{"); depth++ {
		nsrc := varRe.ReplaceAllStringFunc(src, func(m string) string {
			name := m[2 : len(m)-2]
			if v, ok := s.variables[name]; ok {
				return v
			}
			return m
		})
		if nsrc == src {
			break
		}
		src = nsrc
	}
	return src
}

func splitScopes(s string) []Scope {
	return strings.Fields(s)
}

func parseSublimeSyntax(src string) *sSyntax {
	root, err := parseYAML(src)
	if err != nil || root == nil {
		return nil
	}
	syn := &sSyntax{contexts: map[string]*sContext{}, variables: map[string]string{}}
	if n := root.get("name"); n != nil {
		syn.name = n.str
	}
	if n := root.get("scope"); n != nil {
		syn.scope = n.str
	}
	if v := root.get("variables"); v != nil {
		for _, k := range v.keys {
			syn.variables[k] = v.m[k].str
		}
	}
	ctxs := root.get("contexts")
	if ctxs == nil {
		return nil
	}
	for _, name := range ctxs.keys {
		c := syn.parseContext(ctxs.m[name], name == "prototype")
		c.name = name
		if name == "prototype" {
			c.isPrototype = true
		}
		syn.contexts[name] = c
	}
	if m, ok := syn.contexts["main"]; ok {
		m.metaContentScope = append([]Scope{syn.scope}, m.metaContentScope...)
	}
	return syn
}

func (s *sSyntax) parseContext(n *yNode, inProto bool) *sContext {
	c := &sContext{metaIncludePrototype: !inProto, clearScopes: -1, syntax: s}
	if n == nil || n.kind != 2 {
		return c
	}
	for _, item := range n.seq {
		if item.kind != 1 {
			continue
		}
		if v := item.get("meta_scope"); v != nil {
			c.metaScope = splitScopes(v.str)
			continue
		}
		if v := item.get("meta_content_scope"); v != nil {
			c.metaContentScope = splitScopes(v.str)
			continue
		}
		if v := item.get("meta_include_prototype"); v != nil {
			c.metaIncludePrototype = v.str == "true"
			continue
		}
		if v := item.get("clear_scopes"); v != nil {
			if v.str == "true" {
				c.clearScopes = 0
			} else if n, err := strconv.Atoi(v.str); err == nil {
				c.clearScopes = n
			}
			continue
		}
		if v := item.get("include"); v != nil {
			c.patterns = append(c.patterns, &sPattern{isInclude: true, include: s.parseRef(v, inProto)})
			continue
		}
		if v := item.get("match"); v != nil {
			c.patterns = append(c.patterns, s.parseMatch(item, inProto))
		}
	}
	return c
}

func (s *sSyntax) parseRef(v *yNode, inProto bool) *ctxRef {
	if v.kind == 2 {
		ic := s.parseContext(v, inProto)
		s.inline = append(s.inline, ic)
		return &ctxRef{inline: ic, owner: s}
	}
	str := v.str
	if strings.HasPrefix(str, "scope:") {
		rest := str[len("scope:"):]
		name := "main"
		if i := strings.Index(rest, "#"); i >= 0 {
			name = rest[i+1:]
			rest = rest[:i]
		}
		return &ctxRef{syntax: rest, name: name, owner: s}
	}
	return &ctxRef{name: str, owner: s}
}

func (s *sSyntax) parseRefs(v *yNode, inProto bool) []*ctxRef {
	if v.kind == 2 && len(v.seq) > 0 && v.seq[0].kind == 0 {
		var out []*ctxRef
		for _, x := range v.seq {
			out = append(out, s.parseRef(x, inProto))
		}
		return out
	}
	return []*ctxRef{s.parseRef(v, inProto)}
}

func (s *sSyntax) parseMatch(item *yNode, inProto bool) *sPattern {
	p := &sPattern{}
	src := s.resolveVars(item.get("match").str)
	p.regexSrc = src
	re, err := CompileRegex(src)
	if err != nil {
		re, _ = CompileRegex(`(?!)`)
	}
	p.regex = re
	p.hasBackrefs = re.hasBack
	if v := item.get("scope"); v != nil {
		p.scope = splitScopes(v.str)
	}
	if v := item.get("captures"); v != nil && v.kind == 1 {
		for _, k := range v.keys {
			idx, err := strconv.Atoi(k)
			if err != nil {
				continue
			}
			p.captures = append(p.captures, capScopes{idx: idx, scopes: splitScopes(v.m[k].str)})
		}
		sort.SliceStable(p.captures, func(i, j int) bool { return p.captures[i].idx < p.captures[j].idx })
	}
	if v := item.get("push"); v != nil {
		p.op = opPush
		p.refs = s.parseRefs(v, inProto)
	} else if v := item.get("set"); v != nil {
		p.op = opSet
		p.refs = s.parseRefs(v, inProto)
	} else if v := item.get("pop"); v != nil && v.str == "true" {
		p.op = opPop
	} else if v := item.get("embed"); v != nil {
		p.op = opPush
		esc := &sContext{metaIncludePrototype: false, clearScopes: -1, syntax: s}
		if es := item.get("embed_scope"); es != nil {
			esc.metaContentScope = splitScopes(es.str)
		}
		if ev := item.get("escape"); ev != nil {
			ep := &sPattern{op: opPop}
			esrc := s.resolveVars(ev.str)
			ep.regexSrc = esrc
			ep.regex, _ = CompileRegex(esrc)
			if ep.regex == nil {
				ep.regex, _ = CompileRegex(`(?!)`)
			}
			ep.hasBackrefs = ep.regex.hasBack
			if ec := item.get("escape_captures"); ec != nil && ec.kind == 1 {
				for _, k := range ec.keys {
					idx, err := strconv.Atoi(k)
					if err == nil {
						ep.captures = append(ep.captures, capScopes{idx: idx, scopes: splitScopes(ec.m[k].str)})
					}
				}
			}
			esc.patterns = append(esc.patterns, ep)
		}
		s.inline = append(s.inline, esc)
		escRef := &ctxRef{inline: esc, owner: s}
		p.refs = []*ctxRef{escRef, s.parseRef(v, inProto)}
		p.withPrototype = escRef
	}
	if v := item.get("with_prototype"); v != nil {
		p.withPrototype = s.parseRef(v, true)
	}
	return p
}

func (ss *syntaxSet) resolve(r *ctxRef) *sContext {
	if r.resolved != nil {
		return r.resolved
	}
	if r.inline != nil {
		r.resolved = r.inline
		return r.inline
	}
	syn := r.owner
	if r.syntax != "" {
		syn = ss.byScope[r.syntax]
	}
	if syn == nil {
		return nil
	}
	name := r.name
	if name == "$self" || name == "$top_level_main" {
		name = "main"
	}
	c := syn.contexts[name]
	r.resolved = c
	return c
}

func (ss *syntaxSet) link(syn *sSyntax) {
	proto := syn.contexts["prototype"]
	// contexts reachable from prototype do not get the prototype
	noProto := map[*sContext]bool{}
	if proto != nil {
		var mark func(c *sContext)
		mark = func(c *sContext) {
			if c == nil || noProto[c] {
				return
			}
			noProto[c] = true
			for _, p := range c.patterns {
				if p.isInclude {
					if p.include.syntax == "" || p.include.syntax == syn.scope {
						mark(ss.resolve(p.include))
					}
				}
				for _, r := range p.refs {
					if r.syntax == "" {
						mark(ss.resolve(r))
					}
				}
			}
		}
		mark(proto)
	}
	all := []*sContext{}
	for _, c := range syn.contexts {
		all = append(all, c)
	}
	all = append(all, syn.inline...)
	for _, c := range all {
		if proto != nil && c.metaIncludePrototype && !noProto[c] {
			c.prototype = proto
		}
		for _, p := range c.patterns {
			if p.hasBackrefs {
				c.usesBackrefs = true
			}
		}
	}
	// a context uses backrefs if any pattern (incl. included) references captures from the push
	for _, c := range all {
		var check func(x *sContext, depth int) bool
		check = func(x *sContext, depth int) bool {
			if x == nil || depth > 10 {
				return false
			}
			for _, p := range x.patterns {
				if p.isInclude {
					if check(ss.resolve(p.include), depth+1) {
						return true
					}
				} else if p.hasBackrefs {
					return true
				}
			}
			return false
		}
		c.usesBackrefs = check(c, 0)
	}
}

// ---------- parse state ----------

type sOp struct {
	kind  int // 0 push 1 pop 2 clear 3 restore
	scope Scope
	n     int
}

type stateLevel struct {
	ctx        *sContext
	prototypes []*sContext
	capLine    string
	caps       []int
}

type parseState struct {
	ss         *syntaxSet
	stack      []stateLevel
	firstLine  bool
	protoStart []int
}

func newParseState(ss *syntaxSet, syn *sSyntax) *parseState {
	return &parseState{ss: ss, stack: []stateLevel{{ctx: syn.contexts["main"]}}, firstLine: true}
}

type regMatch struct {
	caps      []int
	ctx       *sContext
	pat       *sPattern
	fromProto bool
	wouldLoop bool
}

type posOp struct {
	pos int
	op  sOp
}

func (ps *parseState) parseLine(line string) []posOp {
	var ops []posOp
	if ps.firstLine {
		cur := ps.stack[len(ps.stack)-1].ctx
		if cur != nil && len(cur.metaContentScope) > 0 {
			ops = append(ops, posOp{0, sOp{kind: 0, scope: cur.metaContentScope[0]}})
		}
		ps.firstLine = false
	}
	start := 0
	cache := map[*sPattern][]int{}
	cacheNone := map[*sPattern]bool{}
	ncp := [2]int{0, 0}
	for iter := 0; iter < 100000; iter++ {
		if !ps.parseNextToken(line, &start, cache, cacheNone, &ncp, &ops) {
			break
		}
	}
	return ops
}

func (ps *parseState) contextPatterns(c *sContext, visit func(ctx *sContext, p *sPattern) bool, depth int) bool {
	if c == nil || depth > 30 {
		return false
	}
	for _, p := range c.patterns {
		if p.isInclude {
			ic := ps.ss.resolve(p.include)
			if ps.contextPatterns(ic, visit, depth+1) {
				return true
			}
			continue
		}
		if visit(c, p) {
			return true
		}
	}
	return false
}

func (ps *parseState) parseNextToken(line string, start *int, cache map[*sPattern][]int, cacheNone map[*sPattern]bool, ncp *[2]int, ops *[]posOp) bool {
	checkPopLoop := ncp[0] == *start && ncp[1] == len(ps.stack)
	for len(ps.protoStart) > 0 && ps.protoStart[len(ps.protoStart)-1] >= len(ps.stack) {
		ps.protoStart = ps.protoStart[:len(ps.protoStart)-1]
	}
	best := ps.findBestMatch(line, *start, cache, cacheNone, checkPopLoop)
	if best == nil {
		return false
	}
	if best.wouldLoop {
		// advance one character
		rest := line[*start:]
		if len(rest) == 0 {
			return false
		}
		idx := 0
		for i := range rest {
			if i > 0 {
				idx = i
				break
			}
		}
		if idx == 0 {
			return false
		}
		*start += idx
		return true
	}
	matchEnd := best.caps[1]
	consuming := matchEnd > *start
	if !consuming && best.pat.op == opPush {
		ncp[0] = matchEnd
		ncp[1] = len(ps.stack) + 1
	}
	*start = matchEnd
	if best.fromProto {
		ps.protoStart = append(ps.protoStart, len(ps.stack))
	}
	levelCtx := ps.stack[len(ps.stack)-1].ctx
	ps.execPattern(line, best, levelCtx, ops)
	return true
}

func (ps *parseState) findBestMatch(line string, start int, cache map[*sPattern][]int, cacheNone map[*sPattern]bool, checkPopLoop bool) *regMatch {
	cur := ps.stack[len(ps.stack)-1]
	type chainItem struct {
		fromProto bool
		ctx       *sContext
		lvl       *stateLevel
	}
	var chain []chainItem
	ps0 := 0
	if len(ps.protoStart) > 0 {
		ps0 = ps.protoStart[len(ps.protoStart)-1]
	}
	for i := ps0; i < len(ps.stack); i++ {
		lvl := &ps.stack[i]
		for _, pc := range lvl.prototypes {
			chain = append(chain, chainItem{true, pc, lvl})
		}
	}
	if cur.ctx != nil && cur.ctx.prototype != nil {
		chain = append(chain, chainItem{false, cur.ctx.prototype, nil})
	}
	curLvl := &ps.stack[len(ps.stack)-1]
	chain = append(chain, chainItem{false, cur.ctx, curLvl})

	minStart := len(line) + 1
	var best *regMatch
	popWouldLoop := false
	for _, ci := range chain {
		done := ps.contextPatterns(ci.ctx, func(pctx *sContext, pat *sPattern) bool {
			var capLine string
			var caps []int
			if ci.lvl != nil {
				capLine, caps = ci.lvl.capLine, ci.lvl.caps
			}
			m := ps.search(line, start, pat, capLine, caps, cache, cacheNone)
			if m == nil {
				return false
			}
			ms, me := m[0], m[1]
			if ms < minStart || (ms == minStart && popWouldLoop) {
				minStart = ms
				consuming := me > start
				popWouldLoop = checkPopLoop && !consuming && pat.op == opPop
				best = &regMatch{caps: m, ctx: pctx, pat: pat, fromProto: ci.fromProto, wouldLoop: popWouldLoop}
				if ms == start && !popWouldLoop {
					return true
				}
			}
			return false
		}, 0)
		if done {
			return best
		}
	}
	return best
}

func regexEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		if strings.ContainsRune(`\.+*?()|[]{}^$#&-~ `, r) {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
	}
	return b.String()
}

var backrefRe = regexp.MustCompile(`\\([0-9]+)`)

func (ps *parseState) search(line string, start int, pat *sPattern, capLine string, caps []int, cache map[*sPattern][]int, cacheNone map[*sPattern]bool) []int {
	if m, ok := cache[pat]; ok {
		if m[0] >= start {
			return m
		}
	} else if cacheNone[pat] {
		return nil
	}
	var m []int
	canCache := true
	if pat.hasBackrefs && caps != nil {
		src := backrefRe.ReplaceAllStringFunc(pat.regexSrc, func(x string) string {
			n, _ := strconv.Atoi(x[1:])
			if 2*n+1 < len(caps) && caps[2*n] >= 0 {
				return regexEscape(capLine[caps[2*n]:caps[2*n+1]])
			}
			return ""
		})
		re, err := CompileRegex(src)
		if err != nil {
			return nil
		}
		m = re.SearchAt(line, start)
		canCache = false
	} else {
		m = pat.regex.SearchAt(line, start)
	}
	if m != nil {
		doesSomething := pat.op != opNone || m[0] != m[1]
		if canCache && doesSomething {
			cache[pat] = m
		}
		if doesSomething {
			return m
		}
	} else if canCache {
		cacheNone[pat] = true
	}
	return nil
}

func (ps *parseState) execPattern(line string, rm *regMatch, levelCtx *sContext, ops *[]posOp) {
	ms, me := rm.caps[0], rm.caps[1]
	pat := rm.pat
	ps.pushMetaOps(true, ms, levelCtx, pat, ops)
	for _, s := range pat.scope {
		*ops = append(*ops, posOp{ms, sOp{kind: 0, scope: s}})
	}
	if len(pat.captures) > 0 {
		type capOp struct {
			pos, sub int
			op       sOp
			order    int
		}
		var list []capOp
		ord := 0
		for _, c := range pat.captures {
			if 2*c.idx+1 >= len(rm.caps) {
				continue
			}
			cs, ce := rm.caps[2*c.idx], rm.caps[2*c.idx+1]
			if cs < 0 || cs == ce {
				continue
			}
			for _, s := range c.scopes {
				list = append(list, capOp{cs, -(ce - cs), sOp{kind: 0, scope: s}, ord})
				ord++
			}
			list = append(list, capOp{ce, -1 << 31, sOp{kind: 1, n: len(c.scopes)}, ord})
			ord++
		}
		sort.SliceStable(list, func(i, j int) bool {
			if list[i].pos != list[j].pos {
				return list[i].pos < list[j].pos
			}
			return list[i].sub < list[j].sub
		})
		for _, x := range list {
			*ops = append(*ops, posOp{x.pos, x.op})
		}
	}
	if len(pat.scope) > 0 {
		*ops = append(*ops, posOp{me, sOp{kind: 1, n: len(pat.scope)}})
	}
	ps.pushMetaOps(false, me, levelCtx, pat, ops)
	ps.performOp(line, rm.caps, pat)
}

func (ps *parseState) pushMetaOps(initial bool, index int, cur *sContext, pat *sPattern, ops *[]posOp) {
	switch pat.op {
	case opPop:
		var v []Scope
		if initial {
			v = cur.metaContentScope
		} else {
			v = cur.metaScope
		}
		if len(v) > 0 {
			*ops = append(*ops, posOp{index, sOp{kind: 1, n: len(v)}})
		}
		if !initial && cur.clearScopes >= 0 {
			*ops = append(*ops, posOp{index, sOp{kind: 3}})
		}
	case opPush, opSet:
		isSet := pat.op == opSet
		if initial {
			if isSet && cur.clearScopes >= 0 {
				*ops = append(*ops, posOp{index, sOp{kind: 3}})
			}
			for _, r := range pat.refs {
				ctx := ps.ss.resolve(r)
				if ctx == nil {
					continue
				}
				if !isSet && ctx.clearScopes >= 0 {
					*ops = append(*ops, posOp{index, sOp{kind: 2, n: ctx.clearScopes}})
				}
				for _, s := range ctx.metaScope {
					*ops = append(*ops, posOp{index, sOp{kind: 0, scope: s}})
				}
			}
		} else {
			repush := isSet && (len(cur.metaScope) > 0 || len(cur.metaContentScope) > 0)
			if !repush {
				for _, r := range pat.refs {
					ctx := ps.ss.resolve(r)
					if ctx == nil {
						continue
					}
					if len(ctx.metaContentScope) > 0 || (ctx.clearScopes >= 0 && isSet) {
						repush = true
					}
				}
			}
			if repush {
				num := 0
				for _, r := range pat.refs {
					if ctx := ps.ss.resolve(r); ctx != nil {
						num += len(ctx.metaScope)
					}
				}
				if isSet {
					num += len(cur.metaContentScope) + len(cur.metaScope)
				}
				if num > 0 {
					*ops = append(*ops, posOp{index, sOp{kind: 1, n: num}})
				}
				for _, r := range pat.refs {
					ctx := ps.ss.resolve(r)
					if ctx == nil {
						continue
					}
					if isSet && ctx.clearScopes >= 0 {
						*ops = append(*ops, posOp{index, sOp{kind: 2, n: ctx.clearScopes}})
					}
					for _, s := range ctx.metaScope {
						*ops = append(*ops, posOp{index, sOp{kind: 0, scope: s}})
					}
					for _, s := range ctx.metaContentScope {
						*ops = append(*ops, posOp{index, sOp{kind: 0, scope: s}})
					}
				}
			}
		}
	}
}

func (ps *parseState) performOp(line string, caps []int, pat *sPattern) {
	var oldProtos []*sContext
	switch pat.op {
	case opPush:
	case opSet:
		if len(ps.stack) > 0 {
			oldProtos = ps.stack[len(ps.stack)-1].prototypes
			ps.stack = ps.stack[:len(ps.stack)-1]
		}
	case opPop:
		if len(ps.stack) > 1 {
			ps.stack = ps.stack[:len(ps.stack)-1]
		}
		return
	default:
		return
	}
	for i, r := range pat.refs {
		var protos []*sContext
		if i == 0 {
			protos = append(protos, oldProtos...)
		}
		if i == len(pat.refs)-1 && pat.withPrototype != nil {
			if wp := ps.ss.resolve(pat.withPrototype); wp != nil {
				protos = append(protos, wp)
			}
		}
		ctx := ps.ss.resolve(r)
		if ctx == nil {
			continue
		}
		lvl := stateLevel{ctx: ctx, prototypes: protos}
		if ctx.usesBackrefs {
			lvl.capLine = line
			lvl.caps = append([]int{}, caps...)
		}
		ps.stack = append(ps.stack, lvl)
	}
}
EOF
go vet ./... 2>&1 | head"}

actions.command:
cd /workspace; cat > syntax.go <<'EOF'
package main

import (
	"embed"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
)

//go:embed assets/syntax/basic/*.sublime-syntax assets/syntax/large/*.sublime-syntax
var syntaxFS embed.FS

type Scope = string

type sOpKind int

const (
	opNone sOpKind = iota
	opPush
	opSet
	opPop
)

type ctxRef struct {
	name   string // context name in syntax
	syntax string // scope of syntax ("" = same)
	inline *sContext
	owner  *sSyntax
	resolved *sContext
}

type sPattern struct {
	isInclude     bool
	include       *ctxRef
	regexSrc      string
	regex         *Regex
	hasBackrefs   bool
	scope         []Scope
	captures      []capScopes
	op            sOpKind
	refs          []*ctxRef
	withPrototype *ctxRef
}

type capScopes struct {
	idx    int
	scopes []Scope
}

type sContext struct {
	name                 string
	metaScope            []Scope
	metaContentScope     []Scope
	metaIncludePrototype bool
	clearScopes          int // -1 none, 0 all, n top n
	patterns             []*sPattern
	prototype            *sContext
	usesBackrefs         bool
	syntax               *sSyntax
	isPrototype          bool
}

type sSyntax struct {
	name      string
	scope     string
	variables map[string]string
	contexts  map[string]*sContext
	inline    []*sContext
	protoName bool
}

type syntaxSet struct {
	byScope map[string]*sSyntax
	byName  map[string]*sSyntax
}

var (
	synSetOnce sync.Once
	synSet     *syntaxSet
)

func loadSyntaxSet() *syntaxSet {
	synSetOnce.Do(func() {
		ss := &syntaxSet{byScope: map[string]*sSyntax{}, byName: map[string]*sSyntax{}}
		files := []string{"assets/syntax/basic/json.sublime-syntax", "assets/syntax/large/css.sublime-syntax", "assets/syntax/large/html.sublime-syntax", "assets/syntax/large/js.sublime-syntax", "assets/syntax/large/xml.sublime-syntax"}
		names := []string{"json", "css", "html", "js", "xml"}
		for i, f := range files {
			data, err := syntaxFS.ReadFile(f)
			if err != nil {
				continue
			}
			syn := parseSublimeSyntax(string(data))
			if syn == nil {
				continue
			}
			ss.byScope[syn.scope] = syn
			ss.byName[names[i]] = syn
		}
		hs := httpSyntax()
		ss.byScope[hs.scope] = hs
		ss.byName["http"] = hs
		// link
		for _, syn := range ss.byScope {
			ss.link(syn)
		}
		synSet = ss
	})
	return synSet
}

var varRe = regexp.MustCompile(`\{\{([A-Za-z0-9_]+)\}\}`)

func (s *sSyntax) resolveVars(src string) string {
	for depth := 0; depth < 20 && strings.Contains(src, "{{"); depth++ {
		nsrc := varRe.ReplaceAllStringFunc(src, func(m string) string {
			name := m[2 : len(m)-2]
			if v, ok := s.variables[name]; ok {
				return v
			}
			return m
		})
		if nsrc == src {
			break
		}
		src = nsrc
	}
	return src
}

func splitScopes(s string) []Scope {
	return strings.Fields(s)
}

func parseSublimeSyntax(src string) *sSyntax {
	root, err := parseYAML(src)
	if err != nil || root == nil {
		return nil
	}
	syn := &sSyntax{contexts: map[string]*sContext{}, variables: map[string]string{}}
	if n := root.get("name"); n != nil {
		syn.name = n.str
	}
	if n := root.get("scope"); n != nil {
		syn.scope = n.str
	}
	if v := root.get("variables"); v != nil {
		for _, k := range v.keys {
			syn.variables[k] = v.m[k].str
		}
	}
	ctxs := root.get("contexts")
	if ctxs == nil {
		return nil
	}
	for _, name := range ctxs.keys {
		c := syn.parseContext(ctxs.m[name], name == "prototype")
		c.name = name
		if name == "prototype" {
			c.isPrototype = true
		}
		syn.contexts[name] = c
	}
	if m, ok := syn.contexts["main"]; ok {
		m.metaContentScope = append([]Scope{syn.scope}, m.metaContentScope...)
	}
	return syn
}

func (s *sSyntax) parseContext(n *yNode, inProto bool) *sContext {
	c := &sContext{metaIncludePrototype: !inProto, clearScopes: -1, syntax: s}
	if n == nil || n.kind != 2 {
		return c
	}
	for _, item := range n.seq {
		if item.kind != 1 {
			continue
		}
		if v := item.get("meta_scope"); v != nil {
			c.metaScope = splitScopes(v.str)
			continue
		}
		if v := item.get("meta_content_scope"); v != nil {
			c.metaContentScope = splitScopes(v.str)
			continue
		}
		if v := item.get("meta_include_prototype"); v != nil {
			c.metaIncludePrototype = v.str == "true"
			continue
		}
		if v := item.get("clear_scopes"); v != nil {
			if v.str == "true" {
				c.clearScopes = 0
			} else if n, err := strconv.Atoi(v.str); err == nil {
				c.clearScopes = n
			}
			continue
		}
		if v := item.get("include"); v != nil {
			c.patterns = append(c.patterns, &sPattern{isInclude: true, include: s.parseRef(v, inProto)})
			continue
		}
		if v := item.get("match"); v != nil {
			c.patterns = append(c.patterns, s.parseMatch(item, inProto))
		}
	}
	return c
}

func (s *sSyntax) parseRef(v *yNode, inProto bool) *ctxRef {
	if v.kind == 2 {
		ic := s.parseContext(v, inProto)
		s.inline = append(s.inline, ic)
		return &ctxRef{inline: ic, owner: s}
	}
	str := v.str
	if strings.HasPrefix(str, "scope:") {
		rest := str[len("scope:"):]
		name := "main"
		if i := strings.Index(rest, "#"); i >= 0 {
			name = rest[i+1:]
			rest = rest[:i]
		}
		return &ctxRef{syntax: rest, name: name, owner: s}
	}
	return &ctxRef{name: str, owner: s}
}

func (s *sSyntax) parseRefs(v *yNode, inProto bool) []*ctxRef {
	if v.kind == 2 && len(v.seq) > 0 && v.seq[0].kind == 0 {
		var out []*ctxRef
		for _, x := range v.seq {
			out = append(out, s.parseRef(x, inProto))
		}
		return out
	}
	return []*ctxRef{s.parseRef(v, inProto)}
}

func (s *sSyntax) parseMatch(item *yNode, inProto bool) *sPattern {
	p := &sPattern{}
	src := s.resolveVars(item.get("match").str)
	p.regexSrc = src
	re, err := CompileRegex(src)
	if err != nil {
		re, _ = CompileRegex(`(?!)`)
	}
	p.regex = re
	p.hasBackrefs = re.hasBack
	if v := item.get("scope"); v != nil {
		p.scope = splitScopes(v.str)
	}
	if v := item.get("captures"); v != nil && v.kind == 1 {
		for _, k := range v.keys {
			idx, err := strconv.Atoi(k)
			if err != nil {
				continue
			}
			p.captures = append(p.captures, capScopes{idx: idx, scopes: splitScopes(v.m[k].str)})
		}
		sort.SliceStable(p.captures, func(i, j int) bool { return p.captures[i].idx < p.captures[j].idx })
	}
	if v := item.get("push"); v != nil {
		p.op = opPush
		p.refs = s.parseRefs(v, inProto)
	} else if v := item.get("set"); v != nil {
		p.op = opSet
		p.refs = s.parseRefs(v, inProto)
	} else if v := item.get("pop"); v != nil && v.str == "true" {
		p.op = opPop
	} else if v := item.get("embed"); v != nil {
		p.op = opPush
		esc := &sContext{metaIncludePrototype: false, clearScopes: -1, syntax: s}
		if es := item.get("embed_scope"); es != nil {
			esc.metaContentScope = splitScopes(es.str)
		}
		if ev := item.get("escape"); ev != nil {
			ep := &sPattern{op: opPop}
			esrc := s.resolveVars(ev.str)
			ep.regexSrc = esrc
			ep.regex, _ = CompileRegex(esrc)
			if ep.regex == nil {
				ep.regex, _ = CompileRegex(`(?!)`)
			}
			ep.hasBackrefs = ep.regex.hasBack
			if ec := item.get("escape_captures"); ec != nil && ec.kind == 1 {
				for _, k := range ec.keys {
					idx, err := strconv.Atoi(k)
					if err == nil {
						ep.captures = append(ep.captures, capScopes{idx: idx, scopes: splitScopes(ec.m[k].str)})
					}
				}
			}
			esc.patterns = append(esc.patterns, ep)
		}
		s.inline = append(s.inline, esc)
		escRef := &ctxRef{inline: esc, owner: s}
		p.refs = []*ctxRef{escRef, s.parseRef(v, inProto)}
		p.withPrototype = escRef
	}
	if v := item.get("with_prototype"); v != nil {
		p.withPrototype = s.parseRef(v, true)
	}
	return p
}

func (ss *syntaxSet) resolve(r *ctxRef) *sContext {
	if r.resolved != nil {
		return r.resolved
	}
	if r.inline != nil {
		r.resolved = r.inline
		return r.inline
	}
	syn := r.owner
	if r.syntax != "" {
		syn = ss.byScope[r.syntax]
	}
	if syn == nil {
		return nil
	}
	name := r.name
	if name == "$self" || name == "$top_level_main" {
		name = "main"
	}
	c := syn.contexts[name]
	r.resolved = c
	return c
}

func (ss *syntaxSet) link(syn *sSyntax) {
	proto := syn.contexts["prototype"]
	// contexts reachable from prototype do not get the prototype
	noProto := map[*sContext]bool{}
	if proto != nil {
		var mark func(c *sContext)
		mark = func(c *sContext) {
			if c == nil || noProto[c] {
				return
			}
			noProto[c] = true
			for _, p := range c.patterns {
				if p.isInclude {
					if p.include.syntax == "" || p.include.syntax == syn.scope {
						mark(ss.resolve(p.include))
					}
				}
				for _, r := range p.refs {
					if r.syntax == "" {
						mark(ss.resolve(r))
					}
				}
			}
		}
		mark(proto)
	}
	all := []*sContext{}
	for _, c := range syn.contexts {
		all = append(all, c)
	}
	all = append(all, syn.inline...)
	for _, c := range all {
		if proto != nil && c.metaIncludePrototype && !noProto[c] {
			c.prototype = proto
		}
		for _, p := range c.patterns {
			if p.hasBackrefs {
				c.usesBackrefs = true
			}
		}
	}
	// a context uses backrefs if any pattern (incl. included) references captures from the push
	for _, c := range all {
		var check func(x *sContext, depth int) bool
		check = func(x *sContext, depth int) bool {
			if x == nil || depth > 10 {
				return false
			}
			for _, p := range x.patterns {
				if p.isInclude {
					if check(ss.resolve(p.include), depth+1) {
						return true
					}
				} else if p.hasBackrefs {
					return true
				}
			}
			return false
		}
		c.usesBackrefs = check(c, 0)
	}
}

// ---------- parse state ----------

type sOp struct {
	kind  int // 0 push 1 pop 2 clear 3 restore
	scope Scope
	n     int
}

type stateLevel struct {
	ctx        *sContext
	prototypes []*sContext
	capLine    string
	caps       []int
}

type parseState struct {
	ss         *syntaxSet
	stack      []stateLevel
	firstLine  bool
	protoStart []int
}

func newParseState(ss *syntaxSet, syn *sSyntax) *parseState {
	return &parseState{ss: ss, stack: []stateLevel{{ctx: syn.contexts["main"]}}, firstLine: true}
}

type regMatch struct {
	caps      []int
	ctx       *sContext
	pat       *sPattern
	fromProto bool
	wouldLoop bool
}

type posOp struct {
	pos int
	op  sOp
}

func (ps *parseState) parseLine(line string) []posOp {
	var ops []posOp
	if ps.firstLine {
		cur := ps.stack[len(ps.stack)-1].ctx
		if cur != nil && len(cur.metaContentScope) > 0 {
			ops = append(ops, posOp{0, sOp{kind: 0, scope: cur.metaContentScope[0]}})
		}
		ps.firstLine = false
	}
	start := 0
	cache := map[*sPattern][]int{}
	cacheNone := map[*sPattern]bool{}
	ncp := [2]int{0, 0}
	for iter := 0; iter < 100000; iter++ {
		if !ps.parseNextToken(line, &start, cache, cacheNone, &ncp, &ops) {
			break
		}
	}
	return ops
}

func (ps *parseState) contextPatterns(c *sContext, visit func(ctx *sContext, p *sPattern) bool, depth int) bool {
	if c == nil || depth > 30 {
		return false
	}
	for _, p := range c.patterns {
		if p.isInclude {
			ic := ps.ss.resolve(p.include)
			if ps.contextPatterns(ic, visit, depth+1) {
				return true
			}
			continue
		}
		if visit(c, p) {
			return true
		}
	}
	return false
}

func (ps *parseState) parseNextToken(line string, start *int, cache map[*sPattern][]int, cacheNone map[*sPattern]bool, ncp *[2]int, ops *[]posOp) bool {
	checkPopLoop := ncp[0] == *start && ncp[1] == len(ps.stack)
	for len(ps.protoStart) > 0 && ps.protoStart[len(ps.protoStart)-1] >= len(ps.stack) {
		ps.protoStart = ps.protoStart[:len(ps.protoStart)-1]
	}
	best := ps.findBestMatch(line, *start, cache, cacheNone, checkPopLoop)
	if best == nil {
		return false
	}
	if best.wouldLoop {
		// advance one character
		rest := line[*start:]
		if len(rest) == 0 {
			return false
		}
		idx := 0
		for i := range rest {
			if i > 0 {
				idx = i
				break
			}
		}
		if idx == 0 {
			return false
		}
		*start += idx
		return true
	}
	matchEnd := best.caps[1]
	consuming := matchEnd > *start
	if !consuming && best.pat.op == opPush {
		ncp[0] = matchEnd
		ncp[1] = len(ps.stack) + 1
	}
	*start = matchEnd
	if best.fromProto {
		ps.protoStart = append(ps.protoStart, len(ps.stack))
	}
	levelCtx := ps.stack[len(ps.stack)-1].ctx
	ps.execPattern(line, best, levelCtx, ops)
	return true
}

func (ps *parseState) findBestMatch(line string, start int, cache map[*sPattern][]int, cacheNone map[*sPattern]bool, checkPopLoop bool) *regMatch {
	cur := ps.stack[len(ps.stack)-1]
	type chainItem struct {
		fromProto bool
		ctx       *sContext
		lvl       *stateLevel
	}
	var chain []chainItem
	ps0 := 0
	if len(ps.protoStart) > 0 {
		ps0 = ps.protoStart[len(ps.protoStart)-1]
	}
	for i := ps0; i < len(ps.stack); i++ {
		lvl := &ps.stack[i]
		for _, pc := range lvl.prototypes {
			chain = append(chain, chainItem{true, pc, lvl})
		}
	}
	if cur.ctx != nil && cur.ctx.prototype != nil {
		chain = append(chain, chainItem{false, cur.ctx.prototype, nil})
	}
	curLvl := &ps.stack[len(ps.stack)-1]
	chain = append(chain, chainItem{false, cur.ctx, curLvl})

	minStart := len(line) + 1
	var best *regMatch
	popWouldLoop := false
	for _, ci := range chain {
		done := ps.contextPatterns(ci.ctx, func(pctx *sContext, pat *sPattern) bool {
			var capLine string
			var caps []int
			if ci.lvl != nil {
				capLine, caps = ci.lvl.capLine, ci.lvl.caps
			}
			m := ps.search(line, start, pat, capLine, caps, cache, cacheNone)
			if m == nil {
				return false
			}
			ms, me := m[0], m[1]
			if ms < minStart || (ms == minStart && popWouldLoop) {
				minStart = ms
				consuming := me > start
				popWouldLoop = checkPopLoop && !consuming && pat.op == opPop
				best = &regMatch{caps: m, ctx: pctx, pat: pat, fromProto: ci.fromProto, wouldLoop: popWouldLoop}
				if ms == start && !popWouldLoop {
					return true
				}
			}
			return false
		}, 0)
		if done {
			return best
		}
	}
	return best
}

func regexEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		if strings.ContainsRune(`\.+*?()|[]{}^$#&-~ `, r) {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
	}
	return b.String()
}

var backrefRe = regexp.MustCompile(`\\([0-9]+)`)

func (ps *parseState) search(line string, start int, pat *sPattern, capLine string, caps []int, cache map[*sPattern][]int, cacheNone map[*sPattern]bool) []int {
	if m, ok := cache[pat]; ok {
		if m[0] >= start {
			return m
		}
	} else if cacheNone[pat] {
		return nil
	}
	var m []int
	canCache := true
	if pat.hasBackrefs && caps != nil {
		src := backrefRe.ReplaceAllStringFunc(pat.regexSrc, func(x string) string {
			n, _ := strconv.Atoi(x[1:])
			if 2*n+1 < len(caps) && caps[2*n] >= 0 {
				return regexEscape(capLine[caps[2*n]:caps[2*n+1]])
			}
			return ""
		})
		re, err := CompileRegex(src)
		if err != nil {
			return nil
		}
		m = re.SearchAt(line, start)
		canCache = false
	} else {
		m = pat.regex.SearchAt(line, start)
	}
	if m != nil {
		doesSomething := pat.op != opNone || m[0] != m[1]
		if canCache && doesSomething {
			cache[pat] = m
		}
		if doesSomething {
			return m
		}
	} else if canCache {
		cacheNone[pat] = true
	}
	return nil
}

func (ps *parseState) execPattern(line string, rm *regMatch, levelCtx *sContext, ops *[]posOp) {
	ms, me := rm.caps[0], rm.caps[1]
	pat := rm.pat
	ps.pushMetaOps(true, ms, levelCtx, pat, ops)
	for _, s := range pat.scope {
		*ops = append(*ops, posOp{ms, sOp{kind: 0, scope: s}})
	}
	if len(pat.captures) > 0 {
		type capOp struct {
			pos, sub int
			op       sOp
			order    int
		}
		var list []capOp
		ord := 0
		for _, c := range pat.captures {
			if 2*c.idx+1 >= len(rm.caps) {
				continue
			}
			cs, ce := rm.caps[2*c.idx], rm.caps[2*c.idx+1]
			if cs < 0 || cs == ce {
				continue
			}
			for _, s := range c.scopes {
				list = append(list, capOp{cs, -(ce - cs), sOp{kind: 0, scope: s}, ord})
				ord++
			}
			list = append(list, capOp{ce, -1 << 31, sOp{kind: 1, n: len(c.scopes)}, ord})
			ord++
		}
		sort.SliceStable(list, func(i, j int) bool {
			if list[i].pos != list[j].pos {
				return list[i].pos < list[j].pos
			}
			return list[i].sub < list[j].sub
		})
		for _, x := range list {
			*ops = append(*ops, posOp{x.pos, x.op})
		}
	}
	if len(pat.scope) > 0 {
		*ops = append(*ops, posOp{me, sOp{kind: 1, n: len(pat.scope)}})
	}
	ps.pushMetaOps(false, me, levelCtx, pat, ops)
	ps.performOp(line, rm.caps, pat)
}

func (ps *parseState) pushMetaOps(initial bool, index int, cur *sContext, pat *sPattern, ops *[]posOp) {
	switch pat.op {
	case opPop:
		var v []Scope
		if initial {
			v = cur.metaContentScope
		} else {
			v = cur.metaScope
		}
		if len(v) > 0 {
			*ops = append(*ops, posOp{index, sOp{kind: 1, n: len(v)}})
		}
		if !initial && cur.clearScopes >= 0 {
			*ops = append(*ops, posOp{index, sOp{kind: 3}})
		}
	case opPush, opSet:
		isSet := pat.op == opSet
		if initial {
			if isSet && cur.clearScopes >= 0 {
				*ops = append(*ops, posOp{index, sOp{kind: 3}})
			}
			for _, r := range pat.refs {
				ctx := ps.ss.resolve(r)
				if ctx == nil {
					continue
				}
				if !isSet && ctx.clearScopes >= 0 {
					*ops = append(*ops, posOp{index, sOp{kind: 2, n: ctx.clearScopes}})
				}
				for _, s := range ctx.metaScope {
					*ops = append(*ops, posOp{index, sOp{kind: 0, scope: s}})
				}
			}
		} else {
			repush := isSet && (len(cur.metaScope) > 0 || len(cur.metaContentScope) > 0)
			if !repush {
				for _, r := range pat.refs {
					ctx := ps.ss.resolve(r)
					if ctx == nil {
						continue
					}
					if len(ctx.metaContentScope) > 0 || (ctx.clearScopes >= 0 && isSet) {
						repush = true
					}
				}
			}
			if repush {
				num := 0
				for _, r := range pat.refs {
					if ctx := ps.ss.resolve(r); ctx != nil {
						num += len(ctx.metaScope)
					}
				}
				if isSet {
					num += len(cur.metaContentScope) + len(cur.metaScope)
				}
				if num > 0 {
					*ops = append(*ops, posOp{index, sOp{kind: 1, n: num}})
				}
				for _, r := range pat.refs {
					ctx := ps.ss.resolve(r)
					if ctx == nil {
						continue
					}
					if isSet && ctx.clearScopes >= 0 {
						*ops = append(*ops, posOp{index, sOp{kind: 2, n: ctx.clearScopes}})
					}
					for _, s := range ctx.metaScope {
						*ops = append(*ops, posOp{index, sOp{kind: 0, scope: s}})
					}
					for _, s := range ctx.metaContentScope {
						*ops = append(*ops, posOp{index, sOp{kind: 0, scope: s}})
					}
				}
			}
		}
	}
}

func (ps *parseState) performOp(line string, caps []int, pat *sPattern) {
	var oldProtos []*sContext
	switch pat.op {
	case opPush:
	case opSet:
		if len(ps.stack) > 0 {
			oldProtos = ps.stack[len(ps.stack)-1].prototypes
			ps.stack = ps.stack[:len(ps.stack)-1]
		}
	case opPop:
		if len(ps.stack) > 1 {
			ps.stack = ps.stack[:len(ps.stack)-1]
		}
		return
	default:
		return
	}
	for i, r := range pat.refs {
		var protos []*sContext
		if i == 0 {
			protos = append(protos, oldProtos...)
		}
		if i == len(pat.refs)-1 && pat.withPrototype != nil {
			if wp := ps.ss.resolve(pat.withPrototype); wp != nil {
				protos = append(protos, wp)
			}
		}
		ctx := ps.ss.resolve(r)
		if ctx == nil {
			continue
		}
		lvl := stateLevel{ctx: ctx, prototypes: protos}
		if ctx.usesBackrefs {
			lvl.capLine = line
			lvl.caps = append([]int{}, caps...)
		}
		ps.stack = append(ps.stack, lvl)
	}
}
