func scopeLen(s Scope) int { return strings.Count(s, ".") + 1 }

func scopeIsPrefixOf(sel, s Scope) bool {
	if !strings.HasPrefix(s, sel) {
		return false
	}
	return len(s) == len(sel) || s[len(sel)] == '.'
}

func (sel tSelector) matchPower(stack []Scope) (float64, bool) {
	si := 0
	score := 0.0
	for i, s := range stack {
		if scopeIsPrefixOf(sel.path[si], s) {
			score += float64(scopeLen(sel.path[si])) * math.Exp2(float64(3*i))
			si++
			if si >= len(sel.path) {
				return score, true
			}
		}
	}
	return 0, false
}

type scoredStyle struct {
	fgScore float64
	fg      tColor
	fsScore float64
	fs      int
}

func (s *scoredStyle) apply(m tStyleMod, score float64) {
	if score > s.fgScore && m.fg != nil {
		s.fgScore = score
