func (h *highlighterState) pop() {
	if len(h.path) > 0 {
		h.path = h.path[:len(h.path)-1]
		h.styles = h.styles[:len(h.styles)-1]
		h.caches = h.caches[:len(h.caches)-1]
	}
}

func (h *highlighterState) applyOp(op sOp) {
	switch op.kind {
	case 0:
		h.push(op.scope)
	case 1:
		for i := 0; i < op.n; i++ {
			h.pop()
		}
	case 2:
		n := op.n
		if n == 0 || n > len(h.path) {
			n = len(h.path)
		}
		cleared := append([]Scope{}, h.path[len(h.path)-n:]...)
		h.clear = append(h.clear, cleared)
		for i := 0; i < n; i++ {
			h.pop()
		}
	case 3:
		if len(h.clear) > 0 {
			c := h.clear[len(h.clear)-1]
			h.clear = h.clear[:len(h.clear)-1]
			for _, s := range c {
				h.push(s)
			}
		}
	}
}

func (h *highlighterState) current() hlStyle {
	if len(h.styles) == 0 {
		return h.defaultStyle()
	}
	return h.styles[len(h.styles)-1]
}

func styleEscape(st hlStyle) string {
	var b strings.Builder
	b.WriteString("\x1b[0m")
	if st.fs&2 != 0 {
		b.WriteString("\x1b[4m")
	}
	if st.fs&1 != 0 {
		b.WriteString("\x1b[1m")
	}
	if st.fs&4 != 0 {
		b.WriteString("\x1b[3m")
	}
	c := st.fg
	if c.set {
		if c.a == 0 {
			switch {
			case c.r < 7:
				b.WriteString("\x1b[3" + strconv.Itoa(int(c.r)) + "m")
			case c.r == 7:
			default:
				b.WriteString("\x1b[38;5;" + strconv.Itoa(int(c.r)) + "m")
			}
		} else {
			b.WriteString("\x1b[38;2;" + strconv.Itoa(int(c.r)) + ";" + strconv.Itoa(int(c.g)) + ";" + strconv.Itoa(int(c.b)) + "m")
		}
	}
	return b.String()
}

func highlight(text, syntaxName, themeName string) string {
	ss := loadSyntaxSet()
	syn := ss.byName[syntaxName]
	theme := loadTheme(themeName)
	var b strings.Builder
	if syn == nil {
		b.WriteString(styleEscape(hlStyle{fg: theme.fg}))
		b.WriteString(text)
		b.WriteString("\x1b[0m")
		return b.String()
	}
	ps := newParseState(ss, syn)
	hs := &highlighterState{theme: theme}
	for _, line := range splitInclusive(text, '\n') {
		ops := ps.parseLine(line)
		pos := 0
		for i := 0; i <= len(ops); i++ {
			end := len(line)
			if i < len(ops) {
				end = ops[i].pos
			}
			if end > len(line) {
				end = len(line)
			}
			if end > pos {
				st := hs.current()
				b.WriteString(styleEscape(st))
				b.WriteString(line[pos:end])
				pos = end
			}
			if i < len(ops) {
				hs.applyOp(ops[i].op)
			}
		}
	}
	b.WriteString("\x1b[0m")
	return b.String()
}
