package main

import (
	"strings"
	"unicode/utf8"
)

type hsegKind int

const (
	hsDefault hsegKind = iota
	hsMethod
	hsURL
	hsHTTP
	hsSlash
	hsVersion
	hsStatus
	hsReason
	hsName
	hsColon
	hsValue
	hsError
)

type hseg struct {
	kind hsegKind
	text string
}

var hsegScopes = map[hsegKind][]Scope{
	hsDefault: {"source.http"},
	hsMethod:  {"source.http", "keyword.control.http"},
	hsURL:     {"source.http", "const.language.http"},
	hsHTTP:    {"source.http", "keyword.other.http"},
	hsSlash:   {"source.http", "punctuation.separator.http"},
	hsVersion: {"source.http", "constant.numeric.http"},
	hsStatus:  {"source.http", "constant.numeric.http"},
	hsReason:  {"source.http", "keyword.reason.http"},
	hsName:    {"source.http", "http.requestheaders", "support.variable.http"},
	hsColon:   {"source.http", "http.requestheaders", "punctuation.separator.http"},
	hsValue:   {"source.http", "http.requestheaders", "string.other.http"},
	hsError:   {"source.http", "error"},
}

func styleForScopes(theme *Theme, scopes []Scope) hlStyle {
	hs := &highlighterState{theme: theme}
	for _, s := range scopes {
		hs.push(s)
	}
	return hs.current()
}

func versionSegs(v string) []hseg {
	// v like "HTTP/1.1"
	if strings.HasPrefix(v, "HTTP/") {
		return []hseg{{hsHTTP, "HTTP"}, {hsSlash, "/"}, {hsVersion, v[5:]}}
	}
	return []hseg{{hsDefault, v}}
}

func requestLineSegs(method, target, version string) []hseg {
	segs := []hseg{{hsMethod, method}, {hsDefault, " "}, {hsURL, target}, {hsDefault, " "}}
	segs = append(segs, versionSegs(version)...)
	return append(segs, hseg{hsDefault, "\n"})
}

func statusLineSegs(version string, code int, reason string) []hseg {
	segs := versionSegs(version)
	segs = append(segs, hseg{hsDefault, " "}, hseg{hsStatus, itoa(code)}, hseg{hsDefault, " "}, hseg{hsReason, reason}, hseg{hsDefault, "\n"})
	return segs
}

func headerSegs(name, value string) []hseg {
	segs := []hseg{{hsName, name}, {hsColon, ":"}, {hsDefault, " "}}
	ascii := true
	for i := 0; i < len(value); i++ {
		if value[i] >= 0x80 {
			ascii = false
			break
		}
	}
	if ascii {
		segs = append(segs, hseg{hsValue, value})
	} else {
		var b strings.Builder
		for i := 0; i < len(value); i++ {
			b.WriteRune(rune(value[i]))
		}
		segs = append(segs, hseg{hsError, b.String()})
		if utf8.ValidString(value) {
			segs = append(segs, hseg{hsDefault, " (UTF-8: "}, hseg{hsValue, value}, hseg{hsDefault, ")"})
		}
	}
	return append(segs, hseg{hsDefault, "\n"})
}

func renderSegs(segs []hseg, color bool, themeName string) string {
	var b strings.Builder
	if !color {
		for _, s := range segs {
			b.WriteString(s.text)
		}
		return b.String()
	}
	theme := loadTheme(themeName)
	cache := map[hsegKind]string{}
	for _, s := range segs {
		esc, ok := cache[s.kind]
		if !ok {
			esc = styleEscape(styleForScopes(theme, hsegScopes[s.kind]))
			cache[s.kind] = esc
		}
		b.WriteString(esc)
		b.WriteString(s.text)
	}
	b.WriteString("\x1b[0m")
	return b.String()
}
