func (s *sessionFile) parse(data []byte, u *URL, jar *cookieJar) error {
	p := &jsonParser{s: data}
	v, jerr := p.parseValue()
	if jerr != nil {
		return jerr
	}
	if _, ok := p.parseWhitespace(); ok {
		return p.peekErr("trailing characters")
	}
	l, col := p.positionOf(len(data))
	_ = l
	if v.Kind != JObject {
		return &JSONError{Msg: "invalid type: " + jsonUnexpected(v) + ", expected struct Content", Line: 1, Column: col}
	}
	// position for missing-field errors: end of top-level object
	endLine, endCol := posAfterValue(data)
	for _, f := range []string{"__meta__", "auth", "cookies", "headers"} {
		if v.Get(f) == nil {
			return &JSONError{Msg: "missing field `" + f + "`", Line: endLine, Column: endCol}
		}
	}
	if a := v.Get("auth"); a != nil && a.Kind == JObject {
		if t := a.Get("type"); t != nil && t.Kind == JString {
			x := t.Str
			s.authType = &x
		}
		if t := a.Get("raw_auth"); t != nil && t.Kind == JString {
			x := t.Str
			s.rawAuth = &x
		}
	}
	now := nowUnix()
	addCookie := func(name string, cv *JValue) {
		if cv == nil || cv.Kind != JObject {
			return
		}
		ck := &cookie{name: name}
		if x := cv.Get("value"); x != nil && x.Kind == JString {
			ck.value = x.Str
		}
		if x := cv.Get("expires"); x != nil && x.Kind == JNumber {
			var ts int64
			switch x.NK {
			case NumU64:
				ts = int64(x.U)
			case NumI64:
				ts = x.I
			default:
				ts = int64(x.F)
			}
			if ts <= now {
				return
			}
			ck.expires = &ts
		}
		ck.path = "/"
		if x := cv.Get("path"); x != nil && x.Kind == JString {
			ck.path = x.Str
		}
		if x := cv.Get("secure"); x != nil && x.Kind == JBool {
			b := x.Bool
			ck.secure = &b
		}
		ck.domain = u.Host
		ck.hostOnly = true
		if x := cv.Get("domain"); x != nil && x.Kind == JString && x.Str != "" {
			ck.domain = strings.TrimPrefix(x.Str, ".")
			ck.hostOnly = ck.domain == u.Host
		}
		jar.insert(ck)
	}
	switch cs := v.Get("cookies"); cs.Kind {
	case JArray:
		for _, cv := range cs.Arr {
			if n := cv.Get("name"); n != nil && n.Kind == JString {
				addCookie(n.Str, cv)
			}
		}
	case JObject:
		for _, k := range cs.Keys {
			addCookie(k, cs.Vals[k])
		}
	}
	switch hs := v.Get("headers"); hs.Kind {
	case JArray:
		for _, hv := range hs.Arr {
			n, val := hv.Get("name"), hv.Get("value")
			if n != nil && val != nil && n.Kind == JString && val.Kind == JString {
				s.headers.Append(strings.ToLower(n.Str), val.Str)
			}
		}
	case JObject:
		for _, k := range hs.Keys {
			if val := hs.Vals[k]; val.Kind == JString {
				s.headers.Append(strings.ToLower(k), val.Str)
			}
		}
	}
