func jsonUnexpected(v *JValue) string {
	switch v.Kind {
	case JNull:
		return "null"
	case JBool:
		if v.Bool {
			return "boolean `true`"
		}
		return "boolean `false`"
	case JNumber:
		switch v.NK {
		case NumU64:
			return "integer `" + strconv.FormatUint(v.U, 10) + "`"
		case NumI64:
			return "integer `" + strconv.FormatInt(v.I, 10) + "`"
		}
		return "floating point `" + ryuFormat(v.F) + "`"
	case JString:
		return "string " + rustDebugStr(v.Str)
	case JArray:
		return "sequence"
	}
	return "map"
