package main

import (
	"net"
	"strconv"
	"strings"
	"time"
)

type cookie struct {
	name, value string
	domain      string
	hostOnly    bool
	path        string
	secure      *bool
	expires     *int64 // from Expires attribute or session file
	expiresAt   *time.Time
}

type pathGroup struct {
	path    string
	cookies []*cookie
}

type domainGroup struct {
	domain string
	paths  []*pathGroup
}

type cookieJar struct {
	domains []*domainGroup
	session *sessionFile
	c       *Cli
}

func (j *cookieJar) insert(ck *cookie) {
	var dg *domainGroup
	for _, d := range j.domains {
		if d.domain == ck.domain {
			dg = d
		}
	}
	if dg == nil {
		dg = &domainGroup{domain: ck.domain}
		j.domains = append(j.domains, dg)
	}
	var pg *pathGroup
	for _, p := range dg.paths {
		if p.path == ck.path {
			pg = p
		}
	}
	if pg == nil {
		pg = &pathGroup{path: ck.path}
		dg.paths = append(dg.paths, pg)
	}
	for i, x := range pg.cookies {
		if x.name == ck.name {
			pg.cookies[i] = ck
			return
		}
	}
	pg.cookies = append(pg.cookies, ck)
}

func (j *cookieJar) remove(domain, path, name string) {
	for _, d := range j.domains {
		if d.domain != domain {
			continue
		}
		for _, p := range d.paths {
			if p.path != path {
				continue
			}
			for i, x := range p.cookies {
				if x.name == name {
					p.cookies = append(p.cookies[:i], p.cookies[i+1:]...)
					return
				}
			}
		}
	}
}

func (ck *cookie) expired(now time.Time) bool {
	if ck.expiresAt != nil && !ck.expiresAt.After(now) {
		return true
	}
	return false
}

func (j *cookieJar) all() []*cookie {
	var out []*cookie
	now := time.Now()
	for _, d := range j.domains {
		for _, p := range d.paths {
			for _, c := range p.cookies {
				if !c.expired(now) {
					out = append(out, c)
				}
			}
		}
	}
	return out
}

func defaultCookiePath(u *URL) string {
	p := u.PathString()
	if p == "" || p[0] != '/' {
		return "/"
	}
	i := strings.LastIndex(p, "/")
	if i <= 0 {
		return "/"
	}
	return p[:i]
}

func pathMatch(reqPath, cookiePath string) bool {
	if reqPath == "" {
		reqPath = "/"
	}
	if reqPath == cookiePath {
		return true
	}
	if strings.HasPrefix(reqPath, cookiePath) {
		if strings.HasSuffix(cookiePath, "/") {
			return true
		}
		if len(reqPath) > len(cookiePath) && reqPath[len(cookiePath)] == '/' {
			return true
		}
	}
	return false
}

func domainMatch(host, domain string) bool {
	if host == domain {
		return true
	}
	if net.ParseIP(strings.Trim(host, "[]")) != nil {
		return false
	}
	return strings.HasSuffix(host, "."+domain)
}

func isLocalhost(host string) bool {
	h := strings.Trim(host, "[]")
	if h == "localhost" || strings.HasSuffix(h, ".localhost") {
		return true
	}
	if ip := net.ParseIP(h); ip != nil {
		return ip.IsLoopback()
	}
	return false
}

func (j *cookieJar) matching(u *URL) []*cookie {
	var out []*cookie
	host := u.Host
	for _, c := range j.all() {
		if c.hostOnly {
			if host != c.domain {
				continue
			}
		} else if !domainMatch(host, c.domain) {
			continue
		}
		if !pathMatch(u.PathString(), c.path) {
			continue
		}
		if c.secure != nil && *c.secure && u.Scheme != "https" && !isLocalhost(host) {
			continue
		}
		out = append(out, c)
	}
	return out
}

func (j *cookieJar) headerFor(u *URL) string {
	var parts []string
	for _, c := range j.matching(u) {
		parts = append(parts, c.name+"="+c.value)
	}
	return strings.Join(parts, "; ")
}

// apply adds the Cookie header for sending (if no Cookie header is present).
func (j *cookieJar) apply(req *Request) {
	req.cookieHeader = ""
	if req.Headers.Contains("cookie") {
		return
	}
	req.cookieHeader = j.headerFor(req.URL)
}

func parseCookieDate(s string) (time.Time, bool) {
	layouts := []string{time.RFC1123, "Mon, 02-Jan-2006 15:04:05 MST", "Monday, 02-Jan-06 15:04:05 MST", time.ANSIC, "Mon, 02 Jan 2006 15:04:05 -0700", "Mon, 2 Jan 2006 15:04:05 MST", "Mon, 02-Jan-06 15:04:05 MST"}
	for _, l := range layouts {
		if t, err := time.Parse(l, strings.TrimSpace(s)); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

func (j *cookieJar) storeSetCookie(u *URL, raw string) {
	parts := strings.Split(raw, ";")
	nv := strings.TrimSpace(parts[0])
	name, value, ok := strings.Cut(nv, "=")
	if !ok {
		return
	}
	name = strings.TrimSpace(name)
	value = strings.TrimSpace(value)
	if name == "" {
		return
	}
	ck := &cookie{name: name, value: value}
	var maxAge *int64
	var expAttr *time.Time
	domainAttr := ""
	pathAttr := ""
	for _, a := range parts[1:] {
		k, v, _ := strings.Cut(strings.TrimSpace(a), "=")
		k = strings.ToLower(strings.TrimSpace(k))
		v = strings.TrimSpace(v)
		switch k {
		case "path":
			pathAttr = v
		case "domain":
			domainAttr = strings.ToLower(strings.TrimPrefix(v, "."))
		case "max-age":
			if n, err := strconv.ParseInt(v, 10, 64); err == nil {
				maxAge = &n
			}
		case "expires":
			if t, ok := parseCookieDate(v); ok {
				expAttr = &t
			}
		case "secure":
			t := true
			ck.secure = &t
		}
	}
	host := u.Host
	if domainAttr != "" {
		if !domainMatch(host, domainAttr) {
			return
		}
		ck.domain = domainAttr
	} else {
		ck.domain = host
		ck.hostOnly = true
	}
	if pathAttr != "" && strings.HasPrefix(pathAttr, "/") {
		ck.path = pathAttr
	} else {
		ck.path = defaultCookiePath(u)
	}
	now := time.Now()
	if expAttr != nil {
		ts := expAttr.Unix()
		ck.expires = &ts
		t := *expAttr
		ck.expiresAt = &t
	}
	if maxAge != nil {
		t := now.Add(time.Duration(*maxAge) * time.Second)
		if *maxAge <= 0 {
			t = time.Unix(0, 0)
		}
		ck.expiresAt = &t
	}
	if ck.expiresAt != nil && !ck.expiresAt.After(now) {
		j.remove(ck.domain, ck.path, ck.name)
		return
	}
	j.insert(ck)
}

func (j *cookieJar) store(u *URL, resp *Response) {
	for _, sc := range resp.Headers.GetAll("set-cookie") {
		j.storeSetCookie(u, sc)
	}
}

// addCookieHeader parses a "Cookie: a=b; c=d" header value into the jar.
func (j *cookieJar) addRequestCookies(u *URL, v string) {
	for _, part := range strings.Split(v, ";") {
		name, value, ok := strings.Cut(strings.TrimSpace(part), "=")
		if !ok || strings.TrimSpace(name) == "" {
			continue
		}
		j.insert(&cookie{name: strings.TrimSpace(name), value: strings.TrimSpace(value), domain: u.Host, hostOnly: true, path: "/"})
	}
}

func newCookieJar(c *Cli) *cookieJar {
	return &cookieJar{c: c}
}

func (j *cookieJar) save(resp *Response) {}
