	case JArray:
		for _, cv := range cs.Arr {
			if n := cv.Get("name"); n != nil && n.Kind == JString {
				addCookie(n.Str, cv)
			}
		}
	case JObject:
		for _, k := range cs.Keys {
			addCookie(k, cs.Vals[k])
		}
	}
	switch hs := v.Get("headers"); hs.Kind {
	case JArray:
		for _, hv := range hs.Arr {
			n, val := hv.Get("name"), hv.Get("value")
			if n != nil && val != nil && n.Kind == JString && val.Kind == JString {
				s.headers.Append(strings.ToLower(n.Str), val.Str)
			}
		}
	case JObject:
		for _, k := range hs.Keys {
			if val := hs.Vals[k]; val.Kind == JString {
				s.headers.Append(strings.ToLower(k), val.Str)
			}
		}
	}
	return nil
}

func jsonUnexpected(v *JValue) string {
	switch v.Kind {
	case JNull:
		return "null"
	case JBool:
		if v.Bool {
			return "boolean `true`"
		}
		return "boolean `false`"
	case JNumber:
		switch v.NK {
		case NumU64:
			return "integer `" + strconv.FormatUint(v.U, 10) + "`"
		case NumI64:
			return "integer `" + strconv.FormatInt(v.I, 10) + "`"
		}
		return "floating point `" + ryuFormat(v.F) + "`"
	case JString:
		return "string " + rustDebugStr(v.Str)
	case JArray:
		return "sequence"
	}
	return "map"
}

func posAfterValue(data []byte) (int, int) {
	p := &jsonParser{s: data}
	p.ignoreValue()
	return p.positionOf(p.i)
}

func (s *sessionFile) save(jar *cookieJar) error {
	if s == nil || s.readOnly {
		return nil
	}
	var b strings.Builder
	b.WriteString("{\n    \"__meta__\": {\n        \"about\": \"xh session file\",\n        \"xh\": \"" + xhVersion + "\"\n    },\n")
	b.WriteString("    \"auth\": {\n        \"type\": ")
	if s.authType != nil {
		writeJSONString(&b, *s.authType)
	} else {
		b.WriteString("null")
	}
	b.WriteString(",\n        \"raw_auth\": ")
	if s.rawAuth != nil {
		writeJSONString(&b, *s.rawAuth)
	} else {
		b.WriteString("null")
	}
	b.WriteString("\n    },\n")
	cks := jar.all()
	if len(cks) == 0 {
		b.WriteString("    \"cookies\": [],\n")
	} else {
		b.WriteString("    \"cookies\": [\n")
		for i, c := range cks {
			b.WriteString("        {\n            \"name\": ")
			writeJSONString(&b, c.name)
			b.WriteString(",\n            \"value\": ")
			writeJSONString(&b, c.value)
			if c.expires != nil {
				b.WriteString(",\n            \"expires\": " + strconv.FormatInt(*c.expires, 10))
			}
			b.WriteString(",\n            \"path\": ")
			writeJSONString(&b, c.path)
			if c.secure != nil {
				if *c.secure {
					b.WriteString(",\n            \"secure\": true")
				} else {
					b.WriteString(",\n            \"secure\": false")
				}
			}
			b.WriteString(",\n            \"domain\": ")
			writeJSONString(&b, c.domain)
			b.WriteString("\n        }")
			if i < len(cks)-1 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}
		b.WriteString("    ],\n")
	}
	pairs := s.headers.Pairs()
	if len(pairs) == 0 {
		b.WriteString("    \"headers\": []\n")
	} else {
		b.WriteString("    \"headers\": [\n")
		for i, kv := range pairs {
			b.WriteString("        {\n            \"name\": ")
			writeJSONString(&b, kv[0])
			b.WriteString(",\n            \"value\": ")
			writeJSONString(&b, kv[1])
			b.WriteString("\n        }")
			if i < len(pairs)-1 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}
		b.WriteString("    ]\n")
	}
	b.WriteString("}\n")
	if dir := filepath.Dir(s.path); dir != "" {
		os.MkdirAll(dir, 0o755)
	}
	if err := os.WriteFile(s.path, []byte(b.String()), 0o644); err != nil {
		return ioErr(err)
	}
	return nil
}
