package main

import (
	"crypto/md5"
	"crypto/rand"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/hex"
	"errors"
	"hash"
	"os"
	"strings"
)

func parseDigestParams(s string) map[string]string {
	out := map[string]string{}
	i := 0
	for i < len(s) {
		for i < len(s) && (s[i] == ' ' || s[i] == ',' || s[i] == '\t') {
			i++
		}
		start := i
		for i < len(s) && s[i] != '=' && s[i] != ',' {
			i++
		}
		key := strings.ToLower(strings.TrimSpace(s[start:i]))
		if i >= len(s) || s[i] == ',' {
			if key != "" {
				out[key] = ""
			}
			continue
		}
		i++ // '='
		for i < len(s) && s[i] == ' ' {
			i++
		}
		var val strings.Builder
		if i < len(s) && s[i] == '"' {
			i++
			for i < len(s) && s[i] != '"' {
				if s[i] == '\\' && i+1 < len(s) {
					i++
				}
				val.WriteByte(s[i])
				i++
			}
			i++
		} else {
			for i < len(s) && s[i] != ',' {
				val.WriteByte(s[i])
				i++
			}
		}
		out[key] = strings.TrimSpace(val.String())
	}
	return out
}

func digestQuote(s string) string {
	return "\"" + strings.NewReplacer("\\", "\\\\", "\"", "\\\"").Replace(s) + "\""
}

func digestResponse(wa, user, pass string, req *Request) (string, error) {
	body := wa
	if len(body) >= 7 && strings.EqualFold(body[:7], "Digest ") {
		body = body[7:]
	}
	params := parseDigestParams(body)
	realm, ok := params["realm"]
	if !ok {
		return "", errors.New("Missing \"realm\" in header: " + wa)
	}
	nonce, ok := params["nonce"]
	if !ok {
		return "", errors.New("Missing \"nonce\" in header: " + wa)
	}
	algo := "MD5"
	if a, ok := params["algorithm"]; ok && a != "" {
		algo = strings.ToUpper(a)
	}
	var newHash func() hash.Hash
	sess := strings.HasSuffix(algo, "-SESS")
	base := strings.TrimSuffix(algo, "-SESS")
	switch base {
	case "MD5":
		newHash = md5.New
	case "SHA-256":
		newHash = sha256.New
	case "SHA-512-256":
		newHash = sha512.New512_256
	default:
		return "", errors.New("Unknown algorithm: " + algo)
	}
	h := func(s string) string {
		x := newHash()
		x.Write([]byte(s))
		return hex.EncodeToString(x.Sum(nil))
	}
	qop := ""
	if q, ok := params["qop"]; ok {
		var list []string
		for _, x := range strings.Split(q, ",") {
			list = append(list, strings.ToLower(strings.TrimSpace(x)))
		}
		for _, x := range list {
			if x == "auth" {
				qop = "auth"
			}
		}
		if qop == "" {
			for _, x := range list {
				if x == "auth-int" {
					qop = "auth-int"
				}
			}
		}
	}
	cnonce := os.Getenv("XH_TEST_DIGEST_AUTH_CNONCE")
	if _, ok := os.LookupEnv("XH_TEST_DIGEST_AUTH_CNONCE"); !ok {
		var b [16]byte
		rand.Read(b[:])
		cnonce = hex.EncodeToString(b[:])
	}
	uri := req.URL.PathString()
	ha1 := h(user + ":" + realm + ":" + pass)
	if sess {
		ha1 = h(ha1 + ":" + nonce + ":" + cnonce)
	}
	var ha2 string
	if qop == "auth-int" {
		ha2 = h(req.Method + ":" + uri + ":" + h(string(req.Body)))
	} else {
		ha2 = h(req.Method + ":" + uri)
	}
	var resp string
	if qop != "" {
		resp = h(ha1 + ":" + nonce + ":00000001:" + cnonce + ":" + qop + ":" + ha2)
	} else {
		resp = h(ha1 + ":" + nonce + ":" + ha2)
	}
	parts := []string{
		"username=" + digestQuote(user),
		"realm=" + digestQuote(realm),
		"nonce=" + digestQuote(nonce),
		"uri=" + digestQuote(uri),
	}
	if qop != "" {
		parts = append(parts, "qop="+qop, "nc=00000001", "cnonce="+digestQuote(cnonce))
	}
	parts = append(parts, "response="+digestQuote(resp))
	if op, ok := params["opaque"]; ok {
		parts = append(parts, "opaque="+digestQuote(op))
	}
	if qop != "" || base != "MD5" || sess {
		parts = append(parts, "algorithm="+algo)
	}
	return "Digest " + strings.Join(parts, ", "), nil
}
