	if len(b) == 0 {
		return []byte{}, nil
	}
	if len(b) >= 4 {
		magic := uint32(b[0]) | uint32(b[1])<<8 | uint32(b[2])<<16 | uint32(b[3])<<24
		if magic != 0xFD2FB528 && (magic&0xFFFFFFF0) != 0x184D2A50 {
			return nil, &chainErrList{[]string{fmt.Sprintf("BadMagicNumber(%d)", magic), fmt.Sprintf("Read wrong magic number: 0x%x", magic)}}
		}
	}
	var out *C.uint8_t
	var outLen C.size_t
	var msg *C.char
	rc := C.z_decode((*C.uint8_t)(unsafe.Pointer(&b[0])), C.size_t(len(b)), &out, &outLen, &msg)
	var res []byte
	if out != nil {
		res = C.GoBytes(unsafe.Pointer(out), C.int(outLen))
		C.free(unsafe.Pointer(out))
	}
	switch rc {
	case 0:
		return res, nil
	case 1:
		m := "corrupted data"
		if msg != nil {
			m = C.GoString(msg)
		}
		return nil, errors.New(m)
	case 2:
		return res, nil
	}
	return nil, errors.New("zstd decoding unavailable")
}
