		for i := 0; i < depth; i++ {
			b.WriteString(indent)
		}
	}
	for _, c := range s {
		if inString {
			b.WriteByte(c)
			if inBackslash {
				inBackslash = false
			} else if c == '\\' {
				inBackslash = true
			} else if c == '"' {
				inString = false
			}
			continue
		}
		switch c {
		case ' ', '\n', '\r', '\t':
