// firstBytes computes the set of possible first bytes of a match. ok=false if
// the node can match the empty string or the set can't be determined.
func firstBytes(n *reNode) (set [256]bool, ok bool) {
	switch n.kind {
	case rkLit:
		if n.r < 128 {
			set[byte(n.r)] = true
			if n.fold {
				r := n.r
				if r >= 'a' && r <= 'z' {
					set[byte(r-32)] = true
				} else if r >= 'A' && r <= 'Z' {
					set[byte(r+32)] = true
				}
				if r == 'k' || r == 'K' || r == 's' || r == 'S' {
					return set, false
				}
			}
			return set, true
		}
		return set, false
	case rkClass:
		if n.cls.fold {
			return set, false
		}
		for c := 0; c < 128; c++ {
			if n.cls.matches(rune(c)) {
				set[c] = true
			}
		}
		for c := 128; c < 256; c++ {
			set[c] = true
		}
		return set, true
	case rkSeq:
		for _, s := range n.subs {
			switch s.kind {
			case rkBOL, rkWordB, rkNotWordB, rkStartText, rkSearchStart:
				continue
			case rkLookahead:
				continue
			}
			return firstBytes(s)
		}
		return set, false
	case rkAlt:
		for _, a := range n.subs {
			s, ok := firstBytes(a)
			if !ok {
				return set, false
			}
			for i := range s {
				if s[i] {
					set[i] = true
				}
			}
		}
		return set, true
	case rkGroup, rkAtomic:
		return firstBytes(n.sub)
	case rkRepeat:
		if n.min == 0 {
			return set, false
		}
		return firstBytes(n.sub)
	}
	return set, false
}
