package main

import (
	"fmt"
	"os"
	"strings"
	"time"
)

var (
	logStart     = time.Now()
	envLogger    = false
	logDefault   = 2
	logTargets   = map[string]int{}
)

func parseLevel(s string) (int, bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "off":
		return 0, true
	case "error":
		return 1, true
	case "warn":
		return 2, true
	case "info":
		return 3, true
	case "debug":
		return 4, true
	case "trace":
		return 5, true
	}
	return 0, false
}

func setupLogging(debug bool) {
	v, ok := os.LookupEnv("RUST_LOG")
	if !ok && !debug {
		return
	}
	envLogger = true
	logDefault = 1
	if debug {
		logDefault = 4
	}
	if ok {
		bare := false
		for _, d := range strings.Split(v, ",") {
			d = strings.TrimSpace(d)
			if d == "" {
				continue
			}
			if t, l, has := strings.Cut(d, "="); has {
				if lv, ok := parseLevel(l); ok {
					logTargets[t] = lv
				}
			} else if lv, ok := parseLevel(d); ok {
				logDefault = lv
				bare = true
			} else {
				logTargets[d] = 5
			}
		}
		if !bare && !debug {
			logDefault = 0
		}
	}
}

func logEnabled(level int, target string) bool {
	best := -1
	bestLen := -1
	for t, l := range logTargets {
		if target == t || strings.HasPrefix(target, t+"::") {
			if len(t) > bestLen {
				best, bestLen = l, len(t)
			}
		}
	}
	if best < 0 {
		best = logDefault
	}
	return level <= best
}

var levelNames = []string{"", "ERROR", "WARN", "INFO", "DEBUG", "TRACE"}

func logMsg(level int, target, msg string) {
	if !envLogger {
		return
	}
	if !logEnabled(level, target) {
		return
	}
	stdout.Flush()
	fmt.Fprintf(os.Stderr, "[%.6fs %-5s %s] %s\n", time.Since(logStart).Seconds(), levelNames[level], target, msg)
}
EOF
