// h2RoundTrip performs a request over an established TLS connection that
// negotiated HTTP/2, using the standard library's HTTP/2 implementation.
func (hc *httpClient) h2RoundTrip(pc *pconn, req *Request) (*Response, error) {
	u := req.URL
	if hc.h2t == nil {
		used := false
		conn := pc.c
		hc.h2t = &http.Transport{
			ForceAttemptHTTP2: true,
			DialTLSContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
				if !used {
					used = true
					return conn, nil
				}
				// further connections (e.g. redirects to other hosts) go through our own dialer
				pu := u
				npc, _, err := hc.connect(pu)
				if err != nil {
					return nil, err
				}
				return npc.c, nil
			},
			DisableCompression: true,
		}
	}
	h := wireHeaders(req)
	var body io.Reader
	if req.BodyKind != BodyNone {
		body = bytes.NewReader(req.Body)
	}
	hreq, err := http.NewRequest(req.Method, u.String(), body)
	if err != nil {
		return nil, sendErr(u, "client error (SendRequest)", err.Error())
	}
	for _, kv := range h.Pairs() {
		switch kv[0] {
		case "host", "connection", "content-length", "transfer-encoding", "keep-alive", "upgrade":
			if kv[0] == "host" {
				hreq.Host = kv[1]
			}
			continue
		}
		hreq.Header.Add(kv[0], kv[1])
	}
	if req.BodyKind != BodyNone {
		hreq.ContentLength = int64(len(req.Body))
	}
	if !hc.deadline.IsZero() {
		ctx, cancel := context.WithDeadline(context.Background(), hc.deadline)
		defer cancel()
		hreq = hreq.WithContext(ctx)
	}
	start := time.Now()
	hresp, err := hc.h2t.RoundTrip(hreq)
	if err != nil {
		if isTimeout(err) {
			return nil, timeoutErr(u)
		}
		return nil, sendErr(u, "client error (SendRequest)", "http2 error", err.Error())
	}
	resp := &Response{Version: "HTTP/2.0", Status: hresp.StatusCode, Headers: &HeaderMap{}, RemoteAddr: pc.remote, URL: u, isHead: req.Method == "HEAD"}
	resp.Reason = http.StatusText(hresp.StatusCode)
	var names []string
	for k := range hresp.Header {
		names = append(names, k)
	}
	sort.Strings(names)
	for _, k := range names {
		for _, v := range hresp.Header[k] {
			resp.Headers.Append(strings.ToLower(k), v)
		}
	}
	data, err := io.ReadAll(hresp.Body)
	hresp.Body.Close()
	if err != nil {
		return nil, wrapBodyErr(err)
	}
	resp.Body = data
	resp.Elapsed = time.Since(start)
	return resp, nil
}

