// A minimal HTTP/2 client (one request at a time per connection).

const (
	h2FrameData         = 0x0
	h2FrameHeaders      = 0x1
	h2FrameRSTStream    = 0x3
	h2FrameSettings     = 0x4
	h2FramePing         = 0x6
	h2FrameGoAway       = 0x7
	h2FrameWindowUpdate = 0x8
	h2FrameContinuation = 0x9
)

type h2Conn struct {
	c          net.Conn
	br         *bufio.Reader
	enc        *hpack.Encoder
	encBuf     *strings.Builder
	dec        *hpack.Decoder
	nextStream uint32
	sendWindow int64
	streamWin  int64
	initWin    int64
	maxFrame   int
	started    bool
	fields     [][2]string
}

type h2Err struct{ causes []string }

func (e *h2Err) Error() string { return strings.Join(e.causes, ": ") }

func newH2Conn(c net.Conn, br *bufio.Reader) *h2Conn {
	h := &h2Conn{c: c, br: br, nextStream: 1, sendWindow: 65535, initWin: 65535, maxFrame: 16384}
	h.dec = hpack.NewDecoder(4096, func(f hpack.HeaderField) {
		h.fields = append(h.fields, [2]string{f.Name, f.Value})
	})
	return h
}

func (h *h2Conn) writeFrame(typ, flags byte, stream uint32, payload []byte) error {
	hdr := make([]byte, 9, 9+len(payload))
	hdr[0] = byte(len(payload) >> 16)
	hdr[1] = byte(len(payload) >> 8)
	hdr[2] = byte(len(payload))
	hdr[3] = typ
	hdr[4] = flags
	binary.BigEndian.PutUint32(hdr[5:], stream&0x7fffffff)
	_, err := h.c.Write(append(hdr, payload...))
	return err
}

func (h *h2Conn) readFrame() (typ, flags byte, stream uint32, payload []byte, err error) {
	var hdr [9]byte
	if _, err = io.ReadFull(h.br, hdr[:]); err != nil {
		return
	}
	n := int(hdr[0])<<16 | int(hdr[1])<<8 | int(hdr[2])
	typ, flags = hdr[3], hdr[4]
	stream = binary.BigEndian.Uint32(hdr[5:]) & 0x7fffffff
	if n > h.maxFrameRecv() {
		err = &h2Err{[]string{"http2 error", "connection error detected: frame with invalid size"}}
		return
	}
	payload = make([]byte, n)
	_, err = io.ReadFull(h.br, payload)
	return
}

func (h *h2Conn) maxFrameRecv() int { return 16384 }

func (h *h2Conn) start() error {
	if h.started {
		return nil
	}
	h.started = true
	if _, err := h.c.Write([]byte("PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n")); err != nil {
		return err
	}
	// SETTINGS: ENABLE_PUSH=0, INITIAL_WINDOW_SIZE=2MB
	var s []byte
	s = append(s, 0, 2, 0, 0, 0, 0)
	s = append(s, 0, 4, 0, 0x20, 0, 0)
	if err := h.writeFrame(h2FrameSettings, 0, 0, s); err != nil {
		return err
	}
